/** The Solar System (Geography): 214 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"geo-solar-system-1","question":"Which is the largest planet in the Solar System?","options":["Saturn","Jupiter","Neptune","Earth"],"answer":1,"explanation":"Jupiter is the largest planet, about 11 times Earth's diameter and more massive than all the other planets combined. Saturn is second and only looks comparable because of its rings.","difficulty":"easy","questionHi":"सौरमंडल का सबसे बड़ा ग्रह कौन-सा है?","optionsHi":["शनि","बृहस्पति","वरुण","पृथ्वी"],"explanationHi":"बृहस्पति सबसे बड़ा ग्रह है, जिसका व्यास पृथ्वी के व्यास का लगभग 11 गुना है और जिसका द्रव्यमान अन्य सभी ग्रहों के संयुक्त द्रव्यमान से अधिक है। शनि दूसरे स्थान पर है और केवल अपने छल्लों के कारण तुलनीय दिखता है।"},
  {"id":"geo-solar-system-2","question":"Which planet is known as the Red Planet?","options":["Venus","Mars","Jupiter","Mercury"],"answer":1,"explanation":"Iron oxide (rust) in the dust on Mars's surface gives it a red colour. Jupiter's Great Red Spot is just a storm, so it does not make Jupiter the Red Planet.","difficulty":"easy","questionHi":"किस ग्रह को लाल ग्रह कहा जाता है?","optionsHi":["शुक्र","मंगल","बृहस्पति","बुध"],"explanationHi":"मंगल की सतह की धूल में मौजूद आयरन ऑक्साइड (जंग) उसे लाल रंग देता है। बृहस्पति का महान लाल धब्बा केवल एक तूफ़ान है, इसलिए वह बृहस्पति को लाल ग्रह नहीं बनाता।"},
  {"id":"geo-solar-system-3","question":"Which planet is closest to the Sun?","options":["Venus","Neptune","Mercury","Mars"],"answer":2,"explanation":"Mercury orbits closest, at about 58 million km (0.39 AU). Venus comes second but is the hottest planet because of its greenhouse atmosphere, which is why it is the usual wrong pick.","difficulty":"easy","questionHi":"कौन-सा ग्रह सूर्य के सबसे निकट है?","optionsHi":["शुक्र","वरुण","बुध","मंगल"],"explanationHi":"बुध लगभग 58 मिलियन किमी (0.39 AU) पर सूर्य के सबसे निकट परिक्रमा करता है। शुक्र दूसरे स्थान पर है, परंतु अपने ग्रीनहाउस वायुमंडल के कारण सबसे गर्म ग्रह है, इसीलिए वह प्रायः गलत उत्तर के रूप में चुना जाता है।"},
  {"id":"geo-solar-system-4","question":"Which planet is the hottest?","options":["Mercury","Venus","Mars","Jupiter"],"answer":1,"explanation":"Venus is hotter than Mercury because its thick CO₂ atmosphere traps heat.","difficulty":"moderate","questionHi":"कौन-सा ग्रह सबसे गर्म है?","optionsHi":["बुध","शुक्र","मंगल","बृहस्पति"],"explanationHi":"शुक्र बुध से अधिक गर्म है क्योंकि उसका घना CO₂ वायुमंडल ऊष्मा को रोके रखता है।"},
  {"id":"geo-solar-system-5","question":"Which planet has the most prominent ring system?","options":["Jupiter","Saturn","Uranus","Neptune"],"answer":1,"explanation":"Saturn’s rings, made of ice and rock, are the brightest and most extensive.","difficulty":"moderate","questionHi":"किस ग्रह का वलय तंत्र सबसे प्रमुख है?","optionsHi":["बृहस्पति","शनि","अरुण","वरुण"],"explanationHi":"शनि के वलय, जो बर्फ और चट्टान से बने हैं, सबसे चमकीले और सबसे विस्तृत हैं।"},
  {"id":"geo-solar-system-6","question":"Which planet is often called Earth’s twin because of its similar size and mass?","options":["Mars","Venus","Mercury","Neptune"],"answer":1,"explanation":"Venus has about 95% of Earth's diameter and 82% of its mass, hence 'Earth's twin'. Mars resembles Earth in day length and seasons, but it is only about half Earth's size.","difficulty":"moderate","questionHi":"समान आकार और द्रव्यमान के कारण किस ग्रह को प्रायः पृथ्वी का जुड़वाँ कहा जाता है?","optionsHi":["मंगल","शुक्र","बुध","वरुण"],"explanationHi":"शुक्र का व्यास पृथ्वी के व्यास का लगभग 95% और द्रव्यमान 82% है, इसीलिए उसे ‘पृथ्वी का जुड़वाँ’ कहते हैं। मंगल दिन की लंबाई और ऋतुओं में पृथ्वी से मिलता है, परंतु उसका आकार पृथ्वी के लगभग आधे के बराबर ही है।"},
  {"id":"geo-solar-system-7","question":"Which planet rotates almost on its side, with an axial tilt of about 98°?","options":["Saturn","Uranus","Neptune","Mars"],"answer":1,"explanation":"Uranus is tilted about 98°, so it appears to roll along its orbit.","difficulty":"hard","questionHi":"कौन-सा ग्रह लगभग अपनी बगल पर घूमता है, जिसका अक्षीय झुकाव लगभग 98° है?","optionsHi":["शनि","अरुण","वरुण","मंगल"],"explanationHi":"अरुण लगभग 98° झुका हुआ है, इसलिए वह अपनी कक्षा में लुढ़कता हुआ प्रतीत होता है।"},
  {"id":"geo-solar-system-8","question":"Which is the largest natural satellite in the Solar System?","options":["Titan","Ganymede","The Moon","Europa"],"answer":1,"explanation":"Ganymede, a moon of Jupiter, is larger than the planet Mercury.","difficulty":"hard","questionHi":"सौरमंडल का सबसे बड़ा प्राकृतिक उपग्रह कौन-सा है?","optionsHi":["टाइटन","गैनिमीड","चंद्रमा","यूरोपा"],"explanationHi":"गैनिमीड, बृहस्पति का एक चंद्रमा, बुध ग्रह से भी बड़ा है।"},
  {"id":"geo-solar-system-9","question":"Which planet takes the longest to orbit the Sun?","options":["Uranus","Saturn","Neptune","Jupiter"],"answer":2,"explanation":"Neptune, the farthest planet, takes about 165 Earth years for one orbit.","difficulty":"hard","questionHi":"किस ग्रह को सूर्य की परिक्रमा करने में सबसे अधिक समय लगता है?","optionsHi":["अरुण","शनि","वरुण","बृहस्पति"],"explanationHi":"वरुण, सबसे दूर का ग्रह, एक परिक्रमा पूरी करने में लगभग 165 पृथ्वी वर्ष लेता है।"},
  {"id":"geo-solar-system-10","question":"Which planet has the shortest day (fastest rotation)?","options":["Earth","Mars","Jupiter","Mercury"],"answer":2,"explanation":"Jupiter spins once in about 9 h 56 min, the shortest day of any planet. Mercury is the trap: it orbits the Sun fastest but rotates very slowly, once in about 59 Earth days.","difficulty":"very-hard","questionHi":"किस ग्रह का दिन सबसे छोटा है (सबसे तेज़ घूर्णन)?","optionsHi":["पृथ्वी","मंगल","बृहस्पति","बुध"],"explanationHi":"बृहस्पति लगभग 9 घंटे 56 मिनट में एक बार घूर्णन करता है, जो किसी भी ग्रह का सबसे छोटा दिन है। बुध भ्रमित करने वाला विकल्प है: वह सूर्य की परिक्रमा सबसे तेज़ करता है, परंतु बहुत धीमे घूर्णन करता है, लगभग 59 पृथ्वी दिनों में एक बार।"},
  {"id":"geo-solar-system-11","question":"The asteroid belt lies between the orbits of:","options":["Earth and Mars","Mars and Jupiter","Jupiter and Saturn","Venus and Earth"],"answer":1,"explanation":"Most asteroids orbit in the main belt between Mars and Jupiter.","difficulty":"very-hard","questionHi":"क्षुद्रग्रह पट्टी किन कक्षाओं के बीच स्थित है?","optionsHi":["पृथ्वी और मंगल","मंगल और बृहस्पति","बृहस्पति और शनि","शुक्र और पृथ्वी"],"explanationHi":"अधिकांश क्षुद्रग्रह मंगल और बृहस्पति के बीच की मुख्य पट्टी में परिक्रमा करते हैं।"},
  {"id":"geo-solar-system-12","question":"Olympus Mons, the largest volcano in the Solar System, is on:","options":["Venus","Mars","Earth","Io"],"answer":1,"explanation":"Olympus Mons on Mars is about 22 km high, nearly three times the height of Mount Everest.","difficulty":"very-hard","questionHi":"ओलंपस मॉन्स, सौरमंडल का सबसे बड़ा ज्वालामुखी, किस पर स्थित है?","optionsHi":["शुक्र","मंगल","पृथ्वी","आयो"],"explanationHi":"मंगल पर स्थित ओलंपस मॉन्स लगभग 22 किमी ऊँचा है, जो माउंट एवरेस्ट की ऊँचाई का लगभग तीन गुना है।"},
  {"id":"geo-solar-system-13","question":"Which planet is called the “Red Planet”?","options":["Venus","Mars","Jupiter","Saturn"],"answer":1,"explanation":"Iron oxide (rust) in Martian soil and dust gives Mars its reddish colour. Venus looks yellowish-white because of its thick sulphuric-acid clouds, and Jupiter's Red Spot is only a storm.","difficulty":"easy","source":"RRB Group D · SSC CHSL","questionHi":"किस ग्रह को “लाल ग्रह” कहा जाता है?","optionsHi":["शुक्र","मंगल","बृहस्पति","शनि"],"explanationHi":"मंगल की मृदा और धूल में मौजूद आयरन ऑक्साइड (जंग) उसे लाल-सा रंग देता है। शुक्र सल्फ्यूरिक अम्ल के घने बादलों के कारण पीला-सफ़ेद दिखता है, और बृहस्पति का लाल धब्बा केवल एक तूफ़ान है।"},
  {"id":"geo-solar-system-14","question":"The hottest planet in the Solar System is:","options":["Mercury","Venus","Mars","Jupiter"],"answer":1,"explanation":"Venus is hotter than Mercury because its thick CO₂ atmosphere traps heat.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"सौरमंडल का सबसे गर्म ग्रह कौन-सा है?","optionsHi":["बुध","शुक्र","मंगल","बृहस्पति"],"explanationHi":"शुक्र बुध से अधिक गर्म है क्योंकि उसका घना CO₂ वायुमंडल ऊष्मा को रोके रखता है।"},
  {"id":"geo-solar-system-15","question":"Which planet is known as the “Morning Star” or “Evening Star”?","options":["Mercury","Venus","Mars","Jupiter"],"answer":1,"explanation":"Venus is bright enough to be seen just before sunrise or after sunset.","difficulty":"moderate","source":"SSC CHSL · RRB Group D","questionHi":"किस ग्रह को “भोर का तारा” या “सांध्य तारा” कहा जाता है?","optionsHi":["बुध","शुक्र","मंगल","बृहस्पति"],"explanationHi":"शुक्र इतना चमकीला है कि वह सूर्योदय से ठीक पहले या सूर्यास्त के बाद दिखाई दे जाता है।"},
  {"id":"geo-solar-system-16","question":"The largest moon in the Solar System, Ganymede, belongs to:","options":["Saturn","Jupiter","Neptune","Uranus"],"answer":1,"explanation":"Ganymede, a moon of Jupiter, is bigger than the planet Mercury.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"सौरमंडल का सबसे बड़ा चंद्रमा, गैनिमीड, किसका है?","optionsHi":["शनि","बृहस्पति","वरुण","अरुण"],"explanationHi":"गैनिमीड, बृहस्पति का एक चंद्रमा, बुध ग्रह से भी बड़ा है।"},
  {"id":"geo-solar-system-17","question":"Which planet rotates on its side, with an axial tilt of about 98°?","options":["Venus","Saturn","Uranus","Neptune"],"answer":2,"explanation":"Uranus’s extreme tilt means its poles take turns facing the Sun.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"कौन-सा ग्रह अपनी बगल पर घूमता है, जिसका अक्षीय झुकाव लगभग 98° है?","optionsHi":["शुक्र","शनि","अरुण","वरुण"],"explanationHi":"अरुण के अत्यधिक झुकाव का अर्थ है कि उसके ध्रुव बारी-बारी से सूर्य की ओर होते हैं।"},
  {"id":"geo-solar-system-18","question":"Which planet takes the longest to complete one revolution around the Sun?","options":["Jupiter","Saturn","Uranus","Neptune"],"answer":3,"explanation":"Neptune, the farthest planet, takes about 165 Earth years per orbit.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"कौन-सा ग्रह सूर्य की एक परिक्रमा पूरी करने में सबसे अधिक समय लेता है?","optionsHi":["बृहस्पति","शनि","अरुण","वरुण"],"explanationHi":"वरुण, सबसे दूर का ग्रह, प्रति परिक्रमा लगभग 165 पृथ्वी वर्ष लेता है।"},
  {"id":"geo-solar-system-19","question":"Which planets have no natural satellite?","options":["Mercury only","Mercury, Venus and Mars","Mercury and Venus","Mars and Venus"],"answer":2,"explanation":"Mercury and Venus have no moons; Mars has two, Phobos and Deimos.","difficulty":"hard","questionHi":"किन ग्रहों का कोई प्राकृतिक उपग्रह नहीं है?","optionsHi":["केवल बुध","बुध, शुक्र और मंगल","बुध और शुक्र","मंगल और शुक्र"],"explanationHi":"बुध और शुक्र का कोई चंद्रमा नहीं है; मंगल के दो हैं, फोबोस और डीमोस।"},
  {"id":"geo-solar-system-20","question":"The main asteroid belt lies between the orbits of:","options":["Earth and Mars","Mars and Jupiter","Jupiter and Saturn","Neptune and Pluto"],"answer":1,"explanation":"The asteroid belt is between Mars and Jupiter; the Kuiper belt is beyond Neptune.","difficulty":"hard","questionHi":"मुख्य क्षुद्रग्रह पट्टी किन कक्षाओं के बीच स्थित है?","optionsHi":["पृथ्वी और मंगल","मंगल और बृहस्पति","बृहस्पति और शनि","वरुण और प्लूटो"],"explanationHi":"क्षुद्रग्रह पट्टी मंगल और बृहस्पति के बीच है; कुइपर पट्टी वरुण से परे है।"},
  {"id":"geo-solar-system-21","question":"Consider: 1. Venus rotates from east to west. 2. A day on Venus is longer than its year. 3. Venus has the highest surface temperature of any planet. Which are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Venus rotates backwards; it takes about 243 Earth days to rotate and 225 to orbit; its CO₂ atmosphere makes it the hottest.","difficulty":"very-hard","questionHi":"विचार कीजिए: 1. शुक्र पूर्व से पश्चिम की ओर घूर्णन करता है। 2. शुक्र पर एक दिन उसके वर्ष से लंबा होता है। 3. किसी भी ग्रह में शुक्र का सतही तापमान सर्वाधिक है। कौन-से कथन सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"शुक्र उलटी दिशा में घूर्णन करता है; उसे घूर्णन में लगभग 243 पृथ्वी दिन और परिक्रमा में 225 दिन लगते हैं; उसका CO₂ वायुमंडल उसे सबसे गर्म बनाता है।"},
  {"id":"geo-solar-system-22","question":"By Kepler’s third law, a planet 4 times as far from the Sun as Earth takes how many Earth years to orbit?","options":["4","8","16","64"],"answer":1,"explanation":"By Kepler's third law T² ∝ a³, so T = 4^(3/2) = 8 years. Taking T ∝ a gives 4, T ∝ a² gives 16, and forgetting the square root (T ∝ a³) gives 64.","difficulty":"very-hard","questionHi":"केपलर के तृतीय नियम के अनुसार, जो ग्रह सूर्य से पृथ्वी की तुलना में 4 गुना दूर है, वह कितने पृथ्वी वर्षों में परिक्रमा करेगा?","optionsHi":["4","8","16","64"],"explanationHi":"केपलर के तृतीय नियम T² ∝ a³ से, T = 4^(3/2) = 8 वर्ष। T ∝ a लेने पर 4, T ∝ a² लेने पर 16, और वर्गमूल भूलने पर (T ∝ a³) 64 आता है।"},
  {"id":"geo-solar-system-23","question":"How many of these statements are correct? I. Jupiter is the largest planet. II. Saturn’s average density is less than that of water. III. Mercury has the most eccentric orbit of the eight planets. IV. Neptune was the first planet found by mathematical prediction.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct; Neptune was predicted by Le Verrier and Adams before it was seen in 1846.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. बृहस्पति सबसे बड़ा ग्रह है। II. शनि का औसत घनत्व जल के घनत्व से कम है। III. आठ ग्रहों में बुध की कक्षा सबसे अधिक उत्केंद्रीय है। IV. वरुण गणितीय भविष्यवाणी से खोजा गया पहला ग्रह था।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं; वरुण की भविष्यवाणी 1846 में उसे देखे जाने से पहले ले वेरिए और एडम्स ने की थी।"},
  {"id":"geo-solar-system-24","question":"How many of these statements are correct? I. Earth is closest to the Sun in early January. II. Seasons are caused mainly by the change in the Earth–Sun distance. III. Earth’s axis is tilted about 23.5° from the perpendicular to its orbit.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and III. Seasons come from the tilt of the axis, not the distance.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. पृथ्वी जनवरी के आरंभ में सूर्य के सबसे निकट होती है। II. ऋतुएँ मुख्यतः पृथ्वी–सूर्य की दूरी में परिवर्तन के कारण होती हैं। III. पृथ्वी की धुरी उसकी कक्षा के लंब से लगभग 23.5° झुकी हुई है।","optionsHi":["केवल एक","केवल दो","तीनों","कोई नहीं"],"explanationHi":"केवल I और III। ऋतुएँ धुरी के झुकाव से होती हैं, दूरी से नहीं।"},
  {"id":"geo-solar-system-25","question":"How many of these statements are correct? I. Venus rotates from east to west. II. Uranus has an axial tilt of about 98°. III. Mars has no natural satellite.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"I and II are correct: Venus spins retrograde (east to west) and Uranus is tilted about 98°. III is wrong because Mars has two small moons, Phobos and Deimos.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. शुक्र पूर्व से पश्चिम की ओर घूर्णन करता है। II. अरुण का अक्षीय झुकाव लगभग 98° है। III. मंगल का कोई प्राकृतिक उपग्रह नहीं है।","optionsHi":["केवल एक","केवल दो","सभी तीन","कोई नहीं"],"explanationHi":"I और II सही हैं: शुक्र वक्री (पूर्व से पश्चिम) घूर्णन करता है और अरुण लगभग 98° झुका है। III गलत है क्योंकि मंगल के दो छोटे चंद्रमा हैं, फोबोस और डीमोस।"},
  {"id":"geo-solar-system-26","question":"The Earth is closest to the Sun (perihelion) around:","options":["3 January","4 July","21 June","22 December"],"answer":0,"explanation":"Perihelion falls around 3 January and aphelion around 4 July. Seasons come from the axial tilt, not distance.","difficulty":"very-hard","questionHi":"पृथ्वी सूर्य के सबसे निकट (उपसौर) लगभग कब होती है?","optionsHi":["3 जनवरी","4 जुलाई","21 जून","22 दिसंबर"],"explanationHi":"उपसौर लगभग 3 जनवरी को और अपसौर लगभग 4 जुलाई को पड़ता है। ऋतुएँ अक्षीय झुकाव से होती हैं, दूरी से नहीं।"},
  {"id":"geo-solar-system-27","question":"Assertion (A): The outer planets have much lower densities than the inner planets. Reason (R): The outer planets are made mostly of light gases such as hydrogen and helium.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Saturn’s density is even less than water’s, because the giants are mostly hydrogen and helium.","difficulty":"very-hard","questionHi":"अभिकथन (A): बाह्य ग्रहों का घनत्व आंतरिक ग्रहों से बहुत कम है। कारण (R): बाह्य ग्रह मुख्यतः हाइड्रोजन और हीलियम जैसी हल्की गैसों से बने हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"शनि का घनत्व जल से भी कम है, क्योंकि विशाल ग्रह मुख्यतः हाइड्रोजन और हीलियम से बने हैं।"},
  {"id":"geo-solar-system-28","question":"Arrange these planets in order of size, largest first: 1. Neptune 2. Saturn 3. Uranus 4. Earth","options":["2-3-1-4","2-1-3-4","1-2-3-4","2-3-4-1"],"answer":0,"explanation":"Saturn (about 9 Earth radii), then Uranus, which is slightly larger than Neptune though less massive, then Earth.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"इन ग्रहों को आकार के क्रम में व्यवस्थित कीजिए, सबसे बड़े से शुरू करके: 1. वरुण 2. शनि 3. अरुण 4. पृथ्वी","optionsHi":["2-3-1-4","2-1-3-4","1-2-3-4","2-3-4-1"],"explanationHi":"शनि (लगभग 9 पृथ्वी त्रिज्याएँ), फिर अरुण, जो वरुण से थोड़ा बड़ा है यद्यपि कम द्रव्यमान वाला है, फिर पृथ्वी।"},
  {"id":"geo-solar-system-29","question":"Assertion (A): Mercury has the largest difference between day and night temperatures of any planet. Reason (R): Mercury has almost no atmosphere to retain heat.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Without an atmosphere, heat absorbed by day escapes at night, so the surface swings from about 430 °C to −180 °C.","difficulty":"very-hard","questionHi":"अभिकथन (A): किसी भी ग्रह की तुलना में बुध पर दिन और रात के तापमान का अंतर सबसे अधिक है। कारण (R): बुध पर ऊष्मा को रोके रखने के लिए लगभग कोई वायुमंडल नहीं है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"वायुमंडल के अभाव में दिन में अवशोषित ऊष्मा रात में निकल जाती है, इसलिए सतह का तापमान लगभग 430 °C से −180 °C तक बदलता है।"},
  {"id":"geo-solar-system-30","question":"Which is the smallest planet in the Solar System?","options":["Mars","Mercury","Ganymede","Pluto"],"answer":1,"explanation":"Mercury (diameter about 4,880 km) is the smallest of the eight planets. Pluto is smaller but is a dwarf planet, and Ganymede, though larger than Mercury, is a moon of Jupiter.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"सौरमंडल का सबसे छोटा ग्रह कौन-सा है?","optionsHi":["मंगल","बुध","गैनिमीड","प्लूटो"],"explanationHi":"बुध (व्यास लगभग 4,880 किमी) आठ ग्रहों में सबसे छोटा है। प्लूटो उससे छोटा है पर वह एक बौना ग्रह है, और गैनिमीड, बुध से बड़ा होने पर भी, बृहस्पति का चंद्रमा है।"},
  {"id":"geo-solar-system-31","question":"The Sun is made up mainly of which two elements?","options":["Oxygen and nitrogen","Hydrogen and helium","Carbon and oxygen","Helium and neon"],"answer":1,"explanation":"About 73% of the Sun’s mass is hydrogen and about 25% helium; hydrogen fuses into helium in its core.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"सूर्य मुख्यतः किन दो तत्वों से बना है?","optionsHi":["ऑक्सीजन और नाइट्रोजन","हाइड्रोजन और हीलियम","कार्बन और ऑक्सीजन","हीलियम और नियॉन"],"explanationHi":"सूर्य के द्रव्यमान का लगभग 73% हाइड्रोजन और लगभग 25% हीलियम है; उसके क्रोड में हाइड्रोजन का संलयन होकर हीलियम बनता है।"},
  {"id":"geo-solar-system-32","question":"Which planet is called the “Blue Planet”?","options":["Neptune","Uranus","Earth","Venus"],"answer":2,"explanation":"Earth is the Blue Planet because about 71% of its surface is covered by water; Neptune also looks blue but is the “ice giant”.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"किस ग्रह को “नीला ग्रह” कहा जाता है?","optionsHi":["वरुण","अरुण","पृथ्वी","शुक्र"],"explanationHi":"पृथ्वी नीला ग्रह है क्योंकि उसकी लगभग 71% सतह जल से ढकी है; वरुण भी नीला दिखता है, परंतु वह “हिम दानव” है।"},
  {"id":"geo-solar-system-33","question":"The Great Red Spot, a storm larger than the Earth, is found on:","options":["Mars","Saturn","Jupiter","Neptune"],"answer":2,"explanation":"The Great Red Spot is a giant anticyclonic storm in Jupiter’s atmosphere that has been observed for over 150 years.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"महान लाल धब्बा, जो पृथ्वी से भी बड़ा एक तूफ़ान है, किस पर पाया जाता है?","optionsHi":["मंगल","शनि","बृहस्पति","वरुण"],"explanationHi":"महान लाल धब्बा बृहस्पति के वायुमंडल में एक विशाल प्रतिचक्रवाती तूफ़ान है जिसे 150 वर्षों से अधिक समय से देखा जा रहा है।"},
  {"id":"geo-solar-system-34","question":"The dwarf planet Pluto lies in which region of the Solar System?","options":["The asteroid belt","The Kuiper belt","The Oort cloud","Between Jupiter and Saturn"],"answer":1,"explanation":"Pluto is the best-known member of the Kuiper belt, a ring of icy bodies beyond Neptune; the Oort cloud lies much farther out.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"बौना ग्रह प्लूटो सौरमंडल के किस क्षेत्र में स्थित है?","optionsHi":["क्षुद्रग्रह पट्टी","कुइपर पट्टी","ऊर्ट बादल","बृहस्पति और शनि के बीच"],"explanationHi":"प्लूटो कुइपर पट्टी का सबसे प्रसिद्ध सदस्य है, जो वरुण से परे बर्फीले पिंडों का एक छल्ला है; ऊर्ट बादल बहुत अधिक दूर है।"},
  {"id":"geo-solar-system-35","question":"Titan, the only moon known to have a thick nitrogen-rich atmosphere, orbits:","options":["Jupiter","Neptune","Uranus","Saturn"],"answer":3,"explanation":"Titan is Saturn’s largest moon; its dense atmosphere is mostly nitrogen with methane clouds and lakes.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"टाइटन, एकमात्र ज्ञात चंद्रमा जिसका वायुमंडल घना और नाइट्रोजन-समृद्ध है, किसकी परिक्रमा करता है?","optionsHi":["बृहस्पति","वरुण","अरुण","शनि"],"explanationHi":"टाइटन शनि का सबसे बड़ा चंद्रमा है; उसका घना वायुमंडल मुख्यतः नाइट्रोजन का है, जिसमें मीथेन के बादल और झीलें हैं।"},
  {"id":"geo-solar-system-36","question":"Phobos and Deimos are the two natural satellites of:","options":["Mars","Venus","Mercury","Neptune"],"answer":0,"explanation":"Mars has two small, irregular moons, Phobos and Deimos; Venus and Mercury have none.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"फोबोस और डीमोस किसके दो प्राकृतिक उपग्रह हैं?","optionsHi":["मंगल","शुक्र","बुध","वरुण"],"explanationHi":"मंगल के दो छोटे, अनियमित आकार के चंद्रमा हैं, फोबोस और डीमोस; शुक्र और बुध के कोई चंद्रमा नहीं हैं।"},
  {"id":"geo-solar-system-37","question":"Sunlight takes approximately how long to reach the Earth?","options":["8 min 20 s","1.3 s","80 min","8 h 20 min"],"answer":0,"explanation":"Earth is about 150 million km from the Sun; at 3 × 10⁸ m/s light covers that in about 500 s, i.e. 8 min 20 s. About 1.3 s is the travel time of light from the Moon, a common mix-up.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"सूर्य का प्रकाश पृथ्वी तक पहुँचने में लगभग कितना समय लेता है?","optionsHi":["8 मिनट 20 सेकंड","1.3 सेकंड","80 मिनट","8 घंटे 20 मिनट"],"explanationHi":"पृथ्वी सूर्य से लगभग 150 मिलियन किमी दूर है; 3 × 10⁸ m/s की चाल से प्रकाश यह दूरी लगभग 500 सेकंड, अर्थात 8 मिनट 20 सेकंड में तय करता है। लगभग 1.3 सेकंड चंद्रमा से प्रकाश के आने का समय है, जो एक सामान्य भ्रम है।"},
  {"id":"geo-solar-system-38","question":"The “Goldilocks zone” of a star is the region where:","options":["Asteroids are most densely concentrated","Surface water can stay liquid","Comets originate and are stored","The star's magnetic field is strongest"],"answer":1,"explanation":"The habitable (Goldilocks) zone is the band of distances where a planet is neither too hot nor too cold for liquid water; Earth lies in the Sun’s habitable zone.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"किसी तारे का “गोल्डीलॉक्स क्षेत्र” वह क्षेत्र है जहाँ:","optionsHi":["क्षुद्रग्रह सबसे सघन रूप से केंद्रित होते हैं","सतह पर जल द्रव अवस्था में रह सकता है","धूमकेतुओं की उत्पत्ति और भंडारण होता है","तारे का चुंबकीय क्षेत्र सबसे प्रबल होता है"],"explanationHi":"आवासीय (गोल्डीलॉक्स) क्षेत्र दूरियों की वह पट्टी है जहाँ कोई ग्रह द्रव जल के लिए न बहुत गर्म होता है, न बहुत ठंडा; पृथ्वी सूर्य के आवासीय क्षेत्र में स्थित है।"},
  {"id":"geo-solar-system-39","question":"Io, the most volcanically active body in the Solar System, is a moon of:","options":["Saturn","Jupiter","Neptune","Mars"],"answer":1,"explanation":"Io is one of Jupiter’s four Galilean moons; tidal heating by Jupiter drives its hundreds of active volcanoes.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"आयो, सौरमंडल का सबसे अधिक ज्वालामुखीय सक्रियता वाला पिंड, किसका चंद्रमा है?","optionsHi":["शनि","बृहस्पति","वरुण","मंगल"],"explanationHi":"आयो बृहस्पति के चार गैलीलियन चंद्रमाओं में से एक है; बृहस्पति द्वारा ज्वारीय तापन उसके सैकड़ों सक्रिय ज्वालामुखियों को संचालित करता है।"},
  {"id":"geo-solar-system-40","question":"Halley’s Comet returns to the inner Solar System roughly once every:","options":["11 years","33 years","76 years","150 years"],"answer":2,"explanation":"Halley’s Comet has a period of about 75–76 years; it last appeared in 1986 and is expected again in 2061.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"हैली धूमकेतु आंतरिक सौरमंडल में लगभग कितने वर्षों में एक बार लौटता है?","optionsHi":["11 वर्ष","33 वर्ष","76 वर्ष","150 वर्ष"],"explanationHi":"हैली धूमकेतु की आवर्तकाल लगभग 75–76 वर्ष है; यह अंतिम बार 1986 में दिखाई दिया था और 2061 में पुनः अपेक्षित है।"},
  {"id":"geo-solar-system-41","question":"Ceres, the largest object in the asteroid belt, is officially classified as a:","options":["Comet","Dwarf planet","Meteoroid","Natural satellite"],"answer":1,"explanation":"Since the IAU definition of 2006, Ceres is a dwarf planet, the only one in the asteroid belt; Pluto, Eris, Haumea and Makemake are the others.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"सेरेस, क्षुद्रग्रह पट्टी का सबसे बड़ा पिंड, आधिकारिक रूप से किस रूप में वर्गीकृत है?","optionsHi":["धूमकेतु","बौना ग्रह","उल्कापिंड (मीटियोरॉयड)","प्राकृतिक उपग्रह"],"explanationHi":"2006 की IAU परिभाषा के बाद से सेरेस एक बौना ग्रह है, जो क्षुद्रग्रह पट्टी में एकमात्र है; प्लूटो, एरिस, हाउमिया और माकेमाके अन्य हैं।"},
  {"id":"geo-solar-system-42","question":"Which planet has the highest escape velocity?","options":["Saturn","Earth","Neptune","Jupiter"],"answer":3,"explanation":"Jupiter’s huge mass gives it an escape velocity of about 59.5 km/s, compared with 11.2 km/s for Earth and about 35 km/s for Saturn.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"किस ग्रह का पलायन वेग सबसे अधिक है?","optionsHi":["शनि","पृथ्वी","वरुण","बृहस्पति"],"explanationHi":"बृहस्पति के विशाल द्रव्यमान के कारण उसका पलायन वेग लगभग 59.5 km/s है, जबकि पृथ्वी का 11.2 km/s और शनि का लगभग 35 km/s है।"},
  {"id":"geo-solar-system-43","question":"The Solar System lies in which arm of the Milky Way galaxy?","options":["Perseus arm","Orion arm","Sagittarius arm","Norma arm"],"answer":1,"explanation":"The Sun sits on the inner edge of the Orion (Orion–Cygnus) arm, a minor spiral arm about 26,000 light-years from the galactic centre.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"सौरमंडल आकाशगंगा (मिल्की वे) की किस भुजा में स्थित है?","optionsHi":["पर्सियस भुजा","ओरायन भुजा","सैजिटेरियस भुजा","नॉर्मा भुजा"],"explanationHi":"सूर्य ओरायन (ओरायन–सिग्नस) भुजा के भीतरी किनारे पर स्थित है, जो एक छोटी सर्पिल भुजा है और गैलेक्टिक केंद्र से लगभग 26,000 प्रकाश-वर्ष दूर है।"},
  {"id":"geo-solar-system-44","question":"Triton, a large moon that orbits its planet in the retrograde direction, belongs to:","options":["Uranus","Saturn","Neptune","Jupiter"],"answer":2,"explanation":"Triton is Neptune’s largest moon and the only large moon with a retrograde orbit, suggesting it was captured from the Kuiper belt.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"ट्राइटन, एक बड़ा चंद्रमा जो अपने ग्रह की वक्री दिशा में परिक्रमा करता है, किसका है?","optionsHi":["अरुण","शनि","वरुण","बृहस्पति"],"explanationHi":"ट्राइटन वरुण का सबसे बड़ा चंद्रमा है और वक्री कक्षा वाला एकमात्र बड़ा चंद्रमा है, जिससे संकेत मिलता है कि उसे कुइपर पट्टी से पकड़ा गया था।"},
  {"id":"geo-solar-system-45","question":"Mercury completes one rotation on its axis in about:","options":["24 hours","59 Earth days","88 Earth days","243 Earth days"],"answer":1,"explanation":"Mercury rotates once in about 58.6 Earth days and orbits the Sun in 88 days (a 3:2 spin–orbit resonance); 243 days is the rotation period of Venus.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"बुध अपनी धुरी पर एक घूर्णन लगभग कितने समय में पूरा करता है?","optionsHi":["24 घंटे","59 पृथ्वी दिन","88 पृथ्वी दिन","243 पृथ्वी दिन"],"explanationHi":"बुध लगभग 58.6 पृथ्वी दिनों में एक बार घूर्णन करता है और 88 दिनों में सूर्य की परिक्रमा करता है (3:2 घूर्णन–कक्षा अनुनाद); 243 दिन शुक्र का घूर्णन काल है।"},
  {"id":"geo-solar-system-46","question":"According to Kepler’s second law, a planet moves fastest in its orbit when it is:","options":["Farthest from the Sun","Nearest to the Sun","Crossing the ecliptic","At the equinox"],"answer":1,"explanation":"Kepler’s law of areas means a planet sweeps equal areas in equal times, so its speed is greatest at perihelion (nearest the Sun) and least at aphelion.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"केपलर के द्वितीय नियम के अनुसार, कोई ग्रह अपनी कक्षा में सबसे तेज़ कब चलता है?","optionsHi":["जब वह सूर्य से सबसे दूर हो","जब वह सूर्य के सबसे निकट हो","जब वह क्रांतिवृत्त को पार कर रहा हो","जब विषुव हो"],"explanationHi":"केपलर के क्षेत्रफल के नियम का अर्थ है कि ग्रह समान समय में समान क्षेत्रफल घेरता है, इसलिए उसकी चाल उपसौर (सूर्य के निकटतम) पर सर्वाधिक और अपसौर पर न्यूनतम होती है।"},
  {"id":"geo-solar-system-47","question":"Among the planets, the one with the highest albedo (reflecting the largest fraction of sunlight) is:","options":["Earth","Mars","Venus","Mercury"],"answer":2,"explanation":"Venus’s unbroken cover of sulphuric-acid clouds reflects about 70–75% of sunlight, which is why it is the brightest planet in our sky; Mercury reflects only about 12%.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"ग्रहों में सबसे अधिक एल्बीडो (सूर्य के प्रकाश के सबसे बड़े अंश का परावर्तन) किसका है?","optionsHi":["पृथ्वी","मंगल","शुक्र","बुध"],"explanationHi":"शुक्र का सल्फ्यूरिक अम्ल के बादलों का अटूट आवरण लगभग 70–75% सूर्य प्रकाश को परावर्तित करता है, इसीलिए वह हमारे आकाश का सबसे चमकीला ग्रह है; बुध केवल लगभग 12% परावर्तित करता है।"},
  {"id":"geo-solar-system-48","question":"How many of these statements are correct? I. Jupiter has the strongest magnetic field of all the planets. II. Saturn has the lowest mean density of all the planets. III. Uranus was discovered by William Herschel in 1781. IV. Mars has two natural satellites.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Jupiter’s magnetic field is the strongest, Saturn’s density (about 0.69 g/cm³) is the lowest, Herschel found Uranus in 1781, and Mars has two moons, Phobos and Deimos.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. सभी ग्रहों में बृहस्पति का चुंबकीय क्षेत्र सबसे प्रबल है। II. सभी ग्रहों में शनि का माध्य घनत्व सबसे कम है। III. अरुण की खोज विलियम हर्शल ने 1781 में की थी। IV. मंगल के दो प्राकृतिक उपग्रह हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। बृहस्पति का चुंबकीय क्षेत्र सबसे प्रबल है, शनि का घनत्व (लगभग 0.69 g/cm³) सबसे कम है, हर्शल ने 1781 में अरुण की खोज की, और मंगल के दो चंद्रमा हैं, फोबोस और डीमोस।"},
  {"id":"geo-solar-system-49","question":"Assertion (A): Venus is hotter than Mercury even though it is farther from the Sun. Reason (R): Venus has a dense carbon-dioxide atmosphere that traps heat through a runaway greenhouse effect.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Venus’s surface stays near 465 °C day and night because its thick CO₂ atmosphere (about 92 times Earth’s pressure) traps heat, whereas airless Mercury radiates heat away quickly.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"अभिकथन (A): शुक्र बुध से अधिक गर्म है, यद्यपि वह सूर्य से अधिक दूर है। कारण (R): शुक्र का घना कार्बन डाइऑक्साइड वायुमंडल अनियंत्रित ग्रीनहाउस प्रभाव द्वारा ऊष्मा को रोके रखता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"शुक्र की सतह दिन और रात दोनों में लगभग 465 °C पर रहती है क्योंकि उसका घना CO₂ वायुमंडल (पृथ्वी के दाब का लगभग 92 गुना) ऊष्मा को रोकता है, जबकि वायुमंडल-विहीन बुध ऊष्मा को तेज़ी से विकीर्ण कर देता है।"},
  {"id":"geo-solar-system-50","question":"Match the moon with its planet: 1. Titan 2. Europa 3. Triton 4. Phobos; a. Mars b. Neptune c. Saturn d. Jupiter","options":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-c, 2-b, 3-d, 4-a","1-b, 2-d, 3-c, 4-a"],"answer":0,"explanation":"Titan orbits Saturn, Europa is a Galilean moon of Jupiter, Triton is Neptune’s retrograde moon and Phobos is the larger moon of Mars.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"चंद्रमा का उसके ग्रह से मिलान कीजिए: 1. टाइटन 2. यूरोपा 3. ट्राइटन 4. फोबोस; a. मंगल b. वरुण c. शनि d. बृहस्पति","optionsHi":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-c, 2-b, 3-d, 4-a","1-b, 2-d, 3-c, 4-a"],"explanationHi":"टाइटन शनि की परिक्रमा करता है, यूरोपा बृहस्पति का गैलीलियन चंद्रमा है, ट्राइटन वरुण का वक्री चंद्रमा है और फोबोस मंगल का बड़ा चंद्रमा है।"},
  {"id":"geo-solar-system-51","question":"A planet takes 8 Earth years to orbit the Sun. By Kepler’s third law, its mean distance from the Sun is about:","options":["2 AU","4 AU","8 AU","16 AU"],"answer":1,"explanation":"T² = a³ (T in years, a in AU): 8² = 64 = a³, so a = 4 AU. Choosing 8 AU ignores the square–cube relation.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"एक ग्रह सूर्य की परिक्रमा 8 पृथ्वी वर्षों में करता है। केपलर के तृतीय नियम से, उसकी सूर्य से माध्य दूरी लगभग है:","optionsHi":["2 AU","4 AU","8 AU","16 AU"],"explanationHi":"T² = a³ (T वर्षों में, a AU में): 8² = 64 = a³, अतः a = 4 AU। 8 AU चुनना वर्ग–घन संबंध की उपेक्षा करना है।"},
  {"id":"geo-solar-system-52","question":"Which of the following planets does NOT have a ring system?","options":["Uranus","Neptune","Mars","Jupiter"],"answer":2,"explanation":"Jupiter, Saturn, Uranus and Neptune all have rings (Jupiter’s and Neptune’s are faint). Mars, a terrestrial planet, has no rings.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"निम्नलिखित में से किस ग्रह का वलय तंत्र नहीं है?","optionsHi":["अरुण","वरुण","मंगल","बृहस्पति"],"explanationHi":"बृहस्पति, शनि, अरुण और वरुण, सभी के वलय हैं (बृहस्पति और वरुण के धुँधले हैं)। मंगल, एक पार्थिव ग्रह, के कोई वलय नहीं हैं।"},
  {"id":"geo-solar-system-53","question":"How many of these statements about the Earth are correct? I. Earth moves around the Sun at about 30 km/s. II. Earth’s sidereal rotation period is exactly 24 hours. III. Earth is the second-densest planet, after Mercury. IV. Earth’s mean distance from the Sun is about 108 million km.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I is correct (orbital speed about 29.8 km/s). The sidereal day is about 23 h 56 min; Earth (5.51 g/cm³) is the densest planet, ahead of Mercury; and its mean distance is about 150 million km, 108 million km being Venus’s.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"पृथ्वी के बारे में इनमें से कितने कथन सही हैं? I. पृथ्वी सूर्य की परिक्रमा लगभग 30 km/s की चाल से करती है। II. पृथ्वी का नक्षत्र घूर्णन काल ठीक 24 घंटे है। III. पृथ्वी, बुध के बाद, दूसरा सबसे घना ग्रह है। IV. पृथ्वी की सूर्य से माध्य दूरी लगभग 108 मिलियन किमी है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I सही है (कक्षीय चाल लगभग 29.8 km/s)। नक्षत्र दिवस लगभग 23 घंटे 56 मिनट का है; पृथ्वी (5.51 g/cm³) बुध से आगे सबसे घना ग्रह है; और उसकी माध्य दूरी लगभग 150 मिलियन किमी है, 108 मिलियन किमी शुक्र की है।"},
  {"id":"geo-solar-system-54","question":"Arrange these bodies in the order in which they were discovered, earliest first: 1. Neptune 2. Uranus 3. Pluto 4. Ceres","options":["2, 4, 1, 3","2, 1, 4, 3","4, 2, 1, 3","2, 1, 3, 4"],"answer":0,"explanation":"Uranus was found in 1781 (Herschel), Ceres in 1801 (Piazzi), Neptune in 1846 (Galle, from Le Verrier’s prediction) and Pluto in 1930 (Tombaugh).","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"इन पिंडों को उनकी खोज के क्रम में व्यवस्थित कीजिए, सबसे पहले वाले से शुरू करके: 1. वरुण 2. अरुण 3. प्लूटो 4. सेरेस","optionsHi":["2, 4, 1, 3","2, 1, 4, 3","4, 2, 1, 3","2, 1, 3, 4"],"explanationHi":"अरुण की खोज 1781 में (हर्शल), सेरेस की 1801 में (पियाज़ी), वरुण की 1846 में (गाले, ले वेरिए की भविष्यवाणी से) और प्लूटो की 1930 में (टॉमबॉ) हुई।"},
  {"id":"geo-solar-system-55","question":"How many of these statements about the Sun are correct? I. The Sun is a G-type main-sequence star. II. The Sun produces its energy by nuclear fusion of hydrogen into helium. III. The photosphere is the visible surface of the Sun. IV. The corona is far hotter than the photosphere.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The Sun is a G-type main-sequence star powered by fusing hydrogen into helium; the photosphere (about 5,800 K) is its visible surface, and the corona reaches over a million kelvin.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"सूर्य के बारे में इनमें से कितने कथन सही हैं? I. सूर्य एक G-प्रकार का मुख्य अनुक्रम तारा है। II. सूर्य हाइड्रोजन के हीलियम में नाभिकीय संलयन से अपनी ऊर्जा उत्पन्न करता है। III. प्रकाशमंडल सूर्य की दृश्य सतह है। IV. कोरोना प्रकाशमंडल से कहीं अधिक गर्म है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। सूर्य एक G-प्रकार का मुख्य अनुक्रम तारा है जो हाइड्रोजन को हीलियम में संलयित करके ऊर्जा पाता है; प्रकाशमंडल (लगभग 5,800 K) उसकी दृश्य सतह है, और कोरोना दस लाख केल्विन से भी अधिक तक पहुँचता है।"},
  {"id":"geo-solar-system-56","question":"Which planet completed its first full orbit of the Sun since its discovery only in 2011?","options":["Uranus","Neptune","Pluto","Saturn"],"answer":1,"explanation":"Neptune was discovered in 1846 and takes about 165 years to orbit the Sun, so it finished its first observed orbit in July 2011; Uranus (84-year orbit, found 1781) had done so long before.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"किस ग्रह ने अपनी खोज के बाद सूर्य की अपनी पहली पूरी परिक्रमा केवल 2011 में पूरी की?","optionsHi":["अरुण","वरुण","प्लूटो","शनि"],"explanationHi":"वरुण की खोज 1846 में हुई थी और वह सूर्य की परिक्रमा में लगभग 165 वर्ष लेता है, इसलिए उसने अपनी पहली देखी गई परिक्रमा जुलाई 2011 में पूरी की; अरुण (84 वर्ष की कक्षा, खोज 1781) यह बहुत पहले कर चुका था।"},
  {"id":"geo-solar-system-57","question":"Match the region with the body associated with it: 1. Oort cloud 2. Kuiper belt 3. Main asteroid belt 4. Trojan asteroids; a. Ceres b. Jupiter’s orbit c. Long-period comets d. Pluto","options":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-b, 2-d, 3-a, 4-c"],"answer":0,"explanation":"Long-period comets come from the distant Oort cloud, Pluto lies in the Kuiper belt, Ceres is the largest body of the main belt, and the Trojans share Jupiter’s orbit at its Lagrange points.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"क्षेत्र का उससे संबद्ध पिंड से मिलान कीजिए: 1. ऊर्ट बादल 2. कुइपर पट्टी 3. मुख्य क्षुद्रग्रह पट्टी 4. ट्रोजन क्षुद्रग्रह; a. सेरेस b. बृहस्पति की कक्षा c. दीर्घ-आवर्तकाल वाले धूमकेतु d. प्लूटो","optionsHi":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-b, 2-d, 3-a, 4-c"],"explanationHi":"दीर्घ-आवर्तकाल वाले धूमकेतु दूरस्थ ऊर्ट बादल से आते हैं, प्लूटो कुइपर पट्टी में है, सेरेस मुख्य पट्टी का सबसे बड़ा पिंड है, और ट्रोजन बृहस्पति की कक्षा में उसके लैग्रेंज बिंदुओं पर स्थित हैं।"},
  {"id":"geo-solar-system-58","question":"How many of these statements are correct? I. Titan is larger than the planet Mercury. II. Ganymede is larger than the planet Mercury. III. Earth’s Moon is the fourth-largest moon in the Solar System. IV. Europa is larger than Earth’s Moon.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct: Ganymede (5,268 km) and Titan (5,150 km) exceed Mercury (4,880 km). The Moon is the fifth-largest, after Ganymede, Titan, Callisto and Io, and Europa (3,120 km) is smaller than the Moon (3,474 km).","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. टाइटन बुध ग्रह से बड़ा है। II. गैनिमीड बुध ग्रह से बड़ा है। III. पृथ्वी का चंद्रमा सौरमंडल का चौथा सबसे बड़ा चंद्रमा है। IV. यूरोपा पृथ्वी के चंद्रमा से बड़ा है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं: गैनिमीड (5,268 किमी) और टाइटन (5,150 किमी) बुध (4,880 किमी) से बड़े हैं। चंद्रमा गैनिमीड, टाइटन, कैलिस्टो और आयो के बाद पाँचवाँ सबसे बड़ा है, और यूरोपा (3,120 किमी) चंद्रमा (3,474 किमी) से छोटा है।"},
  {"id":"geo-solar-system-59","question":"Assertion (A): A sidereal day on Venus is longer than its year. Reason (R): Venus rotates once in about 243 Earth days but completes an orbit of the Sun in about 225 Earth days.","options":["A is true but R is false","Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is false but R is true"],"answer":1,"explanation":"Because the rotation period (243 days) exceeds the orbital period (225 days), one spin takes longer than one orbit; the slow retrograde rotation stated in R is exactly the reason.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"अभिकथन (A): शुक्र पर एक नक्षत्र दिवस उसके वर्ष से लंबा होता है। कारण (R): शुक्र लगभग 243 पृथ्वी दिनों में एक बार घूर्णन करता है, परंतु सूर्य की परिक्रमा लगभग 225 पृथ्वी दिनों में पूरी करता है।","optionsHi":["A सत्य है, परंतु R असत्य है","A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A असत्य है, परंतु R सत्य है"],"explanationHi":"क्योंकि घूर्णन काल (243 दिन) कक्षीय काल (225 दिन) से अधिक है, इसलिए एक घूर्णन एक परिक्रमा से अधिक समय लेता है; R में बताया गया धीमा वक्री घूर्णन ही इसका ठीक-ठीक कारण है।"},
  {"id":"geo-solar-system-60","question":"Since the 2006 decision of the International Astronomical Union, how many planets does the Solar System have?","options":["9","8","12","13"],"answer":1,"explanation":"There are eight planets: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus and Neptune. Nine is the pre-2006 count with Pluto, 12 was the rejected 2006 draft (adding Ceres, Charon and Eris), and 13 wrongly adds the five dwarf planets.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"अंतर्राष्ट्रीय खगोलीय संघ के 2006 के निर्णय के बाद से सौरमंडल में कितने ग्रह हैं?","optionsHi":["9","8","12","13"],"explanationHi":"आठ ग्रह हैं: बुध, शुक्र, पृथ्वी, मंगल, बृहस्पति, शनि, अरुण और वरुण। नौ प्लूटो सहित 2006 से पूर्व की गिनती है, 12 अस्वीकृत 2006 का प्रारूप था (जिसमें सेरेस, शेरन और एरिस जोड़े गए थे), और 13 गलत ढंग से पाँचों बौने ग्रहों को जोड़ देता है।"},
  {"id":"geo-solar-system-61","question":"The mean distance between the Earth and the Sun, called one astronomical unit (AU), is about:","options":["384,400 km","15 million km","150 million km","1.5 billion km"],"answer":2,"explanation":"1 AU ≈ 1.5 × 10⁸ km, i.e. about 150 million km. 384,400 km is the Earth–Moon distance.","difficulty":"easy","source":"SSC GD · RRB Group D","questionHi":"पृथ्वी और सूर्य के बीच की माध्य दूरी, जिसे एक खगोलीय इकाई (AU) कहते हैं, लगभग है:","optionsHi":["384,400 किमी","15 मिलियन किमी","150 मिलियन किमी","1.5 बिलियन किमी"],"explanationHi":"1 AU ≈ 1.5 × 10⁸ किमी, अर्थात लगभग 150 मिलियन किमी। 384,400 किमी पृथ्वी–चंद्रमा की दूरी है।"},
  {"id":"geo-solar-system-62","question":"Mars looks reddish because its surface rocks and dust are rich in:","options":["Sulphur","Copper sulphate","Carbon dust","Iron oxide"],"answer":3,"explanation":"Iron oxide (rust) in the Martian soil and dust gives the planet its red colour, hence the name “Red Planet”.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"मंगल लाल-सा दिखता है क्योंकि उसकी सतह की चट्टानें और धूल किसमें समृद्ध हैं?","optionsHi":["सल्फर","कॉपर सल्फेट","कार्बन धूल","आयरन ऑक्साइड"],"explanationHi":"मंगल की मृदा और धूल में आयरन ऑक्साइड (जंग) ग्रह को उसका लाल रंग देता है, इसीलिए उसका नाम “लाल ग्रह” है।"},
  {"id":"geo-solar-system-63","question":"In which year did the International Astronomical Union reclassify Pluto as a dwarf planet?","options":["2001","2011","2006","1996"],"answer":2,"explanation":"At its Prague General Assembly in August 2006 the IAU defined a planet, and Pluto, which has not cleared its orbital neighbourhood, became a dwarf planet.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"अंतर्राष्ट्रीय खगोलीय संघ ने प्लूटो को किस वर्ष बौना ग्रह के रूप में पुनर्वर्गीकृत किया?","optionsHi":["2001","2011","2006","1996"],"explanationHi":"अगस्त 2006 की अपनी प्राग महासभा में IAU ने ग्रह की परिभाषा तय की, और प्लूटो, जिसने अपनी कक्षीय परिधि को साफ़ नहीं किया है, बौना ग्रह बन गया।"},
  {"id":"geo-solar-system-64","question":"The Earth’s axis of rotation is tilted from the perpendicular to its orbital plane by about:","options":["0°","23.5°","66.5°","90°"],"answer":1,"explanation":"The axial tilt is about 23.5° (23.44°) from the perpendicular. 66.5° is the angle the axis makes with the orbital plane itself, a common trap.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"पृथ्वी की घूर्णन धुरी उसके कक्षीय तल के लंब से लगभग कितने अंश झुकी हुई है?","optionsHi":["0°","23.5°","66.5°","90°"],"explanationHi":"अक्षीय झुकाव लंब से लगभग 23.5° (23.44°) है। 66.5° वह कोण है जो धुरी कक्षीय तल से स्वयं बनाती है, जो एक सामान्य भ्रम है।"},
  {"id":"geo-solar-system-65","question":"Among the outer planets, which two are classed as “ice giants” rather than gas giants?","options":["Jupiter and Saturn","Saturn and Uranus","Jupiter and Neptune","Uranus and Neptune"],"answer":3,"explanation":"Uranus and Neptune contain a large share of “ices” (water, ammonia, methane) beneath thinner hydrogen–helium envelopes; Jupiter and Saturn are the gas giants.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"बाह्य ग्रहों में से कौन-से दो “हिम दानव” के रूप में वर्गीकृत हैं, गैस दानव नहीं?","optionsHi":["बृहस्पति और शनि","शनि और अरुण","बृहस्पति और वरुण","अरुण और वरुण"],"explanationHi":"अरुण और वरुण में पतले हाइड्रोजन–हीलियम आवरण के नीचे “हिम” (जल, अमोनिया, मीथेन) का बड़ा अंश होता है; बृहस्पति और शनि गैस दानव हैं।"},
  {"id":"geo-solar-system-66","question":"A piece of rock from space that survives its passage through the atmosphere and lands on the Earth’s surface is called a:","options":["Meteorite","Meteoroid","Asteroid","Comet"],"answer":0,"explanation":"In space it is a meteoroid, the streak of light in the sky is a meteor, and the piece that reaches the ground is a meteorite.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL","questionHi":"अंतरिक्ष से आई चट्टान का वह टुकड़ा जो वायुमंडल से गुज़रकर बच जाता है और पृथ्वी की सतह पर गिरता है, क्या कहलाता है?","optionsHi":["उल्कापिंड (मीटियोराइट)","मीटियोरॉयड","क्षुद्रग्रह","धूमकेतु"],"explanationHi":"अंतरिक्ष में वह मीटियोरॉयड है, आकाश में प्रकाश की रेखा उल्का (मीटियोर) है, और जो टुकड़ा भूमि तक पहुँचता है वह उल्कापिंड (मीटियोराइट) है।"},
  {"id":"geo-solar-system-67","question":"The time the Moon takes to complete one revolution around the Earth measured against the distant stars (the sidereal month) is about:","options":["29.5 days","27.3 days","24.8 days","30.4 days"],"answer":1,"explanation":"The sidereal month is about 27.3 days. The synodic month (new moon to new moon) is longer, about 29.5 days, because the Earth has moved along its orbit in the meantime.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"चंद्रमा को दूरस्थ तारों के सापेक्ष पृथ्वी की एक परिक्रमा पूरी करने में लगने वाला समय (नक्षत्र मास) लगभग है:","optionsHi":["29.5 दिन","27.3 दिन","24.8 दिन","30.4 दिन"],"explanationHi":"नक्षत्र मास लगभग 27.3 दिन का होता है। संयुति मास (अमावस्या से अमावस्या) लगभग 29.5 दिन का होता है, जो अधिक है, क्योंकि इस बीच पृथ्वी अपनी कक्षा में आगे बढ़ चुकी होती है।"},
  {"id":"geo-solar-system-68","question":"Voyager 1 became the first human-made object to enter interstellar space in:","options":["1990","2004","2012","2020"],"answer":2,"explanation":"Voyager 1, launched in 1977, crossed the heliopause in August 2012. Voyager 2 followed in 2018.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"वॉयेजर 1 किस वर्ष अंतरतारकीय अंतरिक्ष में प्रवेश करने वाली पहली मानव-निर्मित वस्तु बना?","optionsHi":["1990","2004","2012","2020"],"explanationHi":"1977 में प्रक्षेपित वॉयेजर 1 ने अगस्त 2012 में हीलियोपॉज़ को पार किया। वॉयेजर 2 ने 2018 में उसका अनुसरण किया।"},
  {"id":"geo-solar-system-69","question":"Neptune was discovered in 1846 mainly as a result of:","options":["Galileo's telescope observations of its rings","Calculations from Uranus's orbital irregularities","Photographs taken by the Voyager 2 space probe","Radio signals detected from the planet by Herschel"],"answer":1,"explanation":"Le Verrier (and Adams) predicted its position from the unexplained perturbations of Uranus’s orbit, and Galle found it close to that spot; it was the first planet found by calculation.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"वरुण की खोज 1846 में मुख्यतः किसके परिणामस्वरूप हुई?","optionsHi":["गैलीलियो द्वारा उसके वलयों के दूरबीन से किए गए प्रेक्षण","अरुण की कक्षीय अनियमितताओं से की गई गणनाएँ","वॉयेजर 2 अंतरिक्ष यान द्वारा ली गई तस्वीरें","हर्शल द्वारा ग्रह से पकड़े गए रेडियो संकेत"],"explanationHi":"ले वेरिए (और एडम्स) ने अरुण की कक्षा की अस्पष्टीकृत विचलनों से उसकी स्थिति की भविष्यवाणी की, और गाले ने उसे उस स्थान के निकट खोज लिया; यह गणना से खोजा गया पहला ग्रह था।"},
  {"id":"geo-solar-system-70","question":"India’s solar observatory Aditya-L1 is placed in a halo orbit around the Lagrange point L1, which lies at about what distance from the Earth?","options":["15 million km","384,400 km","150 million km","1.5 million km"],"answer":3,"explanation":"L1 is about 1.5 million km from the Earth towards the Sun, roughly 1% of the Earth–Sun distance, so the Sun can be watched without eclipses.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"भारत की सौर वेधशाला आदित्य-L1 को लैग्रेंज बिंदु L1 के चारों ओर हेलो कक्षा में रखा गया है, जो पृथ्वी से लगभग कितनी दूरी पर है?","optionsHi":["15 मिलियन किमी","384,400 किमी","150 मिलियन किमी","1.5 मिलियन किमी"],"explanationHi":"L1 पृथ्वी से सूर्य की ओर लगभग 1.5 मिलियन किमी पर है, जो पृथ्वी–सूर्य दूरी का लगभग 1% है, इसलिए सूर्य को ग्रहणों के बिना देखा जा सकता है।"},
  {"id":"geo-solar-system-71","question":"The outermost layer of the Sun’s atmosphere, seen as a pearly glow around the Moon during a total solar eclipse, is the:","options":["Photosphere","Chromosphere","Corona","Core"],"answer":2,"explanation":"The corona is the outermost layer and becomes visible when the Moon blocks the bright photosphere; the chromosphere is the thin reddish layer just above the photosphere.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"सूर्य के वायुमंडल की सबसे बाहरी परत, जो पूर्ण सूर्य ग्रहण के दौरान चंद्रमा के चारों ओर मोती जैसी आभा के रूप में दिखती है, कौन-सी है?","optionsHi":["प्रकाशमंडल","वर्णमंडल","कोरोना","क्रोड"],"explanationHi":"कोरोना सबसे बाहरी परत है और तब दिखाई देती है जब चंद्रमा चमकीले प्रकाशमंडल को अवरुद्ध कर देता है; वर्णमंडल प्रकाशमंडल के ठीक ऊपर की पतली लालिमा लिए परत है।"},
  {"id":"geo-solar-system-72","question":"Which planet has the fastest winds measured in the Solar System, exceeding 2,000 km/h?","options":["Neptune","Jupiter","Saturn","Mars"],"answer":0,"explanation":"Voyager 2 measured winds of about 2,100 km/h on Neptune, the fastest of any planet, even though it is the farthest from the Sun.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"किस ग्रह पर सौरमंडल में मापी गई सबसे तेज़ हवाएँ हैं, जो 2,000 km/h से अधिक हैं?","optionsHi":["वरुण","बृहस्पति","शनि","मंगल"],"explanationHi":"वॉयेजर 2 ने वरुण पर लगभग 2,100 km/h की हवाएँ मापीं, जो किसी भी ग्रह में सबसे तेज़ हैं, जबकि वह सूर्य से सबसे दूर है।"},
  {"id":"geo-solar-system-73","question":"Sunspots appear dark on the Sun’s surface because they are:","options":["Hotter than the surrounding regions","Holes through which the core is visible","Shadows cast by the inner planets","Cooler than the surrounding photosphere"],"answer":3,"explanation":"Sunspots are regions of intense magnetic activity about 1,500 °C cooler than the surrounding photosphere, so they look dark by contrast; their number follows an 11-year cycle.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"सौर कलंक सूर्य की सतह पर काले क्यों दिखाई देते हैं? क्योंकि वे:","optionsHi":["आसपास के क्षेत्रों से अधिक गर्म होते हैं","ऐसे छिद्र हैं जिनसे क्रोड दिखाई देता है","आंतरिक ग्रहों द्वारा बनी छायाएँ हैं","आसपास के प्रकाशमंडल से अधिक ठंडे होते हैं"],"explanationHi":"सौर कलंक तीव्र चुंबकीय गतिविधि वाले क्षेत्र हैं जो आसपास के प्रकाशमंडल से लगभग 1,500 °C ठंडे होते हैं, इसलिए वे विरोधाभास में काले दिखते हैं; उनकी संख्या 11 वर्ष के चक्र का अनुसरण करती है।"},
  {"id":"geo-solar-system-74","question":"How many of these statements are correct? I. The IAU recognises five dwarf planets: Ceres, Pluto, Eris, Haumea and Makemake. II. Ceres is the only dwarf planet in the main asteroid belt. III. Eris is more massive than Pluto. IV. Charon is the largest moon of Pluto.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The IAU lists five dwarf planets, Ceres alone lies in the asteroid belt, Eris is about 27% more massive than Pluto, and Charon is the largest of Pluto’s five known moons.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कितने कथन सही हैं? I. IAU पाँच बौने ग्रहों को मान्यता देता है: सेरेस, प्लूटो, एरिस, हाउमिया और माकेमाके। II. सेरेस मुख्य क्षुद्रग्रह पट्टी का एकमात्र बौना ग्रह है। III. एरिस प्लूटो से अधिक द्रव्यमान वाला है। IV. शेरन प्लूटो का सबसे बड़ा चंद्रमा है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। IAU पाँच बौने ग्रहों को सूचीबद्ध करता है, केवल सेरेस क्षुद्रग्रह पट्टी में है, एरिस प्लूटो से लगभग 27% अधिक द्रव्यमान वाला है, और शेरन प्लूटो के पाँच ज्ञात चंद्रमाओं में सबसे बड़ा है।"},
  {"id":"geo-solar-system-75","question":"Assertion (A): The same face of the Moon is always seen from the Earth. Reason (R): The Moon takes the same time to rotate once on its axis as it takes to revolve once around the Earth.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"The Moon is tidally locked: its rotation period equals its orbital period (about 27.3 days), so one hemisphere always faces the Earth. R correctly explains A.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): पृथ्वी से चंद्रमा का सदैव एक ही पक्ष दिखाई देता है। कारण (R): चंद्रमा को अपनी धुरी पर एक बार घूर्णन करने में उतना ही समय लगता है जितना पृथ्वी की एक परिक्रमा करने में।","optionsHi":["A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"चंद्रमा ज्वारीय रूप से बँधा हुआ है: उसका घूर्णन काल उसके कक्षीय काल (लगभग 27.3 दिन) के बराबर है, इसलिए एक गोलार्ध सदैव पृथ्वी की ओर रहता है। R, A की सही व्याख्या करता है।"},
  {"id":"geo-solar-system-76","question":"Match the mission with its main target: 1. Mangalyaan 2. Juno 3. New Horizons 4. Cassini; a. Saturn b. Pluto c. Jupiter d. Mars","options":["1-c, 2-d, 3-a, 4-b","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a","1-a, 2-c, 3-b, 4-d"],"answer":2,"explanation":"Mangalyaan (ISRO) went to Mars, Juno orbits Jupiter, New Horizons flew past Pluto in 2015 and Cassini studied Saturn until 2017.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभियान का उसके मुख्य लक्ष्य से मिलान कीजिए: 1. मंगलयान 2. जूनो 3. न्यू हॉराइज़न्स 4. कैसिनी; a. शनि b. प्लूटो c. बृहस्पति d. मंगल","optionsHi":["1-c, 2-d, 3-a, 4-b","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a","1-a, 2-c, 3-b, 4-d"],"explanationHi":"मंगलयान (ISRO) मंगल पर गया, जूनो बृहस्पति की परिक्रमा करता है, न्यू हॉराइज़न्स ने 2015 में प्लूटो के पास से उड़ान भरी और कैसिनी ने 2017 तक शनि का अध्ययन किया।"},
  {"id":"geo-solar-system-77","question":"Assertion (A): Pluto is no longer counted as one of the planets of the Solar System. Reason (R): Pluto is not nearly round in shape.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true. R is false: Pluto is massive enough to be nearly round. It failed the IAU test because it has not cleared the neighbourhood of its orbit (the Kuiper belt).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): प्लूटो अब सौरमंडल के ग्रहों में नहीं गिना जाता। कारण (R): प्लूटो का आकार लगभग गोल भी नहीं है।","optionsHi":["A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"A सत्य है। R असत्य है: प्लूटो इतना द्रव्यमान वाला है कि लगभग गोल है। वह IAU की कसौटी पर इसलिए विफल रहा क्योंकि उसने अपनी कक्षा के आस-पास का क्षेत्र (कुइपर पट्टी) साफ़ नहीं किया है।"},
  {"id":"geo-solar-system-78","question":"How many of these statements are correct? I. Comets are made largely of ice, dust and rock. II. A comet’s tail points broadly away from the Sun. III. Most meteors burn up in the mesosphere. IV. Halley’s Comet was last seen from the inner Solar System in 1986.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Comets are icy, dusty bodies whose tails are pushed away from the Sun by radiation pressure and the solar wind; most meteors burn up in the mesosphere, and Halley’s Comet last passed in 1986.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"इनमें से कितने कथन सही हैं? I. धूमकेतु मुख्यतः बर्फ, धूल और चट्टान से बने होते हैं। II. धूमकेतु की पूँछ मोटे तौर पर सूर्य से दूर की ओर होती है। III. अधिकांश उल्काएँ मध्यमंडल में जल जाती हैं। IV. हैली धूमकेतु को आंतरिक सौरमंडल से अंतिम बार 1986 में देखा गया था।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। धूमकेतु बर्फीले, धूल भरे पिंड हैं जिनकी पूँछ विकिरण दाब और सौर पवन द्वारा सूर्य से दूर धकेली जाती है; अधिकांश उल्काएँ मध्यमंडल में जल जाती हैं, और हैली धूमकेतु अंतिम बार 1986 में गुज़रा था।"},
  {"id":"geo-solar-system-79","question":"Arrange these bodies in increasing order of diameter: 1. Mercury 2. Pluto 3. Ganymede 4. Earth’s Moon","options":["2, 4, 1, 3","4, 2, 1, 3","2, 4, 3, 1","4, 2, 3, 1"],"answer":0,"explanation":"Pluto (about 2,377 km) < Moon (about 3,475 km) < Mercury (about 4,880 km) < Ganymede (about 5,268 km). The trap is that the moon Ganymede is larger than the planet Mercury.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इन पिंडों को व्यास के बढ़ते क्रम में व्यवस्थित कीजिए: 1. बुध 2. प्लूटो 3. गैनिमीड 4. पृथ्वी का चंद्रमा","optionsHi":["2, 4, 1, 3","4, 2, 1, 3","2, 4, 3, 1","4, 2, 3, 1"],"explanationHi":"प्लूटो (लगभग 2,377 किमी) < चंद्रमा (लगभग 3,475 किमी) < बुध (लगभग 4,880 किमी) < गैनिमीड (लगभग 5,268 किमी)। भ्रम यह है कि चंद्रमा गैनिमीड ग्रह बुध से बड़ा है।"},
  {"id":"geo-solar-system-80","question":"A planet has twice the radius of the Earth and the same average density. If the Earth’s escape velocity is 11.2 km/s, the planet’s escape velocity is:","options":["11.2 km/s","15.8 km/s","44.8 km/s","22.4 km/s"],"answer":3,"explanation":"vₑ = √(2GM/R) and M ∝ ρR³, so vₑ ∝ R√ρ. With the same density and double the radius, vₑ doubles: 2 × 11.2 = 22.4 km/s.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"एक ग्रह की त्रिज्या पृथ्वी से दोगुनी है और औसत घनत्व समान है। यदि पृथ्वी का पलायन वेग 11.2 km/s है, तो उस ग्रह का पलायन वेग है:","optionsHi":["11.2 km/s","15.8 km/s","44.8 km/s","22.4 km/s"],"explanationHi":"vₑ = √(2GM/R) और M ∝ ρR³, अतः vₑ ∝ R√ρ। समान घनत्व और दोगुनी त्रिज्या के साथ vₑ दोगुना हो जाता है: 2 × 11.2 = 22.4 km/s।"},
  {"id":"geo-solar-system-81","question":"A body weighs 600 N on the Earth (g = 10 m/s²). If gravity on the Moon is one-sixth of that on the Earth, its mass and weight on the Moon are:","options":["10 kg and 100 N","60 kg and 100 N","60 kg and 600 N","10 kg and 600 N"],"answer":1,"explanation":"Mass = 600 ÷ 10 = 60 kg and does not change with place. Weight on the Moon = 600 ÷ 6 = 100 N.","difficulty":"very-hard","source":"SSC CHSL · RRB Group D","questionHi":"एक वस्तु का पृथ्वी पर भार 600 N है (g = 10 m/s²)। यदि चंद्रमा पर गुरुत्व पृथ्वी के गुरुत्व का छठा भाग है, तो चंद्रमा पर उसका द्रव्यमान और भार हैं:","optionsHi":["10 kg और 100 N","60 kg और 100 N","60 kg और 600 N","10 kg और 600 N"],"explanationHi":"द्रव्यमान = 600 ÷ 10 = 60 kg और वह स्थान बदलने पर नहीं बदलता। चंद्रमा पर भार = 600 ÷ 6 = 100 N।"},
  {"id":"geo-solar-system-82","question":"Which of the following is NOT a moon of Jupiter?","options":["Io","Europa","Enceladus","Ganymede"],"answer":2,"explanation":"Io, Europa, Ganymede and Callisto are the four Galilean moons of Jupiter. Enceladus, with its icy water plumes, is a moon of Saturn.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"निम्नलिखित में से कौन-सा बृहस्पति का चंद्रमा नहीं है?","optionsHi":["आयो","यूरोपा","एन्सेलेडस","गैनिमीड"],"explanationHi":"आयो, यूरोपा, गैनिमीड और कैलिस्टो बृहस्पति के चार गैलीलियन चंद्रमा हैं। एन्सेलेडस, अपने बर्फीले जल के फव्वारों के साथ, शनि का चंद्रमा है।"},
  {"id":"geo-solar-system-83","question":"How many of these statements about the Moon are correct? I. Its mean distance from the Earth is about 384,400 km. II. Its surface gravity is about one-sixth of the Earth’s. III. It has a thick atmosphere. IV. Its far side never receives sunlight.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only I and II are correct. The Moon has practically no atmosphere, and the far side gets as much sunlight as the near side; it is only hidden from the Earth, not dark.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"चंद्रमा के बारे में इनमें से कितने कथन सही हैं? I. पृथ्वी से उसकी माध्य दूरी लगभग 384,400 किमी है। II. उसकी सतह का गुरुत्व पृथ्वी के गुरुत्व का लगभग छठा भाग है। III. उसका वायुमंडल घना है। IV. उसके दूर वाले पक्ष पर कभी सूर्य का प्रकाश नहीं पड़ता।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I और II सही हैं। चंद्रमा पर व्यावहारिक रूप से कोई वायुमंडल नहीं है, और दूर वाले पक्ष को उतना ही सूर्य प्रकाश मिलता है जितना निकट वाले पक्ष को; वह केवल पृथ्वी से छिपा रहता है, अंधकारमय नहीं।"},
  {"id":"geo-solar-system-84","question":"Arrange these Indian space events in chronological order: 1. Mangalyaan enters orbit around Mars 2. Launch of Chandrayaan-1 3. Launch of Aditya-L1 4. Chandrayaan-3 lands near the lunar south pole","options":["2, 1, 3, 4","2, 1, 4, 3","1, 2, 4, 3","2, 4, 1, 3"],"answer":1,"explanation":"Chandrayaan-1 was launched in October 2008, Mangalyaan reached Mars orbit on 24 September 2014, Chandrayaan-3 landed on 23 August 2023 and Aditya-L1 was launched on 2 September 2023.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इन भारतीय अंतरिक्ष घटनाओं को कालक्रम में व्यवस्थित कीजिए: 1. मंगलयान का मंगल की कक्षा में प्रवेश 2. चंद्रयान-1 का प्रक्षेपण 3. आदित्य-L1 का प्रक्षेपण 4. चंद्रयान-3 का चंद्रमा के दक्षिणी ध्रुव के निकट उतरना","optionsHi":["2, 1, 3, 4","2, 1, 4, 3","1, 2, 4, 3","2, 4, 1, 3"],"explanationHi":"चंद्रयान-1 अक्टूबर 2008 में प्रक्षेपित हुआ, मंगलयान 24 सितंबर 2014 को मंगल की कक्षा में पहुँचा, चंद्रयान-3 23 अगस्त 2023 को उतरा और आदित्य-L1 2 सितंबर 2023 को प्रक्षेपित हुआ।"},
  {"id":"geo-solar-system-85","question":"Who first observed the four largest moons of Jupiter, in 1610?","options":["Nicolaus Copernicus","Galileo Galilei","Johannes Kepler","Isaac Newton"],"answer":1,"explanation":"Galileo Galilei saw Io, Europa, Ganymede and Callisto through his telescope in January 1610; they are called the Galilean moons. Kepler gave the laws of planetary motion and Copernicus the heliocentric model.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"1610 में बृहस्पति के चार सबसे बड़े चंद्रमाओं को सबसे पहले किसने देखा?","optionsHi":["निकोलस कोपरनिकस","गैलीलियो गैलीली","जोहान्स केपलर","आइज़ैक न्यूटन"],"explanationHi":"गैलीलियो गैलीली ने जनवरी 1610 में अपनी दूरबीन से आयो, यूरोपा, गैनिमीड और कैलिस्टो को देखा; इन्हें गैलीलियन चंद्रमा कहा जाता है। केपलर ने ग्रहीय गति के नियम दिए और कोपरनिकस ने सूर्य-केंद्रित मॉडल।"},
  {"id":"geo-solar-system-86","question":"A lunar eclipse can occur only on a:","options":["First-quarter day","New moon day","Any day of the month","Full moon night"],"answer":3,"explanation":"In a lunar eclipse the Earth lies between the Sun and the Moon, which is exactly the full-moon position. A solar eclipse, in contrast, needs the Moon between the Sun and the Earth, which happens only at new moon.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"चंद्र ग्रहण केवल किस दिन हो सकता है?","optionsHi":["प्रथम चतुर्थांश के दिन","अमावस्या के दिन","महीने के किसी भी दिन","पूर्णिमा की रात"],"explanationHi":"चंद्र ग्रहण में पृथ्वी सूर्य और चंद्रमा के बीच होती है, जो ठीक पूर्णिमा की स्थिति है। इसके विपरीत, सूर्य ग्रहण में चंद्रमा को सूर्य और पृथ्वी के बीच होना चाहिए, जो केवल अमावस्या को होता है।"},
  {"id":"geo-solar-system-87","question":"The large, dark, smooth plains on the Moon that can be seen with the naked eye are called:","options":["Highlands","Craters","Rilles","Maria"],"answer":3,"explanation":"Maria (Latin for ‘seas’) are vast plains of solidified basaltic lava; dark basalt reflects less sunlight, so they look darker than the bright, cratered highlands. Early astronomers mistook them for seas.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"चंद्रमा पर नंगी आँखों से दिखाई देने वाले बड़े, गहरे, चिकने मैदान क्या कहलाते हैं?","optionsHi":["उच्च भूमि (हाइलैंड्स)","क्रेटर","रिल (संकरी घाटियाँ)","मारिया"],"explanationHi":"मारिया (लैटिन में ‘समुद्र’) जमे हुए बेसाल्टिक लावा के विशाल मैदान हैं; गहरा बेसाल्ट कम प्रकाश परावर्तित करता है, इसलिए वे चमकीली, क्रेटरों वाली उच्च भूमि से अधिक गहरे दिखते हैं। प्रारंभिक खगोलविदों ने उन्हें समुद्र समझ लिया था।"},
  {"id":"geo-solar-system-88","question":"Solar and lunar eclipses do not occur every month mainly because:","options":["The Earth's axis is tilted by 23.5° to its orbit","The Moon's orbit around Earth is a perfect circle","The Moon rotates once on its axis every month","The Moon's orbit is tilted 5° to Earth's orbit"],"answer":3,"explanation":"Because of the 5° tilt, the Moon at new or full moon usually passes above or below the Sun–Earth line; eclipses happen only when new or full moon falls near the nodes where the two orbits cross. The Earth’s axial tilt causes the seasons, not this.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"सूर्य और चंद्र ग्रहण हर महीने नहीं होते, इसका मुख्य कारण है:","optionsHi":["पृथ्वी की धुरी उसकी कक्षा से 23.5° झुकी हुई है","चंद्रमा की पृथ्वी के चारों ओर की कक्षा पूर्ण वृत्त है","चंद्रमा प्रत्येक महीने अपनी धुरी पर एक बार घूर्णन करता है","चंद्रमा की कक्षा पृथ्वी की कक्षा से 5° झुकी हुई है"],"explanationHi":"5° के झुकाव के कारण अमावस्या या पूर्णिमा पर चंद्रमा प्रायः सूर्य–पृथ्वी रेखा के ऊपर या नीचे से गुज़रता है; ग्रहण तभी होते हैं जब अमावस्या या पूर्णिमा उन नोड बिंदुओं के निकट पड़े जहाँ दोनों कक्षाएँ एक-दूसरे को काटती हैं। पृथ्वी का अक्षीय झुकाव ऋतुओं का कारण है, इसका नहीं।"},
  {"id":"geo-solar-system-89","question":"The temperature of the Sun’s visible surface, the photosphere, is about:","options":["15 million °C","1 million °C","5,500 °C","1,500 °C"],"answer":2,"explanation":"The photosphere is about 5,500 °C (roughly 5,800 K). The corona reaches more than a million degrees and the core about 15 million degrees, so those options describe other layers.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"सूर्य की दृश्य सतह, प्रकाशमंडल, का तापमान लगभग है:","optionsHi":["15 मिलियन °C","1 मिलियन °C","5,500 °C","1,500 °C"],"explanationHi":"प्रकाशमंडल लगभग 5,500 °C (लगभग 5,800 K) का है। कोरोना दस लाख डिग्री से अधिक और क्रोड लगभग 15 मिलियन डिग्री तक पहुँचता है, इसलिए वे विकल्प अन्य परतों का वर्णन करते हैं।"},
  {"id":"geo-solar-system-90","question":"The auroras (northern and southern lights) are caused by:","options":["Meteors burning up in the mesosphere over the poles","Solar particles exciting upper-air gases near poles","Lightning discharges in the upper stratosphere","Sunlight reflected from polar ice and snow"],"answer":1,"explanation":"Charged particles of the solar wind are guided by the Earth’s magnetic field towards the polar regions, where they excite oxygen and nitrogen atoms that glow green, red or violet. That is why auroras are seen mostly at high latitudes.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"ध्रुवीय ज्योति (उत्तरी और दक्षिणी प्रकाश, ऑरोरा) किसके कारण होती है?","optionsHi":["ध्रुवों के ऊपर मध्यमंडल में उल्काओं का जल जाना","ध्रुवों के निकट ऊपरी वायु की गैसों को उत्तेजित करने वाले सौर कण","ऊपरी समतापमंडल में तड़ित विसर्जन","ध्रुवीय बर्फ और हिम से परावर्तित सूर्य का प्रकाश"],"explanationHi":"सौर पवन के आवेशित कणों को पृथ्वी का चुंबकीय क्षेत्र ध्रुवीय क्षेत्रों की ओर मोड़ता है, जहाँ वे ऑक्सीजन और नाइट्रोजन परमाणुओं को उत्तेजित करते हैं, जो हरे, लाल या बैंगनी रंग में चमकते हैं। इसीलिए ध्रुवीय ज्योति मुख्यतः उच्च अक्षांशों में दिखती है।"},
  {"id":"geo-solar-system-91","question":"Mars rotates once on its axis in about:","options":["24 hours 37 minutes","16 hours 6 minutes","58 days 15 hours","9 hours 56 minutes"],"answer":0,"explanation":"Mars spins once in about 24 h 37 min, so its day is very close to the Earth's. About 9 h 56 min is Jupiter, about 16 h is Neptune and about 58.6 days is Mercury.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"मंगल अपनी धुरी पर एक घूर्णन लगभग कितने समय में पूरा करता है?","optionsHi":["24 घंटे 37 मिनट","16 घंटे 6 मिनट","58 दिन 15 घंटे","9 घंटे 56 मिनट"],"explanationHi":"मंगल लगभग 24 घंटे 37 मिनट में एक बार घूर्णन करता है, इसलिए उसका दिन पृथ्वी के दिन के बहुत निकट है। लगभग 9 घंटे 56 मिनट बृहस्पति का, लगभग 16 घंटे वरुण का और लगभग 58.6 दिन बुध का है।"},
  {"id":"geo-solar-system-92","question":"As of 2025, which planet has the largest number of confirmed moons?","options":["Neptune","Saturn","Uranus","Jupiter"],"answer":1,"explanation":"In March 2025 astronomers confirmed 128 more small moons of Saturn, taking its total to 274, far more than Jupiter’s count of under 100. The lead has switched before as new discoveries are announced, which is why the year matters.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"2025 तक, किस ग्रह के पास सबसे अधिक संख्या में पुष्ट चंद्रमा हैं?","optionsHi":["वरुण","शनि","अरुण","बृहस्पति"],"explanationHi":"मार्च 2025 में खगोलविदों ने शनि के 128 और छोटे चंद्रमाओं की पुष्टि की, जिससे उसकी कुल संख्या 274 हो गई, जो बृहस्पति की 100 से कम संख्या से कहीं अधिक है। नई खोजों की घोषणा के साथ यह अग्रता पहले भी बदली है, इसीलिए वर्ष महत्वपूर्ण है।"},
  {"id":"geo-solar-system-93","question":"Pluto’s largest moon, about half the diameter of Pluto itself, is:","options":["Charon","Nix","Triton","Titania"],"answer":0,"explanation":"Charon is about 1,212 km across against Pluto’s 2,377 km, so the two orbit a common centre lying outside Pluto. Triton belongs to Neptune, Titania to Uranus, and Nix is one of Pluto’s small moons.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"प्लूटो का सबसे बड़ा चंद्रमा, जिसका व्यास स्वयं प्लूटो के व्यास का लगभग आधा है, कौन-सा है?","optionsHi":["शेरन","निक्स","ट्राइटन","टाइटेनिया"],"explanationHi":"शेरन का व्यास लगभग 1,212 किमी है जबकि प्लूटो का 2,377 किमी, इसलिए दोनों एक उभयनिष्ठ केंद्र की परिक्रमा करते हैं जो प्लूटो के बाहर स्थित है। ट्राइटन वरुण का, टाइटेनिया अरुण का है, और निक्स प्लूटो के छोटे चंद्रमाओं में से एक है।"},
  {"id":"geo-solar-system-94","question":"Around what time does a first-quarter Moon cross the meridian, that is, stand highest in the sky?","options":["About 6 pm (sunset)","About 6 am (sunrise)","Midnight","Noon"],"answer":0,"explanation":"At first quarter the Moon is 90° east of the Sun, so it rises around noon, is highest around sunset and sets around midnight. The full Moon, opposite the Sun, is the one that is highest at midnight.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"प्रथम चतुर्थांश का चंद्रमा लगभग किस समय याम्योत्तर को पार करता है, अर्थात आकाश में सबसे ऊँचा होता है?","optionsHi":["लगभग शाम 6 बजे (सूर्यास्त)","लगभग सुबह 6 बजे (सूर्योदय)","मध्यरात्रि","दोपहर"],"explanationHi":"प्रथम चतुर्थांश पर चंद्रमा सूर्य से 90° पूर्व में होता है, इसलिए वह लगभग दोपहर को उदय होता है, सूर्यास्त के आसपास सबसे ऊँचा होता है और लगभग मध्यरात्रि को अस्त होता है। पूर्णिमा का चंद्रमा, जो सूर्य के सम्मुख होता है, मध्यरात्रि को सबसे ऊँचा होता है।"},
  {"id":"geo-solar-system-95","question":"The synodic month (new moon to new moon, about 29.5 days) is longer than the sidereal month (about 27.3 days) because:","options":["The Moon slows down sharply near apogee in each orbit","Earth's orbital motion makes the Moon go about 27° further","The Earth's spin is gradually slowing because of tides","The Moon's orbit is tilted by about 5° to the ecliptic"],"answer":1,"explanation":"In 27.3 days the Moon completes one turn relative to the stars, but meanwhile the Earth has moved about 27° around the Sun, so the Moon needs roughly 2.2 extra days to return to the same phase. The orbital tilt affects eclipses, not the month length.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"संयुति मास (अमावस्या से अमावस्या, लगभग 29.5 दिन) नक्षत्र मास (लगभग 27.3 दिन) से लंबा होता है, क्योंकि:","optionsHi":["प्रत्येक परिक्रमा में अपभू के निकट चंद्रमा तेज़ी से धीमा हो जाता है","पृथ्वी की कक्षीय गति के कारण चंद्रमा को लगभग 27° और आगे जाना पड़ता है","ज्वार के कारण पृथ्वी का घूर्णन धीरे-धीरे धीमा हो रहा है","चंद्रमा की कक्षा क्रांतिवृत्त से लगभग 5° झुकी हुई है"],"explanationHi":"27.3 दिनों में चंद्रमा तारों के सापेक्ष एक चक्कर पूरा करता है, परंतु इस बीच पृथ्वी सूर्य के चारों ओर लगभग 27° आगे बढ़ चुकी होती है, इसलिए चंद्रमा को उसी कला में लौटने के लिए लगभग 2.2 दिन और चाहिए। कक्षीय झुकाव ग्रहणों को प्रभावित करता है, महीने की लंबाई को नहीं।"},
  {"id":"geo-solar-system-96","question":"An annular (‘ring of fire’) solar eclipse occurs when:","options":["The Moon is near perigee and looks largest in the sky","The Earth is at aphelion, so the Sun looks largest","The Moon is near apogee and too small to cover the Sun","Only the Earth's penumbra falls on the Moon's disc"],"answer":2,"explanation":"Near apogee the Moon appears slightly smaller than the Sun, so a bright ring is left around it. The Sun actually looks smallest at aphelion, and the Earth’s shadow on the Moon describes a lunar, not solar, eclipse.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"कंकणाकृति (‘आग का छल्ला’) सूर्य ग्रहण तब होता है जब:","optionsHi":["चंद्रमा उपभू के निकट होता है और आकाश में सबसे बड़ा दिखता है","पृथ्वी अपसौर पर होती है, इसलिए सूर्य सबसे बड़ा दिखता है","चंद्रमा अपभू के निकट होता है और सूर्य को ढकने के लिए बहुत छोटा होता है","केवल पृथ्वी की उपच्छाया चंद्रमा की चकती पर पड़ती है"],"explanationHi":"अपभू के निकट चंद्रमा सूर्य से थोड़ा छोटा दिखता है, इसलिए उसके चारों ओर एक चमकीला छल्ला बच जाता है। वास्तव में सूर्य अपसौर पर सबसे छोटा दिखता है, और चंद्रमा पर पृथ्वी की छाया चंद्र ग्रहण का वर्णन करती है, सूर्य ग्रहण का नहीं।"},
  {"id":"geo-solar-system-97","question":"The Kirkwood gaps are:","options":["The empty space between the Kuiper belt and Oort cloud","Asteroid-belt zones cleared by resonances with Jupiter","Gaps in Saturn's rings cleared by shepherd moons","Dark lanes seen in the Sun's corona during eclipses"],"answer":1,"explanation":"Asteroids whose periods would be a simple fraction of Jupiter’s (such as 1/3 or 2/5) receive repeated tugs and are cleared out, leaving gaps in the belt. Gaps in Saturn’s rings, such as the Cassini Division, are a different feature.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"किर्कवुड अंतराल (Kirkwood gaps) क्या हैं?","optionsHi":["कुइपर पट्टी और ऊर्ट बादल के बीच का रिक्त स्थान","बृहस्पति के साथ अनुनाद द्वारा साफ़ किए गए क्षुद्रग्रह पट्टी के क्षेत्र","चरवाहा चंद्रमाओं द्वारा साफ़ किए गए शनि के वलयों के अंतराल","ग्रहण के दौरान सूर्य के कोरोना में दिखने वाली गहरी धारियाँ"],"explanationHi":"जिन क्षुद्रग्रहों का आवर्तकाल बृहस्पति के आवर्तकाल का कोई सरल भिन्न (जैसे 1/3 या 2/5) होता, उन्हें बार-बार खिंचाव मिलता है और वे बाहर निकल जाते हैं, जिससे पट्टी में अंतराल बन जाते हैं। शनि के वलयों के अंतराल, जैसे कैसिनी विभाजन, एक भिन्न विशेषता हैं।"},
  {"id":"geo-solar-system-98","question":"The particles of Saturn’s rings have not gathered together to form a moon mainly because:","options":["Saturn's tides inside its Roche limit tear clumps apart","They are made of ice, which cannot stick together","Saturn's strong magnetic field keeps pushing them apart","They orbit faster than Saturn's escape velocity allows"],"answer":0,"explanation":"Inside the Roche limit the difference in Saturn’s pull across a clump exceeds the gravity holding the clump together, so it is torn apart. Being icy does not prevent clumping, and particles faster than escape velocity would leave Saturn altogether.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"शनि के वलयों के कण मिलकर एक चंद्रमा क्यों नहीं बना सके, इसका मुख्य कारण है:","optionsHi":["रोश सीमा के भीतर शनि का ज्वारीय बल गुच्छों को तोड़ देता है","वे बर्फ के बने हैं, जो आपस में चिपक नहीं सकती","शनि का प्रबल चुंबकीय क्षेत्र उन्हें लगातार अलग धकेलता रहता है","वे शनि के पलायन वेग से अधिक तेज़ी से परिक्रमा करते हैं"],"explanationHi":"रोश सीमा के भीतर किसी गुच्छे पर शनि के खिंचाव का अंतर उस गुच्छे को जोड़े रखने वाले गुरुत्व से अधिक हो जाता है, इसलिए वह टूट जाता है। बर्फीला होना गुच्छे बनने से नहीं रोकता, और पलायन वेग से तेज़ कण शनि को ही छोड़ देंगे।"},
  {"id":"geo-solar-system-99","question":"India’s Mars Orbiter Mission (Mangalyaan) was launched on 5 November 2013 by:","options":["PSLV-C25","PSLV-C11","GSLV-F10","GSLV Mk III"],"answer":0,"explanation":"PSLV-C25 launched Mangalyaan from Sriharikota, and it entered Mars orbit on 24 September 2014. PSLV-C11 launched Chandrayaan-1 in 2008, while the GSLV Mk III (LVM3) launched Chandrayaan-2 and Chandrayaan-3.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"भारत का मंगल कक्षित्र मिशन (मंगलयान) 5 नवंबर 2013 को किसके द्वारा प्रक्षेपित किया गया?","optionsHi":["PSLV-C25","PSLV-C11","GSLV-F10","GSLV Mk III"],"explanationHi":"PSLV-C25 ने मंगलयान को श्रीहरिकोटा से प्रक्षेपित किया, और वह 24 सितंबर 2014 को मंगल की कक्षा में पहुँचा। PSLV-C11 ने 2008 में चंद्रयान-1 को प्रक्षेपित किया, जबकि GSLV Mk III (LVM3) ने चंद्रयान-2 और चंद्रयान-3 को प्रक्षेपित किया।"},
  {"id":"geo-solar-system-100","question":"The spot where Chandrayaan-3’s Vikram lander touched down on the Moon in August 2023 has been named:","options":["Vikram Sarabhai point","Jawahar Sthal","Tiranga point","Shiv Shakti point"],"answer":3,"explanation":"The landing site was named Shiv Shakti point, and 23 August, the landing date, was declared National Space Day. Tiranga point marks where Chandrayaan-2’s lander crashed in 2019, and Jawahar Sthal is where Chandrayaan-1’s Moon Impact Probe struck in 2008.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"अगस्त 2023 में चंद्रयान-3 का विक्रम लैंडर चंद्रमा पर जिस स्थान पर उतरा, उसका नाम रखा गया है:","optionsHi":["विक्रम साराभाई बिंदु","जवाहर स्थल","तिरंगा बिंदु","शिव शक्ति बिंदु"],"explanationHi":"लैंडिंग स्थल का नाम शिव शक्ति बिंदु रखा गया, और 23 अगस्त, लैंडिंग की तारीख, को राष्ट्रीय अंतरिक्ष दिवस घोषित किया गया। तिरंगा बिंदु वह स्थान है जहाँ 2019 में चंद्रयान-2 का लैंडर दुर्घटनाग्रस्त हुआ, और जवाहर स्थल वह स्थान है जहाँ 2008 में चंद्रयान-1 की मून इम्पैक्ट प्रोब टकराई थी।"},
  {"id":"geo-solar-system-101","question":"Uranus and Neptune look bluish-green mainly because:","options":["Oceans of liquid water reflect blue light","Their faint rings scatter blue light onto them","They are hotter than the other giant planets","Methane in their atmospheres absorbs red light"],"answer":3,"explanation":"Methane absorbs the red part of sunlight, so the light scattered back from their upper atmospheres is blue-green. They have no surface oceans, they are among the coldest planets, and their faint rings play no part.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"अरुण और वरुण नीले-हरे क्यों दिखते हैं? मुख्यतः इसलिए कि:","optionsHi":["द्रव जल के महासागर नीले प्रकाश को परावर्तित करते हैं","उनके धुँधले वलय उन पर नीला प्रकाश बिखेरते हैं","वे अन्य विशाल ग्रहों से अधिक गर्म हैं","उनके वायुमंडल में मीथेन लाल प्रकाश को अवशोषित करती है"],"explanationHi":"मीथेन सूर्य के प्रकाश के लाल भाग को अवशोषित करती है, इसलिए उनके ऊपरी वायुमंडल से वापस बिखरा प्रकाश नीला-हरा होता है। उनकी सतह पर कोई महासागर नहीं हैं, वे सबसे ठंडे ग्रहों में हैं, और उनके धुँधले वलयों की कोई भूमिका नहीं है।"},
  {"id":"geo-solar-system-102","question":"A planet has twice the mass and twice the radius of the Earth. A person who weighs 600 N on the Earth would weigh there:","options":["300 N","600 N","150 N","1,200 N"],"answer":0,"explanation":"Surface gravity g ∝ M/R², so g changes by 2/2² = 1/2. The weight becomes 600 × 1/2 = 300 N; the mass of the person does not change.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"एक ग्रह का द्रव्यमान पृथ्वी से दोगुना और त्रिज्या पृथ्वी से दोगुनी है। पृथ्वी पर जिस व्यक्ति का भार 600 N है, उसका वहाँ भार होगा:","optionsHi":["300 N","600 N","150 N","1,200 N"],"explanationHi":"सतही गुरुत्व g ∝ M/R², अतः g में 2/2² = 1/2 गुना परिवर्तन होता है। भार 600 × 1/2 = 300 N हो जाता है; व्यक्ति का द्रव्यमान नहीं बदलता।"},
  {"id":"geo-solar-system-103","question":"How many of these statements about eclipses are correct? I. A lunar eclipse can be seen at the same time from the whole night side of the Earth. II. A total solar eclipse is visible only along a narrow path on the Earth. III. During a total lunar eclipse the Moon often looks reddish because the Earth’s atmosphere bends red light onto it. IV. A solar eclipse can occur on a full moon day.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct: the Earth’s shadow covers the whole Moon, but the Moon’s small shadow sweeps only a narrow track across the Earth, and red light refracted by the Earth’s atmosphere tints the eclipsed Moon. IV is wrong because a solar eclipse needs the new moon.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"ग्रहणों के बारे में इनमें से कितने कथन सही हैं? I. चंद्र ग्रहण पृथ्वी के पूरे रात्रि पक्ष से एक ही समय में देखा जा सकता है। II. पूर्ण सूर्य ग्रहण पृथ्वी पर केवल एक संकरे पथ के साथ दिखाई देता है। III. पूर्ण चंद्र ग्रहण के दौरान चंद्रमा प्रायः लालिमा लिए दिखता है क्योंकि पृथ्वी का वायुमंडल लाल प्रकाश को उस पर मोड़ता है। IV. सूर्य ग्रहण पूर्णिमा के दिन हो सकता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं: पृथ्वी की छाया पूरे चंद्रमा को ढक लेती है, परंतु चंद्रमा की छोटी छाया पृथ्वी पर केवल एक संकरा पथ बनाती है, और पृथ्वी के वायुमंडल से अपवर्तित लाल प्रकाश ग्रहणग्रस्त चंद्रमा को रंग देता है। IV गलत है क्योंकि सूर्य ग्रहण के लिए अमावस्या आवश्यक है।"},
  {"id":"geo-solar-system-104","question":"Arrange these space events in chronological order: 1. NASA’s DART spacecraft strikes the asteroid moon Dimorphos 2. The Philae lander touches down on comet 67P 3. OSIRIS-REx returns its sample of asteroid Bennu to the Earth 4. New Horizons flies past Pluto","options":["2, 4, 1, 3","4, 2, 3, 1","4, 2, 1, 3","2, 4, 3, 1"],"answer":0,"explanation":"Philae landed in November 2014, New Horizons passed Pluto in July 2015, DART hit Dimorphos in September 2022 and the OSIRIS-REx capsule landed in September 2023.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इन अंतरिक्ष घटनाओं को कालक्रम में व्यवस्थित कीजिए: 1. NASA का DART यान क्षुद्रग्रह चंद्रमा डाइमॉर्फोस से टकराता है 2. फिली लैंडर धूमकेतु 67P पर उतरता है 3. OSIRIS-REx क्षुद्रग्रह बेन्नू का नमूना पृथ्वी पर लौटाता है 4. न्यू हॉराइज़न्स प्लूटो के पास से उड़ान भरता है","optionsHi":["2, 4, 1, 3","4, 2, 3, 1","4, 2, 1, 3","2, 4, 3, 1"],"explanationHi":"फिली नवंबर 2014 में उतरा, न्यू हॉराइज़न्स जुलाई 2015 में प्लूटो के पास से गुज़रा, DART सितंबर 2022 में डाइमॉर्फोस से टकराया और OSIRIS-REx कैप्सूल सितंबर 2023 में उतरा।"},
  {"id":"geo-solar-system-105","question":"Match the mission with its target: 1. Hayabusa2 2. Rosetta 3. DART 4. Dawn; a. Vesta and Ceres b. Dimorphos c. Comet 67P/Churyumov–Gerasimenko d. Asteroid Ryugu","options":["1-c, 2-d, 3-b, 4-a","1-b, 2-c, 3-d, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-c, 3-b, 4-a"],"answer":3,"explanation":"Japan’s Hayabusa2 sampled Ryugu, ESA’s Rosetta orbited comet 67P, NASA’s DART deflected Dimorphos, and NASA’s Dawn orbited Vesta and then Ceres.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभियान का उसके लक्ष्य से मिलान कीजिए: 1. हायाबुसा2 2. रोसेटा 3. DART 4. डॉन; a. वेस्टा और सेरेस b. डाइमॉर्फोस c. धूमकेतु 67P/चुर्युमोव–गेरासिमेंको d. क्षुद्रग्रह रयुगु","optionsHi":["1-c, 2-d, 3-b, 4-a","1-b, 2-c, 3-d, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-c, 3-b, 4-a"],"explanationHi":"जापान के हायाबुसा2 ने रयुगु से नमूने लिए, ESA के रोसेटा ने धूमकेतु 67P की परिक्रमा की, NASA के DART ने डाइमॉर्फोस को विक्षेपित किया, और NASA के डॉन ने वेस्टा और फिर सेरेस की परिक्रमा की।"},
  {"id":"geo-solar-system-106","question":"Assertion (A): Jupiter radiates more energy into space than it receives from the Sun. Reason (R): Jupiter is still slowly contracting under its own gravity, which releases heat from its interior.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Jupiter gives out roughly 1.6–2 times the energy it absorbs; the extra comes from heat left over from its formation and from slow gravitational contraction, which converts potential energy into heat. So R explains A.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): बृहस्पति सूर्य से प्राप्त ऊर्जा से अधिक ऊर्जा अंतरिक्ष में विकीर्ण करता है। कारण (R): बृहस्पति अपने ही गुरुत्व के अधीन अब भी धीरे-धीरे सिकुड़ रहा है, जिससे उसके आंतरिक भाग से ऊष्मा मुक्त होती है।","optionsHi":["A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"बृहस्पति जितनी ऊर्जा अवशोषित करता है उसकी लगभग 1.6–2 गुना ऊर्जा बाहर देता है; यह अतिरिक्त ऊर्जा उसके निर्माण के समय बची ऊष्मा और धीमे गुरुत्वीय संकुचन से आती है, जो स्थितिज ऊर्जा को ऊष्मा में बदलता है। अतः R, A की व्याख्या करता है।"},
  {"id":"geo-solar-system-107","question":"A space probe is 5 AU from the Earth. Taking 1 AU = 1.5 × 10⁸ km and the speed of light as 3 × 10⁵ km/s, how long does it take for a command to reach the probe and its reply to come back?","options":["41 min 40 s","25 min","8 min 20 s","83 min 20 s"],"answer":3,"explanation":"Distance = 5 × 1.5 × 10⁸ = 7.5 × 10⁸ km; one way takes 7.5 × 10⁸ ÷ 3 × 10⁵ = 2,500 s = 41 min 40 s. The round trip is twice that, 5,000 s = 83 min 20 s; 41 min 40 s is only the one-way time.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"एक अंतरिक्ष यान पृथ्वी से 5 AU दूर है। 1 AU = 1.5 × 10⁸ किमी और प्रकाश की चाल 3 × 10⁵ किमी/से मानते हुए, किसी आदेश को यान तक पहुँचने और उसके उत्तर को वापस आने में कितना समय लगेगा?","optionsHi":["41 मिनट 40 सेकंड","25 मिनट","8 मिनट 20 सेकंड","83 मिनट 20 सेकंड"],"explanationHi":"दूरी = 5 × 1.5 × 10⁸ = 7.5 × 10⁸ किमी; एक ओर का समय 7.5 × 10⁸ ÷ 3 × 10⁵ = 2,500 सेकंड = 41 मिनट 40 सेकंड है। आना-जाना इसका दोगुना, 5,000 सेकंड = 83 मिनट 20 सेकंड है; 41 मिनट 40 सेकंड केवल एक ओर का समय है।"},
  {"id":"geo-solar-system-108","question":"How many of these statements about the Sun are correct? I. The temperature at its core is about 15 million K. II. Energy produced in the core takes many thousands of years to reach the surface. III. Nuclear fusion takes place mainly in the convective zone. IV. The Sun rotates faster at its equator than near its poles.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct: photons random-walk through the dense radiative zone for thousands of years or more, and the equator turns in about 25 days against about 35 near the poles. III is wrong because fusion occurs only in the core.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"सूर्य के बारे में इनमें से कितने कथन सही हैं? I. उसके क्रोड का तापमान लगभग 15 मिलियन K है। II. क्रोड में उत्पन्न ऊर्जा को सतह तक पहुँचने में कई हज़ार वर्ष लगते हैं। III. नाभिकीय संलयन मुख्यतः संवहन मंडल में होता है। IV. सूर्य अपने ध्रुवों के निकट की अपेक्षा अपनी विषुवत रेखा पर तेज़ घूर्णन करता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और IV सही हैं: फोटॉन सघन विकिरण मंडल में हज़ारों वर्ष या उससे अधिक समय तक यादृच्छिक गति करते हैं, और विषुवत रेखा लगभग 25 दिनों में घूमती है जबकि ध्रुवों के निकट लगभग 35 दिनों में। III गलत है क्योंकि संलयन केवल क्रोड में होता है।"},
  {"id":"geo-solar-system-109","question":"Match the layer of the Sun with its feature: 1. Core 2. Photosphere 3. Chromosphere 4. Corona; a. Outermost layer and source of the solar wind b. Hydrogen fuses into helium c. Thin reddish layer seen just at the start and end of totality d. Visible surface on which sunspots appear","options":["1-b, 2-d, 3-a, 4-c","1-b, 2-d, 3-c, 4-a","1-b, 2-c, 3-d, 4-a","1-d, 2-b, 3-c, 4-a"],"answer":1,"explanation":"Fusion happens in the core; the photosphere is the visible surface with sunspots; the chromosphere flashes red for a moment during totality; and the hot corona extends far out and streams away as the solar wind.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"सूर्य की परत का उसकी विशेषता से मिलान कीजिए: 1. क्रोड 2. प्रकाशमंडल 3. वर्णमंडल 4. कोरोना; a. सबसे बाहरी परत और सौर पवन का स्रोत b. हाइड्रोजन का हीलियम में संलयन होता है c. पूर्णता के आरंभ और अंत पर ही दिखने वाली पतली लालिमा लिए परत d. दृश्य सतह जिस पर सौर कलंक दिखते हैं","optionsHi":["1-b, 2-d, 3-a, 4-c","1-b, 2-d, 3-c, 4-a","1-b, 2-c, 3-d, 4-a","1-d, 2-b, 3-c, 4-a"],"explanationHi":"संलयन क्रोड में होता है; प्रकाशमंडल सौर कलंकों वाली दृश्य सतह है; वर्णमंडल पूर्णता के दौरान क्षण भर के लिए लाल चमकता है; और गर्म कोरोना बहुत दूर तक फैला है तथा सौर पवन के रूप में बहता रहता है।"},
  {"id":"geo-solar-system-110","question":"Which of the following statements about Pluto is NOT correct?","options":["Its orbit is more eccentric than that of any of the eight planets","It is larger than the Earth’s Moon","It has five known moons","It was discovered by Clyde Tombaugh in 1930"],"answer":1,"explanation":"Pluto is about 2,377 km across, smaller than the Moon’s 3,474 km. It was found by Clyde Tombaugh in 1930, has five known moons (Charon, Nix, Hydra, Kerberos, Styx), and its eccentricity (about 0.25) exceeds Mercury’s (about 0.21).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"प्लूटो के बारे में निम्नलिखित में से कौन-सा कथन सही नहीं है?","optionsHi":["उसकी कक्षा आठों ग्रहों में से किसी की भी कक्षा से अधिक उत्केंद्रीय है","वह पृथ्वी के चंद्रमा से बड़ा है","उसके पाँच ज्ञात चंद्रमा हैं","उसकी खोज क्लाइड टॉमबॉ ने 1930 में की थी"],"explanationHi":"प्लूटो का व्यास लगभग 2,377 किमी है, जो चंद्रमा के 3,474 किमी से छोटा है। उसकी खोज क्लाइड टॉमबॉ ने 1930 में की थी, उसके पाँच ज्ञात चंद्रमा हैं (शेरन, निक्स, हाइड्रा, केरबेरोस, स्टिक्स), और उसकी उत्केंद्रता (लगभग 0.25) बुध की (लगभग 0.21) से अधिक है।"},
  {"id":"geo-solar-system-111","question":"How many of these statements are correct? I. Spring tides occur at new moon and full moon. II. Neap tides occur at the first and last quarter phases. III. The tidal range is greatest during neap tides. IV. The Sun’s tide-raising force on the Earth is about twice that of the Moon.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only I and II are correct. When the Sun and Moon are in line (new and full moon) their pulls add up to give spring tides with the greatest range; at the quarters they act at right angles and give neap tides with the least range. The Moon’s tidal force is about twice the Sun’s because it is so much closer.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कितने कथन सही हैं? I. वृहत् ज्वार (स्प्रिंग टाइड) अमावस्या और पूर्णिमा को आते हैं। II. लघु ज्वार (नीप टाइड) प्रथम और अंतिम चतुर्थांश कलाओं में आते हैं। III. ज्वारीय परिसर लघु ज्वार के दौरान सर्वाधिक होता है। IV. पृथ्वी पर सूर्य का ज्वार-उत्पादक बल चंद्रमा के बल का लगभग दोगुना है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I और II सही हैं। जब सूर्य और चंद्रमा एक सीध में होते हैं (अमावस्या और पूर्णिमा) तो उनके खिंचाव जुड़कर सर्वाधिक परिसर वाले वृहत् ज्वार देते हैं; चतुर्थांशों पर वे समकोण पर कार्य करते हैं और न्यूनतम परिसर वाले लघु ज्वार देते हैं। चंद्रमा का ज्वारीय बल सूर्य के बल का लगभग दोगुना है क्योंकि वह कहीं अधिक निकट है।"},
  {"id":"geo-solar-system-112","question":"Assertion (A): Mars has seasons similar to those of the Earth. Reason (R): Mars has practically no tilt of its axis.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true but R is false. Mars’s axis is tilted about 25°, close to the Earth’s 23.5°, and that tilt is what gives it seasons; its seasons last about twice as long because its year is about 687 days.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): मंगल पर पृथ्वी जैसी ऋतुएँ होती हैं। कारण (R): मंगल की धुरी में व्यावहारिक रूप से कोई झुकाव नहीं है।","optionsHi":["A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"A सत्य है पर R असत्य है। मंगल की धुरी लगभग 25° झुकी है, जो पृथ्वी के 23.5° के निकट है, और यही झुकाव उसे ऋतुएँ देता है; उसकी ऋतुएँ लगभग दोगुनी लंबी होती हैं क्योंकि उसका वर्ष लगभग 687 दिनों का है।"},
  {"id":"geo-solar-system-113","question":"Arrange these moons in decreasing order of diameter: 1. Io 2. Titan 3. Europa 4. Callisto","options":["2, 4, 3, 1","2, 1, 4, 3","4, 2, 1, 3","2, 4, 1, 3"],"answer":3,"explanation":"Titan is about 5,150 km across, Callisto about 4,820 km, Io about 3,640 km and Europa about 3,120 km. Europa is the smallest of the four and is even smaller than the Earth’s Moon.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इन चंद्रमाओं को व्यास के घटते क्रम में व्यवस्थित कीजिए: 1. आयो 2. टाइटन 3. यूरोपा 4. कैलिस्टो","optionsHi":["2, 4, 3, 1","2, 1, 4, 3","4, 2, 1, 3","2, 4, 1, 3"],"explanationHi":"टाइटन का व्यास लगभग 5,150 किमी, कैलिस्टो का लगभग 4,820 किमी, आयो का लगभग 3,640 किमी और यूरोपा का लगभग 3,120 किमी है। यूरोपा चारों में सबसे छोटा है और पृथ्वी के चंद्रमा से भी छोटा है।"},
  {"id":"geo-solar-system-114","question":"How many of these statements about Lagrange points are correct? I. A system of two large bodies, such as the Sun and the Earth, has five Lagrange points. II. The Sun–Earth L1 point lies between the Sun and the Earth. III. The James Webb Space Telescope orbits around the Sun–Earth L2 point. IV. The L4 and L5 points are stable, which is why Trojan asteroids collect there.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. L1 (used by Aditya-L1 and SOHO) is sunward of the Earth and L2 (used by JWST) lies on the far side, both about 1.5 million km away; L1, L2 and L3 are unstable, while L4 and L5, 60° ahead of and behind the smaller body, are stable and gather Trojan asteroids.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"लैग्रेंज बिंदुओं के बारे में इनमें से कितने कथन सही हैं? I. सूर्य और पृथ्वी जैसे दो बड़े पिंडों वाली प्रणाली में पाँच लैग्रेंज बिंदु होते हैं। II. सूर्य–पृथ्वी L1 बिंदु सूर्य और पृथ्वी के बीच स्थित है। III. जेम्स वेब स्पेस टेलीस्कोप सूर्य–पृथ्वी L2 बिंदु के चारों ओर परिक्रमा करता है। IV. L4 और L5 बिंदु स्थिर हैं, इसीलिए ट्रोजन क्षुद्रग्रह वहाँ एकत्र होते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। L1 (आदित्य-L1 और SOHO द्वारा प्रयुक्त) पृथ्वी से सूर्य की ओर है और L2 (JWST द्वारा प्रयुक्त) दूसरी ओर है, दोनों लगभग 1.5 मिलियन किमी दूर हैं; L1, L2 और L3 अस्थिर हैं, जबकि छोटे पिंड से 60° आगे और पीछे स्थित L4 और L5 स्थिर हैं और ट्रोजन क्षुद्रग्रहों को एकत्र करते हैं।"},
  {"id":"geo-solar-system-115","question":"In which direction does the Earth rotate on its axis?","options":["East to west","West to east","North to south","South to north"],"answer":1,"explanation":"The Earth spins from west to east, which is why the Sun, Moon and stars appear to rise in the east and set in the west.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"पृथ्वी अपनी धुरी पर किस दिशा में घूर्णन करती है?","optionsHi":["पूर्व से पश्चिम","पश्चिम से पूर्व","उत्तर से दक्षिण","दक्षिण से उत्तर"],"explanationHi":"पृथ्वी पश्चिम से पूर्व की ओर घूमती है, इसीलिए सूर्य, चंद्रमा और तारे पूर्व में उदय और पश्चिम में अस्त होते प्रतीत होते हैं।"},
  {"id":"geo-solar-system-116","question":"The line of 0° longitude, from which places are measured east or west, is called the:","options":["Equator","Tropic of Cancer","Prime Meridian","International Date Line"],"answer":2,"explanation":"The Prime Meridian passes through Greenwich near London. The equator is 0° latitude, and the Date Line roughly follows 180°.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"0° देशांतर की रेखा, जिससे स्थानों को पूर्व या पश्चिम की ओर मापा जाता है, क्या कहलाती है?","optionsHi":["विषुवत रेखा","कर्क रेखा","प्रधान याम्योत्तर","अंतर्राष्ट्रीय तिथि रेखा"],"explanationHi":"प्रधान याम्योत्तर लंदन के पास ग्रीनविच से गुज़रती है। विषुवत रेखा 0° अक्षांश है, और तिथि रेखा मोटे तौर पर 180° का अनुसरण करती है।"},
  {"id":"geo-solar-system-117","question":"The change of seasons on the Earth is caused mainly by:","options":["Changes in the Earth's distance from the Sun","The changing phases of the Moon each month","Changes in the Sun's energy output over the year","The tilt of Earth's axis during its revolution"],"answer":3,"explanation":"Because the axis stays tilted about 23.5° in the same direction, each hemisphere in turn leans towards the Sun, getting higher sun and longer days. Distance plays only a small role.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"पृथ्वी पर ऋतु परिवर्तन मुख्यतः किसके कारण होता है?","optionsHi":["पृथ्वी की सूर्य से दूरी में परिवर्तन","प्रत्येक महीने चंद्रमा की बदलती कलाएँ","वर्ष भर सूर्य की ऊर्जा उत्सर्जन में परिवर्तन","परिक्रमा के दौरान पृथ्वी की धुरी का झुकाव"],"explanationHi":"क्योंकि धुरी एक ही दिशा में लगभग 23.5° झुकी रहती है, प्रत्येक गोलार्ध बारी-बारी से सूर्य की ओर झुकता है और उसे ऊँचा सूर्य तथा लंबे दिन मिलते हैं। दूरी की भूमिका केवल थोड़ी है।"},
  {"id":"geo-solar-system-118","question":"Around 21 June (the June solstice), the midday Sun is directly overhead at the:","options":["Tropic of Cancer","Equator","Tropic of Capricorn","Arctic Circle"],"answer":0,"explanation":"At the June solstice the northern hemisphere leans most towards the Sun, so the overhead Sun reaches its northern limit, 23.5°N. Around 22 December it is over the Tropic of Capricorn.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"लगभग 21 जून (जून अयनांत) को दोपहर का सूर्य कहाँ सीधे सिर के ऊपर होता है?","optionsHi":["कर्क रेखा","विषुवत रेखा","मकर रेखा","आर्कटिक वृत्त"],"explanationHi":"जून अयनांत पर उत्तरी गोलार्ध सूर्य की ओर सबसे अधिक झुका होता है, इसलिए सिर के ऊपर का सूर्य अपनी उत्तरी सीमा, 23.5°N, तक पहुँचता है। लगभग 22 दिसंबर को वह मकर रेखा के ऊपर होता है।"},
  {"id":"geo-solar-system-119","question":"The equinoxes, when day and night are nearly equal all over the world, fall around:","options":["21 June and 22 December","21 March and 23 September","3 January and 4 July","1 May and 1 November"],"answer":1,"explanation":"On about 21 March and 23 September the Sun is overhead at the equator. 21 June and 22 December are the solstices; early January and early July are perihelion and aphelion.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"विषुव, जब पूरे विश्व में दिन और रात लगभग बराबर होते हैं, लगभग किन तिथियों को पड़ते हैं?","optionsHi":["21 जून और 22 दिसंबर","21 मार्च और 23 सितंबर","3 जनवरी और 4 जुलाई","1 मई और 1 नवंबर"],"explanationHi":"लगभग 21 मार्च और 23 सितंबर को सूर्य विषुवत रेखा पर सिर के ऊपर होता है। 21 जून और 22 दिसंबर अयनांत हैं; जनवरी और जुलाई के आरंभ में उपसौर और अपसौर होते हैं।"},
  {"id":"geo-solar-system-120","question":"Two places differ in longitude by 30°. The difference in their local times is:","options":["30 minutes","1 hour","2 hours","4 hours"],"answer":2,"explanation":"The Earth turns 360° in 24 hours, that is 15° per hour or 1° every 4 minutes, so 30° means 2 hours.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"दो स्थानों के देशांतर में 30° का अंतर है। उनके स्थानीय समय का अंतर है:","optionsHi":["30 मिनट","1 घंटा","2 घंटे","4 घंटे"],"explanationHi":"पृथ्वी 24 घंटे में 360° घूमती है, अर्थात 15° प्रति घंटा या प्रत्येक 4 मिनट में 1°, इसलिए 30° का अर्थ 2 घंटे है।"},
  {"id":"geo-solar-system-121","question":"A ship sailing eastward from Asia to America crosses the International Date Line. Its calendar should:","options":["Be set back by one day, repeating a date","Be advanced by one day, skipping a date","Stay unchanged, as only the clock moves","Be advanced by 12 hours at midnight"],"answer":0,"explanation":"Moving east, a traveller has been gaining time zone by zone; crossing the Date Line eastward cancels this by repeating a day. Crossing it westward skips a day.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"एशिया से अमेरिका की ओर पूर्व दिशा में चल रहा एक जहाज़ अंतर्राष्ट्रीय तिथि रेखा पार करता है। उसका कैलेंडर:","optionsHi":["एक दिन पीछे कर दिया जाना चाहिए, एक तिथि दोहराते हुए","एक दिन आगे बढ़ा दिया जाना चाहिए, एक तिथि छोड़ते हुए","अपरिवर्तित रहना चाहिए, केवल घड़ी बदलती है","मध्यरात्रि पर 12 घंटे आगे बढ़ा दिया जाना चाहिए"],"explanationHi":"पूर्व की ओर चलने पर यात्री क्षेत्र-दर-क्षेत्र समय प्राप्त करता जाता है; तिथि रेखा को पूर्व की ओर पार करने पर एक दिन दोहराकर यह संतुलित हो जाता है। उसे पश्चिम की ओर पार करने पर एक दिन छूट जाता है।"},
  {"id":"geo-solar-system-122","question":"When the local time at a place on 82.5°E is 12 noon, what is the local time at Greenwich (0°)?","options":["5:30 pm","6:30 pm","5:30 am","6:30 am"],"answer":3,"explanation":"82.5° × 4 minutes = 330 minutes = 5 h 30 min. Greenwich lies to the west, so its time is behind: 12:00 − 5:30 = 6:30 am.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"जब 82.5°E पर स्थित किसी स्थान का स्थानीय समय दोपहर 12 बजे है, तब ग्रीनविच (0°) का स्थानीय समय क्या है?","optionsHi":["शाम 5:30 बजे","शाम 6:30 बजे","सुबह 5:30 बजे","सुबह 6:30 बजे"],"explanationHi":"82.5° × 4 मिनट = 330 मिनट = 5 घंटे 30 मिनट। ग्रीनविच पश्चिम में है, इसलिए उसका समय पीछे है: 12:00 − 5:30 = सुबह 6:30।"},
  {"id":"geo-solar-system-123","question":"Around 22 December, which of these places experiences 24 hours of darkness?","options":["Places on the Tropic of Cancer","Places on the equator","Places north of the Arctic Circle","Places on the Tropic of Capricorn"],"answer":2,"explanation":"At the December solstice the North Pole is tilted away from the Sun, so everywhere north of the Arctic Circle (66.5°N) has at least one day without sunrise; the area south of the Antarctic Circle has continuous daylight.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"लगभग 22 दिसंबर को इनमें से किन स्थानों पर 24 घंटे का अंधकार रहता है?","optionsHi":["कर्क रेखा पर स्थित स्थान","विषुवत रेखा पर स्थित स्थान","आर्कटिक वृत्त के उत्तर में स्थित स्थान","मकर रेखा पर स्थित स्थान"],"explanationHi":"दिसंबर अयनांत पर उत्तरी ध्रुव सूर्य से दूर झुका होता है, इसलिए आर्कटिक वृत्त (66.5°N) के उत्तर में हर जगह कम से कम एक दिन सूर्योदय नहीं होता; अंटार्कटिक वृत्त के दक्षिण का क्षेत्र निरंतर दिन के प्रकाश में रहता है।"},
  {"id":"geo-solar-system-124","question":"Day and night are of nearly equal length at the equator throughout the year because:","options":["The equator is the part of Earth closest to the Sun","The circle of illumination always bisects the equator","The Earth's surface spins fastest at the equator","The equator has no distinct seasons of rainfall"],"answer":1,"explanation":"The boundary between day and night is a great circle, and it always cuts the equator (another great circle) exactly in half, so equatorial days stay close to 12 hours.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"विषुवत रेखा पर पूरे वर्ष दिन और रात की लंबाई लगभग बराबर रहती है क्योंकि:","optionsHi":["विषुवत रेखा पृथ्वी का सूर्य के सबसे निकट का भाग है","प्रदीप्ति वृत्त सदैव विषुवत रेखा को दो बराबर भागों में बाँटता है","पृथ्वी की सतह विषुवत रेखा पर सबसे तेज़ घूमती है","विषुवत रेखा पर वर्षा की कोई स्पष्ट ऋतुएँ नहीं होतीं"],"explanationHi":"दिन और रात के बीच की सीमा एक वृहत् वृत्त है, और वह सदैव विषुवत रेखा (एक अन्य वृहत् वृत्त) को ठीक आधा काटती है, इसलिए विषुवतीय दिन लगभग 12 घंटे के बने रहते हैं।"},
  {"id":"geo-solar-system-125","question":"The true shape of the Earth is best described as:","options":["A perfect sphere with no flattening","Flattened at the equator, bulging at the poles","An oblate spheroid, flattened at the poles","A flat disc with a raised centre"],"answer":2,"explanation":"Rotation makes the Earth bulge at the equator; the polar diameter is about 43 km shorter than the equatorial one. The irregular real shape is called the geoid.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"पृथ्वी के वास्तविक आकार का सबसे अच्छा वर्णन है:","optionsHi":["बिना चपटेपन का पूर्ण गोला","विषुवत रेखा पर चपटी, ध्रुवों पर उभरी हुई","ध्रुवों पर चपटा गोलाभ (ओब्लेट स्फेरॉइड)","केंद्र पर उभरी हुई चपटी चकती"],"explanationHi":"घूर्णन के कारण पृथ्वी विषुवत रेखा पर उभरती है; ध्रुवीय व्यास विषुवतीय व्यास से लगभग 43 किमी छोटा है। इसके अनियमित वास्तविक आकार को भूआभ (जियॉइड) कहते हैं।"},
  {"id":"geo-solar-system-126","question":"A geostationary communication satellite orbits above the equator at a height of roughly:","options":["36,000 km","400 km","3,600 km","3,84,000 km"],"answer":0,"explanation":"At about 35,786 km, a satellite's period equals one sidereal day, so it appears fixed over one spot. About 400 km is the height of the International Space Station; 3,84,000 km is the Moon's distance.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"एक भूस्थिर संचार उपग्रह विषुवत रेखा के ऊपर लगभग किस ऊँचाई पर परिक्रमा करता है?","optionsHi":["36,000 किमी","400 किमी","3,600 किमी","3,84,000 किमी"],"explanationHi":"लगभग 35,786 किमी पर उपग्रह का आवर्तकाल एक नक्षत्र दिवस के बराबर होता है, इसलिए वह किसी एक स्थान के ऊपर स्थिर दिखाई देता है। लगभग 400 किमी अंतर्राष्ट्रीय अंतरिक्ष स्टेशन की ऊँचाई है; 3,84,000 किमी चंद्रमा की दूरी है।"},
  {"id":"geo-solar-system-127","question":"The sidereal day (one rotation relative to the stars) is about 4 minutes shorter than the solar day because:","options":["The Earth's spin slows down a little every night","The Moon's gravity drags the Earth's spin back daily","The Sun itself moves around the Earth once a day","Orbital motion makes Earth turn ~1° extra each day"],"answer":3,"explanation":"Each day the Earth advances about 1° in its orbit, so it must rotate roughly 361° to face the Sun again; that extra 1° takes about 4 minutes, giving 24 h against 23 h 56 min.","difficulty":"hard","source":"UPSC Prelims","questionHi":"नक्षत्र दिवस (तारों के सापेक्ष एक घूर्णन) सौर दिवस से लगभग 4 मिनट छोटा होता है, क्योंकि:","optionsHi":["पृथ्वी का घूर्णन हर रात थोड़ा धीमा हो जाता है","चंद्रमा का गुरुत्व प्रतिदिन पृथ्वी के घूर्णन को पीछे खींचता है","सूर्य स्वयं दिन में एक बार पृथ्वी की परिक्रमा करता है","कक्षीय गति के कारण पृथ्वी को प्रतिदिन ~1° अधिक घूमना पड़ता है"],"explanationHi":"प्रतिदिन पृथ्वी अपनी कक्षा में लगभग 1° आगे बढ़ जाती है, इसलिए सूर्य के सामने फिर आने के लिए उसे लगभग 361° घूमना पड़ता है; वह अतिरिक्त 1° लगभग 4 मिनट लेता है, जिससे 24 घंटे बनाम 23 घंटे 56 मिनट का अंतर आता है।"},
  {"id":"geo-solar-system-128","question":"How many of these statements are correct? I. At the equinoxes the midday Sun is overhead at the equator. II. Around 21 June the midday Sun is overhead at the Tropic of Cancer. III. On the equinoxes, places such as Chennai and Delhi have roughly 12 hours of day and 12 hours of night. IV. Around 21 June the Sun does not set at places on the Arctic Circle.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. At the equinoxes the Sun is overhead at the equator and day and night are each about 12 hours at places away from the poles; at the June solstice it is overhead at the Tropic of Cancer and the Arctic Circle has 24 hours of daylight.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. विषुवों पर दोपहर का सूर्य विषुवत रेखा पर सिर के ऊपर होता है। II. लगभग 21 जून को दोपहर का सूर्य कर्क रेखा पर सिर के ऊपर होता है। III. विषुवों पर चेन्नई और दिल्ली जैसे स्थानों में लगभग 12 घंटे का दिन और 12 घंटे की रात होती है। IV. लगभग 21 जून को आर्कटिक वृत्त पर स्थित स्थानों पर सूर्य अस्त नहीं होता।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। विषुवों पर सूर्य विषुवत रेखा पर सिर के ऊपर होता है और ध्रुवों से दूर के स्थानों पर दिन और रात प्रत्येक लगभग 12 घंटे के होते हैं; जून अयनांत पर वह कर्क रेखा पर सिर के ऊपर होता है और आर्कटिक वृत्त पर 24 घंटे का दिन होता है।"},
  {"id":"geo-solar-system-129","question":"Arrange these events in the order they occur in a calendar year: 1. Aphelion  2. June solstice  3. Perihelion  4. March equinox","options":["3-4-2-1","4-3-2-1","3-4-1-2","3-2-4-1"],"answer":0,"explanation":"Perihelion (Earth nearest the Sun) comes around 3 January, the March equinox around 20–21 March, the June solstice around 21 June and aphelion (farthest) around 4 July.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन घटनाओं को एक कैलेंडर वर्ष में घटित होने के क्रम में व्यवस्थित कीजिए: 1. अपसौर  2. जून अयनांत  3. उपसौर  4. मार्च विषुव","optionsHi":["3-4-2-1","4-3-2-1","3-4-1-2","3-2-4-1"],"explanationHi":"उपसौर (पृथ्वी सूर्य के निकटतम) लगभग 3 जनवरी को, मार्च विषुव लगभग 20–21 मार्च को, जून अयनांत लगभग 21 जून को और अपसौर (सबसे दूर) लगभग 4 जुलाई को पड़ता है।"},
  {"id":"geo-solar-system-130","question":"A cricket match begins at 9:00 am local time in a city at 75°E. What is the local time at that moment in a city at 45°W?","options":["5:00 pm the same day","1:00 am the same day","3:00 am the same day","9:00 pm the previous day"],"answer":1,"explanation":"The longitude difference is 75 + 45 = 120°, that is 120 × 4 = 480 minutes or 8 hours. The western city is behind, so 9:00 am − 8 h = 1:00 am on the same date.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"75°E पर स्थित एक शहर में स्थानीय समय सुबह 9:00 बजे एक क्रिकेट मैच शुरू होता है। उस क्षण 45°W पर स्थित शहर में स्थानीय समय क्या है?","optionsHi":["उसी दिन शाम 5:00 बजे","उसी दिन रात 1:00 बजे","उसी दिन सुबह 3:00 बजे","पिछले दिन रात 9:00 बजे"],"explanationHi":"देशांतर का अंतर 75 + 45 = 120° है, अर्थात 120 × 4 = 480 मिनट या 8 घंटे। पश्चिमी शहर पीछे है, इसलिए सुबह 9:00 − 8 घंटे = उसी तारीख को रात 1:00 बजे।"},
  {"id":"geo-solar-system-131","question":"Match the term with its meaning. A. Perihelion  B. Aphelion  C. Solstice  D. Equinox; 1. Sun overhead at the equator, day and night nearly equal  2. Earth at its nearest point to the Sun  3. Earth at its farthest point from the Sun  4. Sun overhead at a tropic, giving the longest or shortest day","options":["A-3, B-2, C-4, D-1","A-2, B-3, C-1, D-4","A-2, B-3, C-4, D-1","A-2, B-4, C-3, D-1"],"answer":2,"explanation":"Peri- means near and ap- means away, so perihelion is the closest approach and aphelion the farthest. Solstices mark the Sun's turning point at a tropic; equinoxes put it over the equator.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"शब्द का मिलान उसके अर्थ से कीजिए। A. उपसौर  B. अपसौर  C. अयनांत  D. विषुव; 1. सूर्य विषुवत रेखा पर सिर के ऊपर, दिन और रात लगभग बराबर  2. पृथ्वी का सूर्य से निकटतम बिंदु  3. पृथ्वी का सूर्य से सबसे दूर का बिंदु  4. सूर्य एक कटिबंध रेखा पर सिर के ऊपर, जिससे सबसे लंबा या सबसे छोटा दिन होता है","optionsHi":["A-3, B-2, C-4, D-1","A-2, B-3, C-1, D-4","A-2, B-3, C-4, D-1","A-2, B-4, C-3, D-1"],"explanationHi":"Peri- का अर्थ निकट और ap- का अर्थ दूर है, इसलिए उपसौर निकटतम स्थिति और अपसौर सबसे दूर की स्थिति है। अयनांत किसी कटिबंध रेखा पर सूर्य के मोड़ बिंदु को चिह्नित करते हैं; विषुव उसे विषुवत रेखा पर ले आते हैं।"},
  {"id":"geo-solar-system-132","question":"Assertion (A): The northern hemisphere has its summer when the Earth is near its farthest point from the Sun. Reason (R): Seasons are governed mainly by the tilt of the Earth's axis, not by its distance from the Sun.","options":["A is true but R is false","Both A and R are true but R is not the correct explanation of A","A is false but R is true","Both A and R are true and R is the correct explanation of A"],"answer":3,"explanation":"Aphelion falls in early July, in the middle of the northern summer. The tilt, which brings higher sun and longer days to the hemisphere leaning sunward, outweighs the roughly 3% change in distance.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): उत्तरी गोलार्ध में ग्रीष्म ऋतु तब होती है जब पृथ्वी सूर्य से अपने सबसे दूर के बिंदु के निकट होती है। कारण (R): ऋतुएँ मुख्यतः पृथ्वी की धुरी के झुकाव से नियंत्रित होती हैं, सूर्य से उसकी दूरी से नहीं।","optionsHi":["A सत्य है, परंतु R असत्य है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A असत्य है, परंतु R सत्य है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है"],"explanationHi":"अपसौर जुलाई के आरंभ में, उत्तरी ग्रीष्म के मध्य में, पड़ता है। झुकाव, जो सूर्य की ओर झुके गोलार्ध को ऊँचा सूर्य और लंबे दिन देता है, दूरी में लगभग 3% के परिवर्तन पर भारी पड़ता है।"},
  {"id":"geo-solar-system-133","question":"How many of these statements about latitude and longitude are correct? I. One degree of latitude spans roughly 111 km everywhere. II. One degree of longitude spans about 111 km everywhere on the Earth. III. All parallels of latitude are of equal length. IV. All parallels of latitude are great circles.","options":["Only three","Only one","Only two","All four"],"answer":1,"explanation":"Only I is correct. A degree of longitude is about 111 km only at the equator and shrinks to zero at the poles; parallels shrink towards the poles, so they are unequal, and only the equator is a great circle.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अक्षांश और देशांतर के बारे में इनमें से कितने कथन सही हैं? I. अक्षांश का एक अंश सर्वत्र लगभग 111 किमी होता है। II. देशांतर का एक अंश पृथ्वी पर सर्वत्र लगभग 111 किमी होता है। III. अक्षांश की सभी समानांतर रेखाएँ समान लंबाई की होती हैं। IV. अक्षांश की सभी समानांतर रेखाएँ वृहत् वृत्त होती हैं।","optionsHi":["केवल तीन","केवल एक","केवल दो","सभी चार"],"explanationHi":"केवल I सही है। देशांतर का एक अंश लगभग 111 किमी केवल विषुवत रेखा पर होता है और ध्रुवों पर शून्य हो जाता है; समानांतर रेखाएँ ध्रुवों की ओर छोटी होती जाती हैं, इसलिए वे असमान हैं, और केवल विषुवत रेखा वृहत् वृत्त है।"},
  {"id":"geo-solar-system-134","question":"How many of these statements about leap years in the Gregorian calendar are correct? I. A leap day is added because the year is about 365¼ days long. II. A century year is a leap year only if it is divisible by 400. III. 1900 was not a leap year. IV. 2100 will be a leap year.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct; 2000 was a leap year because it divides by 400. 2100 is divisible by 100 but not by 400, so it will not be a leap year, and IV is wrong.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"ग्रेगोरियन कैलेंडर में अधिवर्ष (लीप वर्ष) के बारे में इनमें से कितने कथन सही हैं? I. एक अतिरिक्त दिन जोड़ा जाता है क्योंकि वर्ष लगभग 365¼ दिन का होता है। II. शताब्दी वर्ष तभी अधिवर्ष होता है जब वह 400 से विभाज्य हो। III. 1900 अधिवर्ष नहीं था। IV. 2100 अधिवर्ष होगा।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं; 2000 अधिवर्ष था क्योंकि वह 400 से विभाज्य है। 2100, 100 से विभाज्य है पर 400 से नहीं, इसलिए वह अधिवर्ष नहीं होगा, और IV गलत है।"},
  {"id":"geo-solar-system-135","question":"Assertion (A): Twilight lasts much longer at high latitudes than near the equator. Reason (R): At high latitudes the Sun's daily path meets the horizon at a shallow angle, so it takes longer to sink well below the horizon.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Near the equator the Sun drops almost vertically and darkness comes quickly; near the poles it slants along the horizon, giving long dusks and, in summer, the 'white nights'.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): उच्च अक्षांशों पर गोधूलि विषुवत रेखा के निकट की तुलना में बहुत लंबी चलती है। कारण (R): उच्च अक्षांशों पर सूर्य का दैनिक पथ क्षितिज से उथले कोण पर मिलता है, इसलिए उसे क्षितिज से भली-भाँति नीचे डूबने में अधिक समय लगता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"विषुवत रेखा के निकट सूर्य लगभग लंबवत नीचे गिरता है और अंधेरा शीघ्र हो जाता है; ध्रुवों के निकट वह क्षितिज के साथ तिरछा चलता है, जिससे लंबी संध्याएँ और गर्मियों में ‘श्वेत रातें’ होती हैं।"},
  {"id":"geo-solar-system-136","question":"An asteroid orbits the Sun at a mean distance of 4 AU. By Kepler's third law, its orbital period is about:","options":["4 years","8 years","16 years","2 years"],"answer":1,"explanation":"For bodies orbiting the Sun, T² = a³ with T in years and a in AU: T² = 64, so T = 8 years. 16 years wrongly squares the distance, and 4 years assumes period grows in simple proportion.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"एक क्षुद्रग्रह सूर्य की परिक्रमा 4 AU की माध्य दूरी पर करता है। केपलर के तृतीय नियम से, उसका परिक्रमण काल लगभग है:","optionsHi":["4 वर्ष","8 वर्ष","16 वर्ष","2 वर्ष"],"explanationHi":"सूर्य की परिक्रमा करने वाले पिंडों के लिए T² = a³, जहाँ T वर्षों में और a AU में है: T² = 64, अतः T = 8 वर्ष। 16 वर्ष दूरी का वर्ग करना गलत है, और 4 वर्ष मान लेता है कि आवर्तकाल सरल अनुपात में बढ़ता है।"},
  {"id":"geo-solar-system-137","question":"How many of these statements about Venus are correct? I. It rotates in the opposite direction to most planets. II. Its sidereal day (one rotation) is longer than its year. III. It has no natural moon. IV. Its surface is cooler than Mercury's because it is farther from the Sun.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct: Venus takes about 243 Earth days to rotate and 225 days to orbit. Its dense carbon-dioxide atmosphere creates a runaway greenhouse effect, making it the hottest planet, hotter than Mercury, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"शुक्र के बारे में इनमें से कितने कथन सही हैं? I. वह अधिकांश ग्रहों की विपरीत दिशा में घूर्णन करता है। II. उसका नक्षत्र दिवस (एक घूर्णन) उसके वर्ष से लंबा है। III. उसका कोई प्राकृतिक चंद्रमा नहीं है। IV. उसकी सतह बुध से ठंडी है क्योंकि वह सूर्य से अधिक दूर है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं: शुक्र को घूर्णन में लगभग 243 पृथ्वी दिन और परिक्रमा में 225 दिन लगते हैं। उसका घना कार्बन डाइऑक्साइड वायुमंडल अनियंत्रित ग्रीनहाउस प्रभाव उत्पन्न करता है, जिससे वह बुध से भी अधिक गर्म, सबसे गर्म ग्रह है, इसलिए IV गलत है।"},
  {"id":"geo-solar-system-138","question":"Which statement about the sources of comets is correct?","options":["Short-period from the Oort cloud, long-period from the Kuiper belt","Both kinds come mainly from the asteroid belt beyond Mars","The Oort cloud lies between the orbits of Mars and Jupiter","Short-period from the Kuiper belt, long-period from the Oort cloud"],"answer":3,"explanation":"The Kuiper belt and scattered disc beyond Neptune supply comets that return within about 200 years, such as Halley's; the far-off, spherical Oort cloud sends in comets with periods of thousands of years from all directions.","difficulty":"hard","source":"UPSC Prelims","questionHi":"धूमकेतुओं के स्रोतों के बारे में कौन-सा कथन सही है?","optionsHi":["अल्प-आवर्तकाल वाले ऊर्ट बादल से, दीर्घ-आवर्तकाल वाले कुइपर पट्टी से","दोनों प्रकार मुख्यतः मंगल से परे क्षुद्रग्रह पट्टी से आते हैं","ऊर्ट बादल मंगल और बृहस्पति की कक्षाओं के बीच स्थित है","अल्प-आवर्तकाल वाले कुइपर पट्टी से, दीर्घ-आवर्तकाल वाले ऊर्ट बादल से"],"explanationHi":"वरुण से परे की कुइपर पट्टी और प्रकीर्णित चकती उन धूमकेतुओं की आपूर्ति करती हैं जो लगभग 200 वर्षों के भीतर लौट आते हैं, जैसे हैली; दूरस्थ, गोलाकार ऊर्ट बादल सभी दिशाओं से हज़ारों वर्षों के आवर्तकाल वाले धूमकेतु भेजता है।"},
  {"id":"geo-solar-system-139","question":"Match the moon with its feature. A. Titan  B. Europa  C. Io  D. Enceladus; 1. The most volcanically active body in the Solar System  2. Moon of Saturn with a thick, nitrogen-rich atmosphere  3. Moon of Saturn that sprays jets of water vapour from its south polar region  4. Icy moon of Jupiter thought to hide an ocean beneath its crust","options":["A-2, B-4, C-1, D-3","A-3, B-4, C-1, D-2","A-2, B-1, C-4, D-3","A-2, B-4, C-3, D-1"],"answer":0,"explanation":"Titan is the only moon with a dense atmosphere; Europa and Enceladus are icy moons with subsurface oceans (Enceladus venting plumes); tidal heating from Jupiter keeps Io's volcanoes erupting.","difficulty":"hard","source":"UPSC Prelims","questionHi":"चंद्रमा का मिलान उसकी विशेषता से कीजिए। A. टाइटन  B. यूरोपा  C. आयो  D. एन्सेलेडस; 1. सौरमंडल का सबसे अधिक ज्वालामुखीय सक्रियता वाला पिंड  2. शनि का चंद्रमा जिसका वायुमंडल घना और नाइट्रोजन-समृद्ध है  3. शनि का चंद्रमा जो अपने दक्षिणी ध्रुवीय क्षेत्र से जलवाष्प की धाराएँ छोड़ता है  4. बृहस्पति का बर्फीला चंद्रमा जिसकी पर्पटी के नीचे महासागर छिपा माना जाता है","optionsHi":["A-2, B-4, C-1, D-3","A-3, B-4, C-1, D-2","A-2, B-1, C-4, D-3","A-2, B-4, C-3, D-1"],"explanationHi":"टाइटन एकमात्र चंद्रमा है जिसका वायुमंडल घना है; यूरोपा और एन्सेलेडस उपसतही महासागरों वाले बर्फीले चंद्रमा हैं (एन्सेलेडस फव्वारे छोड़ता है); बृहस्पति से ज्वारीय तापन आयो के ज्वालामुखियों को फूटते रखता है।"},
  {"id":"geo-solar-system-140","question":"Galileo's observation that Venus shows a full set of phases, like the Moon, was important because:","options":["it proved that Venus has a thick cloudy atmosphere","it showed that Venus rotates in the opposite direction","only a Venus orbiting the Sun could show it, refuting Ptolemy","it proved that the Earth's orbit is an ellipse, not a circle"],"answer":2,"explanation":"In Ptolemy's scheme Venus always stays between the Earth and the Sun and could never appear full; the full cycle of phases, with size changes, fits a Venus circling the Sun, supporting Copernicus.","difficulty":"hard","source":"UPSC Prelims","questionHi":"गैलीलियो का यह प्रेक्षण कि शुक्र चंद्रमा की तरह कलाओं का पूरा क्रम दिखाता है, महत्वपूर्ण क्यों था?","optionsHi":["इससे सिद्ध हुआ कि शुक्र का वायुमंडल घना और बादलों वाला है","इससे दिखा कि शुक्र विपरीत दिशा में घूर्णन करता है","इसे केवल सूर्य की परिक्रमा करने वाला शुक्र ही दिखा सकता था, जिससे टॉलेमी का मत खंडित हुआ","इससे सिद्ध हुआ कि पृथ्वी की कक्षा वृत्ताकार नहीं, दीर्घवृत्ताकार है"],"explanationHi":"टॉलेमी की योजना में शुक्र सदैव पृथ्वी और सूर्य के बीच रहता है और कभी पूर्ण नहीं दिख सकता था; आकार-परिवर्तन के साथ कलाओं का पूरा चक्र सूर्य की परिक्रमा करते शुक्र के अनुरूप है, जो कोपरनिकस का समर्थन करता है।"},
  {"id":"geo-solar-system-141","question":"Each pole of Uranus gets about 42 years of continuous sunlight followed by about 42 years of darkness. This is mainly because:","options":["its axis is tilted about 98° and its orbit takes about 84 years","its orbit is highly eccentric, swinging it far from the Sun","it has no internal heat source to warm the dark side","it rotates in the retrograde direction like Venus does"],"answer":0,"explanation":"With the axis lying nearly in the orbital plane, each pole points towards the Sun for about half of the 84-year orbit. Eccentricity changes distance, not day–night length.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"अरुण के प्रत्येक ध्रुव को लगभग 42 वर्ष निरंतर सूर्य का प्रकाश मिलता है और उसके बाद लगभग 42 वर्ष अंधकार रहता है। इसका मुख्य कारण है:","optionsHi":["उसकी धुरी लगभग 98° झुकी है और उसकी कक्षा लगभग 84 वर्षों की है","उसकी कक्षा अत्यधिक उत्केंद्रीय है, जो उसे सूर्य से बहुत दूर ले जाती है","उसके पास अंधेरे पक्ष को गर्म करने वाला कोई आंतरिक ऊष्मा स्रोत नहीं है","वह शुक्र की तरह वक्री दिशा में घूर्णन करता है"],"explanationHi":"धुरी के लगभग कक्षीय तल में पड़ी होने के कारण, प्रत्येक ध्रुव 84 वर्ष की कक्षा के लगभग आधे भाग में सूर्य की ओर रहता है। उत्केंद्रता दूरी बदलती है, दिन–रात की लंबाई नहीं।"},
  {"id":"geo-solar-system-142","question":"From India, Venus can never be seen high in the sky at midnight, whereas Jupiter often can. This is because:","options":["Venus is too faint to be seen in the night sky","Venus, an inferior planet, never strays beyond ~47° of the Sun","the thick clouds of Venus reflect sunlight only at dawn","Jupiter shines by its own light, while Venus only reflects"],"answer":1,"explanation":"Planets inside the Earth's orbit stay close to the Sun in the sky, appearing only as 'morning' or 'evening stars'; outer planets reach opposition and are highest around midnight. Venus is actually the brightest planet.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारत से शुक्र मध्यरात्रि को आकाश में कभी ऊँचा नहीं दिख सकता, जबकि बृहस्पति प्रायः दिख जाता है। इसका कारण है:","optionsHi":["शुक्र रात के आकाश में दिखने के लिए बहुत धुँधला है","शुक्र, एक आंतरिक ग्रह होने के कारण, सूर्य से ~47° से अधिक दूर कभी नहीं जाता","शुक्र के घने बादल सूर्य के प्रकाश को केवल भोर में परावर्तित करते हैं","बृहस्पति अपने स्वयं के प्रकाश से चमकता है, जबकि शुक्र केवल परावर्तित करता है"],"explanationHi":"पृथ्वी की कक्षा के भीतर के ग्रह आकाश में सूर्य के निकट रहते हैं और केवल ‘भोर’ या ‘सांध्य तारे’ के रूप में दिखते हैं; बाह्य ग्रह प्रतिमुख (अपोज़िशन) पर पहुँचते हैं और मध्यरात्रि के आसपास सबसे ऊँचे होते हैं। वास्तव में शुक्र सबसे चमकीला ग्रह है।"},
  {"id":"geo-solar-system-143","question":"Match the feature with its description. A. Olympus Mons  B. Great Red Spot  C. Valles Marineris  D. Caloris Basin; 1. Vast canyon system on Mars  2. Giant long-lived anticyclonic storm on Jupiter  3. Largest known volcano in the Solar System, on Mars  4. Large impact basin on Mercury","options":["A-1, B-2, C-3, D-4","A-3, B-4, C-1, D-2","A-3, B-2, C-4, D-1","A-3, B-2, C-1, D-4"],"answer":3,"explanation":"Mars hosts both Olympus Mons, a shield volcano about 22 km high, and the Valles Marineris canyon system; the Great Red Spot is a storm on Jupiter, and the Caloris Basin is one of the largest impact craters on Mercury.","difficulty":"hard","source":"SSC CGL Tier 2","questionHi":"विशेषता का मिलान उसके विवरण से कीजिए। A. ओलंपस मॉन्स  B. महान लाल धब्बा  C. वैलेस मैरिनेरिस  D. कैलोरिस बेसिन; 1. मंगल पर विशाल घाटी तंत्र  2. बृहस्पति पर विशाल, दीर्घजीवी प्रतिचक्रवाती तूफ़ान  3. सौरमंडल का ज्ञात सबसे बड़ा ज्वालामुखी, मंगल पर  4. बुध पर एक बड़ा आघात बेसिन","optionsHi":["A-1, B-2, C-3, D-4","A-3, B-4, C-1, D-2","A-3, B-2, C-4, D-1","A-3, B-2, C-1, D-4"],"explanationHi":"मंगल पर ओलंपस मॉन्स, लगभग 22 किमी ऊँचा एक ढाल ज्वालामुखी, और वैलेस मैरिनेरिस घाटी तंत्र दोनों हैं; महान लाल धब्बा बृहस्पति पर एक तूफ़ान है, और कैलोरिस बेसिन बुध के सबसे बड़े आघात क्रेटरों में से एक है।"},
  {"id":"geo-solar-system-144","question":"Halley's Comet has an orbital period of 76 years and comes within 0.59 AU of the Sun at perihelion. Its greatest distance from the Sun, at aphelion, is about:","options":["35 AU","30 AU","76 AU","18 AU"],"answer":0,"explanation":"By Kepler's third law the semi-major axis is 76^(2/3) = about 17.9 AU. Perihelion plus aphelion equals twice this, so aphelion = 35.9 - 0.59 = about 35 AU. The 18 AU figure is only the semi-major axis, the usual trap.","difficulty":"very-hard","questionHi":"हैली धूमकेतु की कक्षीय अवधि 76 वर्ष है और वह उपसौर पर सूर्य से 0.59 AU के भीतर आता है। अपसौर पर सूर्य से उसकी अधिकतम दूरी लगभग है:","optionsHi":["35 AU","30 AU","76 AU","18 AU"],"explanationHi":"केप्लर के तीसरे नियम से अर्ध-दीर्घ अक्ष 76^(2/3) = लगभग 17.9 AU है। उपसौर और अपसौर का योग इसका दोगुना होता है, इसलिए अपसौर = 35.9 - 0.59 = लगभग 35 AU। 18 AU केवल अर्ध-दीर्घ अक्ष है, जो सामान्य भ्रम है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-145","question":"The Earth moves around the Sun at about 30 km/s. A planet moving in a circular orbit 4 AU from the Sun would move at about:","options":["120 km/s","15 km/s","7.5 km/s","30 km/s"],"answer":1,"explanation":"Circular orbital speed varies as 1/sqrt(r). At 4 AU it is 30/sqrt(4) = 15 km/s. Using 1/r gives 7.5 km/s, which is the common slip.","difficulty":"hard","questionHi":"पृथ्वी सूर्य के चारों ओर लगभग 30 km/s की गति से घूमती है। सूर्य से 4 AU दूर वृत्ताकार कक्षा में घूमने वाले ग्रह की गति लगभग होगी:","optionsHi":["120 km/s","15 km/s","7.5 km/s","30 km/s"],"explanationHi":"वृत्ताकार कक्षीय चाल 1/वर्गमूल(r) के अनुसार बदलती है। 4 AU पर यह 30/वर्गमूल(4) = 15 km/s है। 1/r लेने पर 7.5 km/s आता है, जो आम भूल है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-146","question":"Jupiter has about 318 times the mass and 11.2 times the radius of the Earth. Compared with the Earth, the gravity at the top of its clouds is about:","options":["28 times","0.4 times","2.5 times","11 times"],"answer":2,"explanation":"Surface gravity varies as mass divided by radius squared: 318 / (11.2)^2 = 318/125 = about 2.5. Dividing by the radius alone gives 28, and 0.4 inverts the ratio.","difficulty":"hard","questionHi":"बृहस्पति का द्रव्यमान पृथ्वी का लगभग 318 गुना और उसकी त्रिज्या 11.2 गुना है। पृथ्वी की तुलना में उसके बादलों के शीर्ष पर गुरुत्व लगभग है:","optionsHi":["28 गुना","0.4 गुना","2.5 गुना","11 गुना"],"explanationHi":"सतही गुरुत्व द्रव्यमान को त्रिज्या के वर्ग से भाग देने पर आता है: 318 / (11.2)^2 = 318/125 = लगभग 2.5। केवल त्रिज्या से भाग देने पर 28 आता है और 0.4 अनुपात को उलट देता है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-147","question":"Mars has 0.107 times the mass and 0.532 times the radius of the Earth. If the escape speed from the Earth is 11.2 km/s, the escape speed from Mars is about:","options":["7.9 km/s","11.2 km/s","2.3 km/s","5.0 km/s"],"answer":3,"explanation":"Escape speed varies as sqrt(M/R): 11.2 x sqrt(0.107/0.532) = 11.2 x 0.448 = about 5.0 km/s. The 2.3 km/s figure drops the square root.","difficulty":"very-hard","questionHi":"मंगल का द्रव्यमान पृथ्वी का 0.107 गुना और त्रिज्या 0.532 गुना है। यदि पृथ्वी से पलायन वेग 11.2 km/s है, तो मंगल से पलायन वेग लगभग है:","optionsHi":["7.9 km/s","11.2 km/s","2.3 km/s","5.0 km/s"],"explanationHi":"पलायन वेग वर्गमूल(M/R) के अनुसार बदलता है: 11.2 x वर्गमूल(0.107/0.532) = 11.2 x 0.448 = लगभग 5.0 km/s। 2.3 km/s का आँकड़ा वर्गमूल छोड़ने से आता है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-148","question":"The Earth takes 365.26 days and Mars 687 days to go round the Sun. The interval between two successive oppositions of Mars is about:","options":["780 days","1,052 days","322 days","687 days"],"answer":0,"explanation":"The synodic period S satisfies 1/S = 1/365.26 - 1/687, which gives about 780 days (roughly 26 months). The 322 days option is the simple difference of the periods, and 1,052 their sum.","difficulty":"very-hard","questionHi":"पृथ्वी को सूर्य की परिक्रमा में 365.26 दिन और मंगल को 687 दिन लगते हैं। मंगल के दो क्रमिक विरोधों के बीच का अंतराल लगभग है:","optionsHi":["780 दिन","1,052 दिन","322 दिन","687 दिन"],"explanationHi":"संयुति अवधि S के लिए 1/S = 1/365.26 - 1/687 होता है, जिससे लगभग 780 दिन (लगभग 26 महीने) आते हैं। 322 दिन अवधियों का सीधा अंतर है और 1,052 उनका योग।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-149","question":"A laser pulse is sent from the Earth to a reflector left on the Moon and returns. Taking the Moon's distance as 384,400 km and the speed of light as 3.0 x 10^5 km/s, the round trip takes about:","options":["1.28 s","2.56 s","5.1 s","25.6 s"],"answer":1,"explanation":"Round-trip distance = 2 x 384,400 = 768,800 km, and 768,800 / 300,000 = about 2.56 s. The 1.28 s figure is the one-way time.","difficulty":"moderate","questionHi":"पृथ्वी से चंद्रमा पर छोड़े गए परावर्तक तक एक लेज़र स्पंद भेजा जाता है और वह लौटता है। चंद्रमा की दूरी 384,400 km और प्रकाश की चाल 3.0 x 10^5 km/s मानने पर, आने-जाने में लगभग कितना समय लगता है?","optionsHi":["1.28 s","2.56 s","5.1 s","25.6 s"],"explanationHi":"आने-जाने की दूरी = 2 x 384,400 = 768,800 km, और 768,800 / 300,000 = लगभग 2.56 s। 1.28 s केवल एक ओर का समय है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-150","question":"The Moon has a diameter of about 3,475 km and is about 384,400 km away. Its angular diameter in the sky is about:","options":["1.04°","5.2°","0.52°","0.26°"],"answer":2,"explanation":"Angular size = diameter/distance = 3,475/384,400 = 0.00904 radian, which times 57.3 degrees is about 0.52°. This nearly equals the Sun's 0.53°, which is why total solar eclipses occur.","difficulty":"moderate","questionHi":"चंद्रमा का व्यास लगभग 3,475 km है और वह लगभग 384,400 km दूर है। आकाश में उसका कोणीय व्यास लगभग है:","optionsHi":["1.04°","5.2°","0.52°","0.26°"],"explanationHi":"कोणीय आकार = व्यास/दूरी = 3,475/384,400 = 0.00904 रेडियन, जिसे 57.3 अंश से गुणा करने पर लगभग 0.52° आता है। यह सूर्य के 0.53° के लगभग बराबर है, इसीलिए पूर्ण सूर्यग्रहण होते हैं।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-151","question":"The Sun is about 27 million times as massive as the Moon and about 389 times farther away. Taking the tide-raising force as proportional to mass divided by the cube of distance, the Sun's tidal effect on the Earth compared with the Moon's is about:","options":["0.003 times","178 times","2.2 times","0.46 times"],"answer":3,"explanation":"Tidal force varies as M/d^3, so the ratio = 27 x 10^6 / (389)^3 = about 0.46. The Sun's direct pull (M/d^2) is about 178 times the Moon's, but tides come from the difference in pull across the Earth.","difficulty":"very-hard","questionHi":"सूर्य का द्रव्यमान चंद्रमा से लगभग 2.7 करोड़ गुना और उसकी दूरी लगभग 389 गुना है। ज्वार-उत्पादक बल को द्रव्यमान और दूरी के घन के अनुपात में मानने पर, पृथ्वी पर सूर्य का ज्वारीय प्रभाव चंद्रमा की तुलना में लगभग है:","optionsHi":["0.003 गुना","178 गुना","2.2 गुना","0.46 गुना"],"explanationHi":"ज्वारीय बल M/d^3 के अनुसार बदलता है, इसलिए अनुपात = 27 x 10^6 / (389)^3 = लगभग 0.46। सूर्य का प्रत्यक्ष आकर्षण (M/d^2) चंद्रमा से लगभग 178 गुना है, पर ज्वार पृथ्वी के आर-पार आकर्षण के अंतर से बनते हैं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-152","question":"A planet has 8 times the Earth's mass and twice its radius. Compared with the Earth, its surface gravity and mean density are respectively:","options":["2 times and the same","4 times and 2 times","The same and 2 times","2 times and 4 times"],"answer":0,"explanation":"Gravity varies as M/R^2 = 8/4 = 2, and density as M/R^3 = 8/8 = 1, so the planet has twice the gravity but the same density as Earth.","difficulty":"hard","questionHi":"किसी ग्रह का द्रव्यमान पृथ्वी का 8 गुना और त्रिज्या दोगुनी है। पृथ्वी की तुलना में उसका सतही गुरुत्व और माध्य घनत्व क्रमशः हैं:","optionsHi":["2 गुना और समान","4 गुना और 2 गुना","समान और 2 गुना","2 गुना और 4 गुना"],"explanationHi":"गुरुत्व M/R^2 = 8/4 = 2 के अनुसार और घनत्व M/R^3 = 8/8 = 1 के अनुसार बदलता है, इसलिए ग्रह का गुरुत्व दोगुना है पर घनत्व पृथ्वी के बराबर है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-153","question":"Mercury turns once on its axis in 58.65 days and goes round the Sun in 88 days. The interval from one sunrise to the next on Mercury is about:","options":["147 days","176 days","88 days","59 days"],"answer":1,"explanation":"The solar day satisfies 1/S = 1/58.65 - 1/88, giving about 176 days, exactly twice Mercury's year because of its 3:2 spin-orbit resonance. The 147 days option simply adds 59 and 88.","difficulty":"very-hard","questionHi":"बुध अपनी धुरी पर 58.65 दिन में एक चक्कर लगाता है और सूर्य की परिक्रमा 88 दिन में करता है। बुध पर एक सूर्योदय से अगले सूर्योदय तक का अंतराल लगभग है:","optionsHi":["147 दिन","176 दिन","88 दिन","59 दिन"],"explanationHi":"सौर दिन के लिए 1/S = 1/58.65 - 1/88 होता है, जिससे लगभग 176 दिन आते हैं, जो 3:2 घूर्णन-कक्षा अनुनाद के कारण बुध के वर्ष का ठीक दोगुना है। 147 दिन केवल 59 और 88 का योग है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-154","question":"Venus turns once on its axis in 243 days, but backwards (retrograde), and goes round the Sun in 224.7 days. The interval from one sunrise to the next on Venus is about:","options":["225 days","243 days","117 days","2,980 days"],"answer":2,"explanation":"Because the spin is retrograde, the two rates add: 1/S = 1/243 + 1/224.7, giving S = about 117 days. Treating the spin as prograde would subtract and give about 2,980 days, which is the trap.","difficulty":"very-hard","questionHi":"शुक्र अपनी धुरी पर 243 दिन में एक चक्कर लगाता है, पर विपरीत दिशा में (पश्चगामी), और सूर्य की परिक्रमा 224.7 दिन में करता है। शुक्र पर एक सूर्योदय से अगले सूर्योदय तक का अंतराल लगभग है:","optionsHi":["225 दिन","243 दिन","117 दिन","2,980 दिन"],"explanationHi":"घूर्णन पश्चगामी होने के कारण दोनों दरें जुड़ती हैं: 1/S = 1/243 + 1/224.7, जिससे S = लगभग 117 दिन। घूर्णन को अग्रगामी मानने पर घटाना पड़ता और लगभग 2,980 दिन आते, जो भ्रम है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-155","question":"The Moon rises at 8:00 pm on a certain day. Its rising time on the next day will be about:","options":["8:00 pm","7:10 pm","9:50 pm","8:50 pm"],"answer":3,"explanation":"The Moon moves about 13 degrees east among the stars each day, so the Earth must turn an extra 50 minutes or so to bring it up again. The lunar day is therefore about 24 h 50 min, and the Moon rises later each day.","difficulty":"hard","questionHi":"किसी दिन चंद्रमा रात 8:00 बजे उगता है। अगले दिन उसके उगने का समय लगभग होगा:","optionsHi":["रात 8:00 बजे","शाम 7:10 बजे","रात 9:50 बजे","रात 8:50 बजे"],"explanationHi":"चंद्रमा प्रतिदिन तारों के बीच लगभग 13 अंश पूर्व की ओर खिसकता है, इसलिए उसे फिर से उदय कराने के लिए पृथ्वी को लगभग 50 मिनट अधिक घूमना पड़ता है। इसलिए चंद्र दिन लगभग 24 घंटे 50 मिनट का होता है और चंद्रमा प्रतिदिन देर से उगता है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-156","question":"The Sun radiates about 3.8 x 10^26 watts. Using E = mc^2 with c = 3 x 10^8 m/s, the mass it converts to energy every second is about:","options":["4.3 x 10^9 kg","4.3 x 10^6 kg","1.3 x 10^18 kg","4.3 x 10^12 kg"],"answer":0,"explanation":"Mass per second = 3.8 x 10^26 / (3 x 10^8)^2 = 3.8 x 10^26 / 9 x 10^16 = about 4.3 x 10^9 kg, over four million tonnes a second. Forgetting to square c gives 1.3 x 10^18 kg.","difficulty":"very-hard","questionHi":"सूर्य लगभग 3.8 x 10^26 वाट विकिरित करता है। c = 3 x 10^8 m/s लेकर E = mc^2 के प्रयोग से वह प्रति सेकंड जितना द्रव्यमान ऊर्जा में बदलता है वह लगभग है:","optionsHi":["4.3 x 10^9 kg","4.3 x 10^6 kg","1.3 x 10^18 kg","4.3 x 10^12 kg"],"explanationHi":"प्रति सेकंड द्रव्यमान = 3.8 x 10^26 / (3 x 10^8)^2 = 3.8 x 10^26 / 9 x 10^16 = लगभग 4.3 x 10^9 kg, यानी प्रति सेकंड चालीस लाख टन से अधिक। c का वर्ग करना भूलने पर 1.3 x 10^18 kg आता है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-157","question":"Compared with the sunlight received per square metre at the Earth's distance, a body 4 AU from the Sun receives:","options":["1/2 as much","1/16 as much","1/4 as much","1/8 as much"],"answer":1,"explanation":"Sunlight intensity falls as the inverse square of distance, so at 4 AU it is 1/4^2 = 1/16 of the Earth's, about 6%. A 1/4 answer forgets the square.","difficulty":"moderate","questionHi":"पृथ्वी की दूरी पर प्रति वर्ग मीटर प्राप्त सूर्य के प्रकाश की तुलना में, सूर्य से 4 AU दूर स्थित पिंड को मिलता है:","optionsHi":["1/2 गुना","1/16 गुना","1/4 गुना","1/8 गुना"],"explanationHi":"सूर्य के प्रकाश की तीव्रता दूरी के वर्ग के व्युत्क्रम से घटती है, इसलिए 4 AU पर वह पृथ्वी की 1/4^2 = 1/16, यानी लगभग 6%, होती है। 1/4 का उत्तर वर्ग करना भूल जाता है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-158","question":"Without any atmosphere, the Earth's mean surface temperature would be about 255 K (-18 °C), whereas the actual mean is about 288 K (15 °C). The natural greenhouse effect therefore warms the surface by about:","options":["18 °C","66 °C","33 °C","15 °C"],"answer":2,"explanation":"The difference is 288 - 255 = 33 K, which is also 33 °C of warming. The 18 and 15 figures are merely the two Celsius temperatures themselves.","difficulty":"hard","questionHi":"वायुमंडल के बिना पृथ्वी का माध्य सतही तापमान लगभग 255 K (-18 °C) होता, जबकि वास्तविक माध्य लगभग 288 K (15 °C) है। इसलिए प्राकृतिक हरितगृह प्रभाव सतह को लगभग कितना गर्म करता है?","optionsHi":["18 °C","66 °C","33 °C","15 °C"],"explanationHi":"अंतर 288 - 255 = 33 K है, जो 33 °C की वृद्धि भी है। 18 और 15 केवल दोनों सेल्सियस तापमान स्वयं हैं।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-159","question":"The Moon is at perigee, 363,300 km away, in one month and at apogee, 405,500 km away, in another. Its apparent diameter at perigee is larger than at apogee by about:","options":["1.2%","24%","6%","12%"],"answer":3,"explanation":"Apparent size varies inversely with distance: 405,500/363,300 = 1.116, so the Moon looks about 12% wider at perigee. A full Moon at perigee is called a supermoon.","difficulty":"hard","questionHi":"चंद्रमा एक महीने में उपभू पर, 363,300 km दूर, और दूसरे महीने में अपभू पर, 405,500 km दूर, होता है। उपभू पर उसका आभासी व्यास अपभू की तुलना में लगभग कितना अधिक है?","optionsHi":["1.2%","24%","6%","12%"],"explanationHi":"आभासी आकार दूरी के व्युत्क्रमानुपाती होता है: 405,500/363,300 = 1.116, इसलिए चंद्रमा उपभू पर लगभग 12% चौड़ा दिखता है। उपभू पर पूर्णिमा का चाँद सुपरमून कहलाता है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-160","question":"On 22 December, when the Sun is overhead at 23.44° S, the altitude of the Sun at local noon at a place at 30° N is about:","options":["36.5°","66.5°","53.5°","23.5°"],"answer":0,"explanation":"Noon altitude = 90° - (latitude + declination distance) = 90 - (30 + 23.44) = 36.56°. The 53.5° option is the Sun's zenith distance, not its altitude.","difficulty":"hard","questionHi":"22 दिसंबर को, जब सूर्य 23.44° दक्षिण पर सिर के ऊपर होता है, 30° उत्तर पर स्थित स्थान पर स्थानीय दोपहर में सूर्य की ऊँचाई लगभग होगी:","optionsHi":["36.5°","66.5°","53.5°","23.5°"],"explanationHi":"दोपहर की ऊँचाई = 90° - (अक्षांश + सूर्य की दिक्पात दूरी) = 90 - (30 + 23.44) = 36.56°। 53.5° वाला विकल्प सूर्य की शिरोबिंदु दूरी है, ऊँचाई नहीं।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-161","question":"Taking the Earth's equatorial circumference as 40,075 km, a point at 60° N, carried round by the Earth's rotation, moves at about:","options":["1,670 km/h","835 km/h","1,445 km/h","418 km/h"],"answer":1,"explanation":"The equator moves at 40,075/24 = about 1,670 km/h. Speed scales with the cosine of latitude, and cos 60° = 0.5, giving 835 km/h. Using cos 30° gives the 1,445 km/h trap.","difficulty":"hard","questionHi":"पृथ्वी की विषुवतीय परिधि 40,075 km मानने पर, पृथ्वी के घूर्णन से घूमता 60° उत्तर का एक बिंदु लगभग किस चाल से चलता है?","optionsHi":["1,670 km/h","835 km/h","1,445 km/h","418 km/h"],"explanationHi":"विषुवत रेखा 40,075/24 = लगभग 1,670 km/h से चलती है। चाल अक्षांश की कोज्या के अनुसार घटती है, और cos 60° = 0.5 से 835 km/h मिलता है। cos 30° लेने पर 1,445 km/h का भ्रम आता है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-162","question":"The speed needed to escape from the Earth's surface is 11.2 km/s. The speed of a satellite in a circular orbit grazing the surface is about:","options":["15.8 km/s","11.2 km/s","7.9 km/s","5.6 km/s"],"answer":2,"explanation":"Escape speed is sqrt(2) times the circular orbital speed at the same radius, so the orbital speed is 11.2/1.414 = about 7.9 km/s. Halving 11.2 gives the 5.6 km/s trap.","difficulty":"hard","questionHi":"पृथ्वी की सतह से पलायन के लिए आवश्यक चाल 11.2 km/s है। सतह को छूती वृत्ताकार कक्षा में उपग्रह की चाल लगभग है:","optionsHi":["15.8 km/s","11.2 km/s","7.9 km/s","5.6 km/s"],"explanationHi":"उसी त्रिज्या पर पलायन चाल वृत्ताकार कक्षीय चाल की वर्गमूल(2) गुना होती है, इसलिए कक्षीय चाल 11.2/1.414 = लगभग 7.9 km/s है। 11.2 को आधा करने पर 5.6 km/s का भ्रम आता है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-163","question":"Twelve lunar months of 29.53 days fall short of the solar year of 365.24 days. To keep a lunisolar calendar in step with the seasons, an extra month (as in the Hindu adhik maas) has to be added roughly every:","options":["1.4 years","4 years","19 years","2.7 years"],"answer":3,"explanation":"The yearly shortfall is 365.24 - 12 x 29.53 = about 10.9 days, so a whole month of 29.5 days accumulates in 29.5/10.9 = about 2.7 years. The 19-year figure is the Metonic cycle, which has seven such months.","difficulty":"very-hard","questionHi":"29.53 दिन के बारह चंद्र मास 365.24 दिन के सौर वर्ष से कम पड़ते हैं। चांद्र-सौर पंचांग को ऋतुओं के साथ बनाए रखने के लिए (जैसे हिंदू अधिक मास में) एक अतिरिक्त मास लगभग कितने समय में जोड़ना पड़ता है?","optionsHi":["1.4 वर्ष","4 वर्ष","19 वर्ष","2.7 वर्ष"],"explanationHi":"वार्षिक कमी 365.24 - 12 x 29.53 = लगभग 10.9 दिन है, इसलिए 29.5 दिन का पूरा मास 29.5/10.9 = लगभग 2.7 वर्ष में जमा होता है। 19 वर्ष का आँकड़ा मेटोनिक चक्र है, जिसमें सात ऐसे मास होते हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-solar-system-164","question":"Eclipse seasons recur about every 173 days, roughly twice a year, mainly because:","options":["The Sun returns to a node of the Moon's tilted orbit about every 173 days","The Moon reaches its full phase near the same point of its orbit every 173 days","The Earth's axis swings between its extreme tilts about every 173 days in each cycle","The Earth passes close to perihelion twice a year, once on each side of the Sun"],"answer":0,"explanation":"Eclipses need the Moon near a node, where its orbit crosses the ecliptic. Because the nodes slowly regress, the Sun passes a node every 173.3 days, giving two eclipse seasons a year, about 346.6 days apart in a full cycle.","difficulty":"very-hard","questionHi":"ग्रहण ऋतुएँ लगभग प्रत्येक 173 दिन में, यानी वर्ष में लगभग दो बार, आती हैं, मुख्यतः क्योंकि:","optionsHi":["सूर्य लगभग प्रत्येक 173 दिन में चंद्रमा की झुकी कक्षा के एक पात पर लौटता है","चंद्रमा लगभग प्रत्येक 173 दिन में पूर्ण कला में पहुँचता है","पृथ्वी की धुरी का झुकाव लगभग प्रत्येक 173 दिन में बदलता है","पृथ्वी वर्ष में दो बार उपसौर से गुज़रती है"],"explanationHi":"ग्रहण के लिए चंद्रमा का पात के निकट होना चाहिए, जहाँ उसकी कक्षा क्रांतिवृत्त को काटती है। पात धीरे-धीरे पीछे खिसकते हैं, इसलिए सूर्य प्रत्येक 173.3 दिन में एक पात से गुज़रता है, जिससे वर्ष में दो ग्रहण ऋतुएँ आती हैं, जिनका पूरा चक्र लगभग 346.6 दिन का है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-165","question":"The saros, the interval after which a very similar eclipse repeats, is about:","options":["27.3 days, the sidereal month","18 years and about 11 days","11 years, the sunspot cycle","19 years, the Metonic lunar cycle"],"answer":1,"explanation":"A saros is 223 synodic months, about 6,585.3 days or 18 years 11 days, in which the Sun, Moon and nodes return to nearly the same arrangement. The extra one-third of a day shifts each eclipse about 120 degrees west in longitude.","difficulty":"hard","questionHi":"सारोस, वह अंतराल जिसके बाद लगभग वैसा ही ग्रहण दोहराता है, लगभग है:","optionsHi":["27.3 दिन, नक्षत्र मास","18 वर्ष और लगभग 11 दिन","11 वर्ष, सौर कलंक चक्र","19 वर्ष, मेटोनिक चंद्र चक्र"],"explanationHi":"एक सारोस 223 संयुति मास, लगभग 6,585.3 दिन या 18 वर्ष 11 दिन का होता है, जिसमें सूर्य, चंद्रमा और पात लगभग उसी व्यवस्था में लौट आते हैं। अतिरिक्त एक-तिहाई दिन हर ग्रहण को देशांतर में लगभग 120 अंश पश्चिम खिसका देता है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-166","question":"The Earth is at aphelion in early July. As a result, the northern hemisphere's summer half of the year is:","options":["Exactly as long as its winter half, since the tilt alone fixes the seasons","Shorter than its winter half, because the Earth moves fastest near aphelion","Longer than its winter half, because the Earth moves slowest near aphelion","Hotter than the southern summer by about 20 °C, because it is nearer the Sun"],"answer":2,"explanation":"By Kepler's second law the Earth moves slowest near aphelion in July, so the half-year from the March equinox to the September equinox is about 186 days against 179 for the northern winter half. The slightly greater July distance does not outweigh the effect of tilt.","difficulty":"very-hard","questionHi":"पृथ्वी जुलाई के आरंभ में अपसौर पर होती है। इसके परिणामस्वरूप उत्तरी गोलार्ध के वर्ष का ग्रीष्म अर्ध भाग:","optionsHi":["शीत अर्ध भाग के ठीक बराबर होता है, क्योंकि केवल झुकाव ऋतुएँ तय करता है","शीत अर्ध भाग से छोटा होता है, क्योंकि पृथ्वी अपसौर के निकट सबसे तेज़ चलती है","शीत अर्ध भाग से लंबा होता है, क्योंकि पृथ्वी अपसौर के निकट सबसे धीमी चलती है","दक्षिणी ग्रीष्म से लगभग 20 °C अधिक गर्म होता है, क्योंकि वह सूर्य के अधिक निकट है"],"explanationHi":"केप्लर के दूसरे नियम से पृथ्वी जुलाई में अपसौर के निकट सबसे धीमी चलती है, इसलिए मार्च विषुव से सितंबर विषुव तक का अर्ध वर्ष लगभग 186 दिन का है जबकि उत्तरी शीत अर्ध भाग 179 दिन का। जुलाई की थोड़ी अधिक दूरी झुकाव के प्रभाव पर भारी नहीं पड़ती।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-167","question":"Match each Milankovitch cycle with its approximate length. A. Change in the Earth's axial tilt (22.1° to 24.5°)  B. Precession of the Earth's axis  C. Change in the shape (eccentricity) of the orbit. 1. About 100,000 years  2. About 41,000 years  3. About 26,000 years","options":["A-3, B-2, C-1","A-2, B-1, C-3","A-1, B-3, C-2","A-2, B-3, C-1"],"answer":3,"explanation":"The tilt varies over about 41,000 years, the wobble of the axis (precession) takes about 26,000 years, and the orbit's eccentricity changes over about 100,000 years. Together these pace the glacial cycles of the Pleistocene.","difficulty":"very-hard","questionHi":"प्रत्येक मिलनकोविच चक्र का उसकी लगभग अवधि से मिलान कीजिए। A. पृथ्वी के अक्षीय झुकाव में परिवर्तन (22.1° से 24.5°)  B. पृथ्वी की धुरी का पुरस्सरण  C. कक्षा के आकार (उत्केन्द्रता) में परिवर्तन। 1. लगभग 100,000 वर्ष  2. लगभग 41,000 वर्ष  3. लगभग 26,000 वर्ष","optionsHi":["A-3, B-2, C-1","A-2, B-1, C-3","A-1, B-3, C-2","A-2, B-3, C-1"],"explanationHi":"झुकाव लगभग 41,000 वर्ष में बदलता है, धुरी का डगमगाना (पुरस्सरण) लगभग 26,000 वर्ष लेता है, और कक्षा की उत्केन्द्रता लगभग 100,000 वर्ष में बदलती है। मिलकर ये प्लीस्टोसीन के हिमयुग चक्रों की गति तय करते हैं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-168","question":"An outer planet such as Mars appears to move backwards (retrograde) among the stars for a few weeks around the time of its:","options":["Opposition","Greatest elongation","Eastern quadrature","Conjunction with the Sun"],"answer":0,"explanation":"Near opposition the faster-moving Earth overtakes the outer planet, so the planet seems to slide backwards against the stars for a time. The motion is only apparent, a matter of viewpoint.","difficulty":"hard","questionHi":"मंगल जैसा बाह्य ग्रह अपने किस समय के आसपास कुछ सप्ताह तक तारों के बीच पीछे की ओर (वक्री) जाता प्रतीत होता है?","optionsHi":["विरोध","अधिकतम दीर्घकोणीय दूरी","पूर्वी चतुर्थांश","सूर्य के साथ युति"],"explanationHi":"विरोध के निकट तेज़ चलने वाली पृथ्वी बाह्य ग्रह से आगे निकल जाती है, इसलिए ग्रह कुछ समय के लिए तारों के सापेक्ष पीछे खिसकता लगता है। यह गति केवल आभासी है, दृष्टिकोण का परिणाम।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-169","question":"Mercury is seen only low in the twilight sky because its greatest angular distance (elongation) from the Sun is only about:","options":["15°","28°","47°","90°"],"answer":1,"explanation":"Mercury's orbit is so small that it never gets more than about 28 degrees from the Sun, so it sets or rises within a couple of hours of the Sun. The 47 degrees figure is Venus's greatest elongation.","difficulty":"hard","questionHi":"बुध केवल गोधूलि के आकाश में नीचे दिखता है क्योंकि सूर्य से उसकी अधिकतम कोणीय दूरी (दीर्घकोणीय दूरी) केवल लगभग है:","optionsHi":["15°","28°","47°","90°"],"explanationHi":"बुध की कक्षा इतनी छोटी है कि वह सूर्य से लगभग 28 अंश से अधिक दूर नहीं जाता, इसलिए वह सूर्य के दो घंटे के भीतर अस्त या उदय होता है। 47 अंश शुक्र की अधिकतम दीर्घकोणीय दूरी है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-170","question":"Which dwarf planet rotates once in about four hours, which has stretched it into an egg-like shape?","options":["Makemake","Ceres","Haumea","Eris"],"answer":2,"explanation":"Haumea spins in about 3.9 hours, one of the fastest rotations of any large body, which makes it a stretched ellipsoid. Ceres turns in about 9 hours and is nearly round.","difficulty":"very-hard","questionHi":"कौन-सा बौना ग्रह लगभग चार घंटे में एक बार घूमता है, जिससे वह अंडे जैसे आकार में खिंच गया है?","optionsHi":["माकेमाके","सेरेस","हाउमिया","एरिस"],"explanationHi":"हाउमिया लगभग 3.9 घंटे में घूमता है, जो किसी बड़े पिंड की सबसे तेज़ गतियों में से एक है, जिससे वह खिंचा हुआ दीर्घवृत्तज बन गया है। सेरेस लगभग 9 घंटे में घूमता है और लगभग गोल है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-171","question":"Which of the known dwarf planets is the most massive?","options":["Makemake","Haumea","Pluto","Eris"],"answer":3,"explanation":"Eris is about 27% more massive than Pluto, though Pluto is slightly larger in diameter. The discovery of Eris in 2005 was a major reason the IAU defined 'planet' in 2006.","difficulty":"hard","questionHi":"ज्ञात बौने ग्रहों में सबसे अधिक द्रव्यमान किसका है?","optionsHi":["माकेमाके","हाउमिया","प्लूटो","एरिस"],"explanationHi":"एरिस प्लूटो से लगभग 27% अधिक द्रव्यमान वाला है, यद्यपि प्लूटो व्यास में थोड़ा बड़ा है। 2005 में एरिस की खोज IAU द्वारा 2006 में 'ग्रह' की परिभाषा तय करने का एक प्रमुख कारण थी।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-172","question":"The only moon in the Solar System known to generate its own magnetic field is:","options":["Ganymede","Europa, the icy moon of Jupiter","Titan, the largest moon of Saturn","Triton, the largest moon of Neptune"],"answer":0,"explanation":"Ganymede, Jupiter's largest moon, has a molten iron core that drives its own magnetic field, detected by the Galileo spacecraft. Titan, Europa and Triton have no intrinsic field of their own.","difficulty":"hard","questionHi":"सौरमंडल का एकमात्र चंद्रमा जिसके बारे में ज्ञात है कि वह अपना चुंबकीय क्षेत्र उत्पन्न करता है, कौन-सा है?","optionsHi":["गैनिमीड","यूरोपा, बृहस्पति का हिमाच्छादित चंद्रमा","टाइटन, शनि का सबसे बड़ा चंद्रमा","ट्राइटन, नेपच्यून का सबसे बड़ा चंद्रमा"],"explanationHi":"बृहस्पति के सबसे बड़े चंद्रमा गैनिमीड में पिघला लोहे का कोर है जो उसका अपना चुंबकीय क्षेत्र चलाता है, जिसका पता गैलीलियो यान ने लगाया। टाइटन, यूरोपा और ट्राइटन का अपना कोई आंतरिक क्षेत्र नहीं है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-173","question":"The Huygens probe, carried to Saturn by the Cassini spacecraft, landed in January 2005 on:","options":["Enceladus","Titan","Rhea","Mimas"],"answer":1,"explanation":"Huygens parachuted through the thick nitrogen atmosphere of Titan on 14 January 2005, the first landing on a body in the outer Solar System. Enceladus is known for its water plumes and was only observed by Cassini.","difficulty":"hard","questionHi":"हाइगेंस यान, जिसे कैसिनी यान शनि तक लाया, जनवरी 2005 में किस पर उतरा?","optionsHi":["एन्सेलाडस","टाइटन","रिया","माइमास"],"explanationHi":"हाइगेंस 14 जनवरी 2005 को टाइटन के घने नाइट्रोजन वायुमंडल से पैराशूट द्वारा उतरा, जो बाह्य सौरमंडल के किसी पिंड पर पहला अवतरण था। एन्सेलाडस अपने जल फुहारों के लिए जाना जाता है और कैसिनी ने केवल उसका प्रेक्षण किया।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-174","question":"Which is the only spacecraft to have visited both Uranus and Neptune?","options":["Pioneer 10","New Horizons","Voyager 2","Voyager 1"],"answer":2,"explanation":"Voyager 2 flew past Uranus in January 1986 and Neptune in August 1989, after Jupiter and Saturn. Voyager 1 visited only Jupiter and Saturn, and New Horizons went to Pluto.","difficulty":"hard","questionHi":"वह एकमात्र अंतरिक्ष यान कौन-सा है जिसने यूरेनस और नेपच्यून दोनों की यात्रा की है?","optionsHi":["पायनियर 10","न्यू होराइज़ंस","वॉयजर 2","वॉयजर 1"],"explanationHi":"वॉयजर 2 बृहस्पति और शनि के बाद जनवरी 1986 में यूरेनस के और अगस्त 1989 में नेपच्यून के पास से गुज़रा। वॉयजर 1 केवल बृहस्पति और शनि गया और न्यू होराइज़ंस प्लूटो गया।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-175","question":"Which spacecraft became the first to enter orbit around Mercury, in 2011?","options":["Magellan","Mariner 10","BepiColombo","MESSENGER"],"answer":3,"explanation":"NASA's MESSENGER went into orbit around Mercury in March 2011 and mapped the whole planet. Mariner 10 made only flybys in 1974-75, and Magellan studied Venus.","difficulty":"hard","questionHi":"कौन-सा अंतरिक्ष यान 2011 में बुध की कक्षा में प्रवेश करने वाला पहला यान बना?","optionsHi":["मैगेलन","मेरिनर 10","बेपीकोलंबो","मैसेंजर"],"explanationHi":"नासा का मैसेंजर मार्च 2011 में बुध की कक्षा में गया और उसने पूरे ग्रह का मानचित्रण किया। मेरिनर 10 ने 1974-75 में केवल निकट-उड़ानें भरीं और मैगेलन ने शुक्र का अध्ययन किया।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-176","question":"Which NASA instrument aboard India's Chandrayaan-1 found absorption signatures of hydroxyl and water on the lunar surface in 2009?","options":["Moon Mineralogy Mapper (M3)","Terrain Mapping Camera (TMC)","Moon Impact Probe (MIP)","Hyper Spectral Imager (HySI)"],"answer":0,"explanation":"The Moon Mineralogy Mapper, a NASA imaging spectrometer carried on Chandrayaan-1, found infrared absorption bands of hydroxyl and water, widespread though thin, especially at high latitudes. ISRO's cameras mapped terrain and minerals but are not credited with this finding.","difficulty":"very-hard","questionHi":"भारत के चंद्रयान-1 पर लगे नासा के किस उपकरण ने 2009 में चंद्र सतह पर हाइड्रॉक्सिल और जल के अवशोषण संकेत पाए?","optionsHi":["मून मिनरलॉजी मैपर (M3)","भू-आकृति मानचित्रण कैमरा","मून इम्पैक्ट प्रोब","हाइपर स्पेक्ट्रल इमेजर"],"explanationHi":"मून मिनरलॉजी मैपर, चंद्रयान-1 पर लगा नासा का इमेजिंग स्पेक्ट्रोमीटर, ने हाइड्रॉक्सिल और जल के अवरक्त अवशोषण बैंड पाए, जो व्यापक पर पतले हैं, विशेषकर उच्च अक्षांशों पर। ISRO के कैमरों ने भू-आकृति और खनिजों का मानचित्रण किया, पर इस खोज का श्रेय उन्हें नहीं दिया जाता।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-solar-system-177","question":"With the Chandrayaan-3 landing in August 2023, India became which country to make a soft landing on the Moon?","options":["Fifth, after the USA, the Soviet Union, China and Japan","Fourth, after the Soviet Union, the USA and China","Second, after the USA, with the Soviet Union not counted","Third, after the Soviet Union and the United States"],"answer":1,"explanation":"The Soviet Union (1966), the United States (1966), and China (2013) had soft-landed earlier, and India's Vikram lander touched down on 23 August 2023 near the south polar region, making it the fourth. Japan's SLIM landed later, in January 2024.","difficulty":"hard","questionHi":"अगस्त 2023 में चंद्रयान-3 के अवतरण के साथ भारत चंद्रमा पर सॉफ्ट लैंडिंग करने वाला कौन-सा देश बना?","optionsHi":["पाँचवाँ, अमेरिका, सोवियत संघ, चीन और जापान के बाद","चौथा, सोवियत संघ, अमेरिका और चीन के बाद","दूसरा, अमेरिका के बाद, सोवियत संघ को छोड़कर","तीसरा, सोवियत संघ और संयुक्त राज्य अमेरिका के बाद"],"explanationHi":"सोवियत संघ (1966), अमेरिका (1966) और चीन (2013) पहले सॉफ्ट लैंडिंग कर चुके थे, और भारत का विक्रम लैंडर 23 अगस्त 2023 को दक्षिणी ध्रुवीय क्षेत्र के निकट उतरा, जिससे वह चौथा बना। जापान का SLIM बाद में, जनवरी 2024 में, उतरा।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-178","question":"Sunspot numbers peak about every 11 years. The complete cycle of the Sun's magnetic field, including the reversal of polarity, takes about:","options":["44 years","11 years","22 years","5.5 years"],"answer":2,"explanation":"The Sun's global magnetic polarity flips at each sunspot maximum, so two 11-year sunspot cycles make one 22-year magnetic or Hale cycle.","difficulty":"hard","questionHi":"सौर कलंकों की संख्या लगभग प्रत्येक 11 वर्ष में चरम पर पहुँचती है। ध्रुवता के उलटने सहित सूर्य के चुंबकीय क्षेत्र का पूरा चक्र लगभग कितना समय लेता है?","optionsHi":["44 वर्ष","11 वर्ष","22 वर्ष","5.5 वर्ष"],"explanationHi":"प्रत्येक सौर कलंक अधिकतम पर सूर्य की वैश्विक चुंबकीय ध्रुवता पलट जाती है, इसलिए दो 11 वर्षीय सौर कलंक चक्र मिलकर एक 22 वर्षीय चुंबकीय या हेल चक्र बनाते हैं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-179","question":"After a large solar flare and a coronal mass ejection from the same region, which reaches the Earth first?","options":["The plasma cloud, within a few minutes, well before the flare's light and X-rays reach the Earth at all","Both arrive together after about 8 minutes, since the plasma also moves at the speed of light","The plasma cloud in about 8 minutes and then the flare's light only after one to three days","The flare's light and X-rays in about 8 minutes, well before the plasma cloud, which takes one to three days"],"answer":3,"explanation":"Flare radiation travels at the speed of light and takes about 8 minutes, causing radio blackouts. The coronal mass ejection is a cloud of plasma moving at hundreds to a few thousand km/s, so it arrives in one to three days and triggers geomagnetic storms and aurorae.","difficulty":"hard","questionHi":"एक ही क्षेत्र से बड़ी सौर ज्वाला और कोरोनल मास इजेक्शन के बाद, कौन पृथ्वी पर पहले पहुँचता है?","optionsHi":["प्लाज़्मा बादल, कुछ मिनटों में, ज्वाला के प्रकाश और X-किरणों से बहुत पहले","दोनों साथ-साथ लगभग 8 मिनट बाद पहुँचते हैं","प्लाज़्मा बादल लगभग 8 मिनट में और ज्वाला का प्रकाश एक से तीन दिन में","ज्वाला का प्रकाश और X-किरणें, लगभग 8 मिनट में, प्लाज़्मा बादल के एक से तीन दिन में पहुँचने से बहुत पहले"],"explanationHi":"ज्वाला का विकिरण प्रकाश की चाल से चलता है और लगभग 8 मिनट लेता है, जिससे रेडियो ब्लैकआउट होते हैं। कोरोनल मास इजेक्शन प्लाज़्मा का बादल है जो सैकड़ों से कुछ हज़ार km/s की चाल से चलता है, इसलिए एक से तीन दिन में पहुँचता है और भू-चुंबकीय तूफान तथा ध्रुवीय ज्योति उत्पन्न करता है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-180","question":"Which two planets have atmospheres made up mostly of carbon dioxide?","options":["Venus and Mars","Venus and Mercury","Mars and Neptune","Earth and Mars"],"answer":0,"explanation":"Venus's atmosphere is about 96% carbon dioxide and Mars's about 95%. Earth's is mostly nitrogen, Mercury has only a trace exosphere, and Neptune's atmosphere is hydrogen, helium and methane.","difficulty":"moderate","questionHi":"किन दो ग्रहों के वायुमंडल में मुख्यतः कार्बन डाइऑक्साइड है?","optionsHi":["शुक्र और मंगल","शुक्र और बुध","मंगल और नेपच्यून","पृथ्वी और मंगल"],"explanationHi":"शुक्र के वायुमंडल में लगभग 96% और मंगल के वायुमंडल में लगभग 95% कार्बन डाइऑक्साइड है। पृथ्वी का वायुमंडल मुख्यतः नाइट्रोजन है, बुध में केवल अल्प बहिर्मंडल है, और नेपच्यून का वायुमंडल हाइड्रोजन, हीलियम तथा मीथेन का है।","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-solar-system-181","question":"Phobos orbits Mars in about 7.7 hours, which is less than the Martian day of about 24.6 hours. As seen from the surface of Mars, Phobos therefore:","options":["Rises in the east and sets in the west, but crosses the sky about twice a Martian day","Rises in the west and sets in the east, crossing the sky about twice a Martian day","Rises in the east and sets in the west, once a Martian day, just as the Sun does when seen from the surface","Never rises above the horizon of most places because its orbit is inclined to the equator"],"answer":1,"explanation":"Phobos circles Mars faster than Mars rotates, so it overtakes the surface and appears to move east across the sky, rising in the west and setting in the east about every 11 hours. Deimos, orbiting more slowly than the rotation, rises in the east.","difficulty":"very-hard","questionHi":"फोबोस मंगल की परिक्रमा लगभग 7.7 घंटे में करता है, जो मंगल के लगभग 24.6 घंटे के दिन से कम है। इसलिए मंगल की सतह से फोबोस:","optionsHi":["पूर्व में उगता और पश्चिम में अस्त होता है, पर मंगल के दिन में लगभग दो बार","पश्चिम में उगता और पूर्व में अस्त होता है, और मंगल के एक दिन में लगभग दो बार आकाश पार करता है","पूर्व में उगता और पश्चिम में अस्त होता है, मंगल के दिन में एक बार, सूर्य की तरह","कभी क्षितिज के ऊपर नहीं उगता क्योंकि उसकी कक्षा ध्रुवीय है"],"explanationHi":"फोबोस मंगल के घूर्णन से तेज़ परिक्रमा करता है, इसलिए वह सतह से आगे निकल जाता है और आकाश में पूर्व की ओर चलता दिखता है, लगभग प्रत्येक 11 घंटे में पश्चिम में उगता और पूर्व में अस्त होता है। डीमोस, जो घूर्णन से धीमा परिक्रमा करता है, पूर्व में उगता है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-182","question":"The most widely accepted explanation for the origin of the Moon is that:","options":["The Moon was a wandering body that was captured whole and intact by the Earth's gravity as it passed by","A large piece of the fast-spinning molten young Earth was flung off by rotation and became the Moon","A Mars-sized body struck the young Earth, and debris from the collision gathered into the Moon","The Moon formed beside the Earth, at the same time, from the same cloud of gas and dust around the Sun"],"answer":2,"explanation":"In the giant impact hypothesis, a Mars-sized body (called Theia) hit the early Earth about 4.5 billion years ago, and the ejected material coalesced into the Moon. It explains the Moon's small iron core and its rocks' near-identical isotopes to Earth's mantle.","difficulty":"hard","questionHi":"चंद्रमा की उत्पत्ति की सर्वाधिक स्वीकृत व्याख्या यह है कि:","optionsHi":["चंद्रमा एक भटकता पिंड था जिसे पृथ्वी के गुरुत्व ने ज्यों का त्यों पकड़ लिया","तेज़ घूमती नवजात पृथ्वी का एक टुकड़ा छिटककर चंद्रमा बन गया","मंगल के आकार के एक पिंड ने नवजात पृथ्वी को टक्कर मारी, और टक्कर के मलबे से चंद्रमा बना","चंद्रमा पृथ्वी के बगल में उसी गैस और धूल के बादल से बना"],"explanationHi":"महाटक्कर परिकल्पना में मंगल के आकार का पिंड (थेया) लगभग 4.5 अरब वर्ष पहले आरंभिक पृथ्वी से टकराया और उछला पदार्थ मिलकर चंद्रमा बना। यह चंद्रमा के छोटे लौह कोर और उसकी चट्टानों के पृथ्वी के मैंटल से लगभग समान समस्थानिकों को समझाती है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-183","question":"The far side of the Moon is wrongly called the 'dark side' because:","options":["It is lit only at the moment of a total lunar eclipse, when the Earth's shadow falls on it","It reflects almost no light, because its rocks are much darker than those of the near side","It lies permanently in the shadow of the Moon itself and receives no direct sunlight at any time","It gets as much sunlight over a lunar day as the near side, and is only hidden from Earth"],"answer":3,"explanation":"The Moon's rotation is locked to its orbit, so one face always points to Earth, but both faces go through day and night during the 29.5-day cycle. At new moon, the far side is fully sunlit.","difficulty":"moderate","questionHi":"चंद्रमा के दूरस्थ पक्ष को गलती से 'अँधेरा पक्ष' कहा जाता है क्योंकि:","optionsHi":["वह केवल पूर्ण चंद्रग्रहण के समय प्रकाशित होता है","वह कोई प्रकाश परावर्तित नहीं करता क्योंकि उसकी चट्टानें काली हैं","वह स्थायी रूप से पृथ्वी की छाया में है और उसे सूर्य प्रकाश नहीं मिलता","उसे एक चंद्र दिन में निकट पक्ष जितना ही सूर्य प्रकाश मिलता है और वह केवल पृथ्वी से छिपा रहता है"],"explanationHi":"चंद्रमा का घूर्णन उसकी कक्षा से बँधा है, इसलिए एक ही पक्ष पृथ्वी की ओर रहता है, पर 29.5 दिन के चक्र में दोनों पक्षों में दिन और रात होते हैं। अमावस्या पर दूरस्थ पक्ष पूरी तरह प्रकाशित होता है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-184","question":"Because of libration, a slight rocking of the Moon, observers on the Earth can over time see about what share of the Moon's surface?","options":["59%","41%","50%","75%"],"answer":0,"explanation":"The Moon's elliptical orbit and the tilt of its axis make it nod and sway, letting us glimpse a little beyond the edges, so about 59% of the surface is visible over time. No more than 41% is hidden permanently.","difficulty":"very-hard","questionHi":"चंद्रमा के हल्के डगमगाने, यानी उसकी दोलन-गति (लिब्रेशन), के कारण पृथ्वी के प्रेक्षक समय के साथ चंद्रमा की सतह का लगभग कितना भाग देख सकते हैं?","optionsHi":["59%","41%","50%","75%"],"explanationHi":"चंद्रमा की दीर्घवृत्ताकार कक्षा और उसकी धुरी का झुकाव उसे हिलाते-डुलाते हैं, जिससे हम किनारों के थोड़ा पार भी झाँक लेते हैं, इसलिए समय के साथ लगभग 59% सतह दिखती है। केवल 41% से अधिक स्थायी रूप से छिपा नहीं रहता।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-185","question":"The 'equation of time', by which the Sun runs up to about 16 minutes ahead of or behind a clock in the course of a year, arises mainly from:","options":["The precession of the Earth's axis alone, acting over a period of 26,000 years","The tilt of the Earth's axis together with the ellipticity of its orbit","The Moon's pull on the Earth's rotation alone, which slows the day by milliseconds","The change of the Earth's distance from the Moon during its monthly orbit"],"answer":1,"explanation":"The apparent Sun's pace against mean time varies because the Earth's axis is tilted (the Sun's path is not along the equator) and because its orbit is elliptical (it moves faster near perihelion). Together they give the figure-8 analemma.","difficulty":"very-hard","questionHi":"'समय समीकरण', जिसके कारण सूर्य वर्ष भर में घड़ी से लगभग 16 मिनट तक आगे या पीछे चलता है, मुख्यतः किससे उत्पन्न होता है?","optionsHi":["अकेले पृथ्वी की धुरी के पुरस्सरण से","पृथ्वी की धुरी के झुकाव और उसकी कक्षा की दीर्घवृत्तीयता से","अकेले पृथ्वी के घूर्णन पर चंद्रमा के खिंचाव से","पृथ्वी की चंद्रमा से दूरी में परिवर्तन से"],"explanationHi":"आभासी सूर्य की माध्य समय से तुलना में चाल इसलिए बदलती है क्योंकि पृथ्वी की धुरी झुकी है (सूर्य का पथ विषुवत रेखा के अनुदिश नहीं है) और उसकी कक्षा दीर्घवृत्ताकार है (उपसौर के पास वह तेज़ चलती है)। दोनों मिलकर 8 के आकार का एनालेमा बनाते हैं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-186","question":"The tropical year, measured from equinox to equinox, is about 20 minutes shorter than the sidereal year mainly because of:","options":["The nutation of the Earth's axis with a period of 18.6 years","The elliptical shape of the Earth's orbit","The precession of the Earth's axis, which shifts the equinoxes westwards","The slowing of the Earth's rotation by tidal friction, lengthening the day"],"answer":2,"explanation":"The equinox point slides slowly westward along the ecliptic, about 50 arcseconds a year, so the Sun returns to it slightly before it returns to the same star. The tropical year (365.2422 days) is thus shorter than the sidereal year (365.2564 days).","difficulty":"very-hard","questionHi":"विषुव से विषुव तक मापा गया उष्णकटिबंधीय वर्ष नाक्षत्र वर्ष से लगभग 20 मिनट छोटा होता है, मुख्यतः किसके कारण?","optionsHi":["18.6 वर्ष की अवधि वाले पृथ्वी की धुरी के अक्षदोलन (न्यूटेशन) के कारण","पृथ्वी की कक्षा के दीर्घवृत्ताकार आकार के कारण","पृथ्वी की धुरी के पुरस्सरण के कारण, जो विषुवों को पश्चिम की ओर खिसकाता है","ज्वारीय घर्षण से पृथ्वी के घूर्णन के धीमे होने के कारण"],"explanationHi":"विषुव बिंदु क्रांतिवृत्त के अनुदिश धीरे-धीरे पश्चिम की ओर खिसकता है, लगभग 50 चाप-सेकंड प्रति वर्ष, इसलिए सूर्य उस तक उसी तारे पर लौटने से थोड़ा पहले लौट आता है। इस प्रकार उष्णकटिबंधीय वर्ष (365.2422 दिन) नाक्षत्र वर्ष (365.2564 दिन) से छोटा है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-187","question":"Remote-sensing satellites of the IRS series are usually placed in near-polar, sun-synchronous orbits at about 800 km mainly so that they:","options":["Orbit once every 24 hours to match the Earth's rotation and hover over one longitude","Stay fixed above one point on the equator to watch that place continuously for days","Remain permanently above the Earth's day side, where the surface is always sunlit and photographed","Cross every place at the same local solar time on each visit, giving comparable lighting"],"answer":3,"explanation":"A sun-synchronous orbit precesses about one degree a day eastward, matching the Earth's motion round the Sun, so the satellite crosses each latitude at the same local time. This keeps shadows and lighting consistent for comparing images over time. A geostationary satellite is the one that stays above one point.","difficulty":"hard","questionHi":"IRS श्रृंखला के सुदूर संवेदन उपग्रह प्रायः लगभग 800 km पर निकट-ध्रुवीय, सूर्य-तुल्यकालिक कक्षाओं में रखे जाते हैं, मुख्यतः ताकि वे:","optionsHi":["पृथ्वी के घूर्णन से मेल खाने के लिए हर 24 घंटे में एक बार परिक्रमा करें","विषुवत रेखा के एक बिंदु के ऊपर स्थिर रहकर उसे लगातार देखें","पृथ्वी के दिन वाले पक्ष के ऊपर स्थायी रूप से रहें जहाँ सदा धूप रहती है","हर बार किसी स्थान के ऊपर उसी स्थानीय सौर समय पर गुज़रें, जिससे तुलनीय प्रकाश मिले"],"explanationHi":"सूर्य-तुल्यकालिक कक्षा प्रतिदिन लगभग एक अंश पूर्व की ओर पुरस्सरण करती है, जो पृथ्वी की सूर्य के चारों ओर गति से मेल खाता है, इसलिए उपग्रह प्रत्येक अक्षांश को एक ही स्थानीय समय पर पार करता है। इससे समय के साथ चित्रों की तुलना के लिए छाया और प्रकाश सुसंगत रहते हैं। एक बिंदु के ऊपर स्थिर रहने वाला उपग्रह भूस्थिर होता है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-solar-system-188","question":"Our Sun, with too little mass to explode as a supernova, is expected to end its life as:","options":["A white dwarf, after shedding its outer layers as a planetary nebula","A neutron star left behind by a supernova explosion","A pulsar spinning many times a second with a strong magnetic field","A black hole formed by the direct collapse of its core"],"answer":0,"explanation":"After the hydrogen in its core is spent in some 5 billion years, the Sun will swell into a red giant, shed its outer layers as a planetary nebula, and leave a hot white dwarf. Only stars of more than about 8 solar masses end in supernovae.","difficulty":"hard","questionHi":"हमारा सूर्य, जिसका द्रव्यमान सुपरनोवा के रूप में फटने के लिए बहुत कम है, अपने जीवन का अंत किस रूप में करेगा, ऐसी आशा है?","optionsHi":["श्वेत वामन, अपनी बाहरी परतों को ग्रहीय नीहारिका के रूप में छोड़ने के बाद","सुपरनोवा विस्फोट से बचा न्यूट्रॉन तारा","प्रबल चुंबकीय क्षेत्र वाला पल्सर जो प्रति सेकंड कई बार घूमता है","अपने कोर के सीधे ढहने से बना कृष्ण विवर"],"explanationHi":"लगभग 5 अरब वर्ष में कोर का हाइड्रोजन समाप्त होने पर सूर्य फूलकर लाल दानव बनेगा, अपनी बाहरी परतें ग्रहीय नीहारिका के रूप में छोड़ेगा और पीछे गर्म श्वेत वामन छोड़ेगा। केवल लगभग 8 सौर द्रव्यमान से अधिक के तारे सुपरनोवा में समाप्त होते हैं।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-189","question":"The planets orbit the Sun in nearly the same plane and in the same direction, which the nebular theory explains by saying that the cloud they formed from:","options":["Was held in orbit by the pull of the Milky Way's galactic centre","Was spinning and flattened into a disc as it contracted, keeping its angular momentum","Was cold and still, so matter fell straight inwards from all directions","Was struck by a passing star that pulled out a thread of matter in one plane"],"answer":1,"explanation":"A collapsing, rotating cloud flattens into a disc because spin resists collapse across the rotation axis, and conservation of angular momentum makes everything circulate the same way. The planets formed in this disc, which is why their orbits are coplanar and prograde.","difficulty":"hard","questionHi":"ग्रह सूर्य की परिक्रमा लगभग एक ही तल में और एक ही दिशा में करते हैं, जिसे नीहारिका सिद्धांत यह कहकर समझाता है कि जिस बादल से वे बने वह:","optionsHi":["आकाशगंगा के केंद्र के खिंचाव से कक्षा में बँधा था","घूम रहा था और संकुचन के साथ चपटी तश्तरी बन गया, अपना कोणीय संवेग बनाए रखते हुए","ठंडा और स्थिर था, इसलिए पदार्थ सभी दिशाओं से सीधे भीतर गिरा","पास से गुज़रते तारे से टकराया जिसने एक तल में पदार्थ की धारा खींच ली"],"explanationHi":"ढहता, घूमता बादल तश्तरी में चपटा हो जाता है क्योंकि घूर्णन अक्ष के आर-पार ढहने का प्रतिरोध करता है, और कोणीय संवेग संरक्षण सबको एक ही दिशा में घुमाता है। ग्रह इसी तश्तरी में बने, इसीलिए उनकी कक्षाएँ समतलीय और अग्रगामी हैं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-190","question":"Match the annual meteor shower with the parent body. A. Perseids  B. Leonids  C. Geminids  D. Orionids. 1. Comet Halley  2. Comet Swift-Tuttle  3. Asteroid 3200 Phaethon  4. Comet Tempel-Tuttle","options":["A-2, B-4, C-1, D-3","A-4, B-2, C-3, D-1","A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1"],"answer":2,"explanation":"The Perseids of August come from Comet Swift-Tuttle, the Leonids of November from Tempel-Tuttle, the Geminids of December from the asteroid 3200 Phaethon, and the Orionids of October from Halley's Comet.","difficulty":"very-hard","questionHi":"वार्षिक उल्का वर्षा का उसके जनक पिंड से मिलान कीजिए। A. पर्सिड  B. लियोनिड  C. जेमिनिड  D. ओरायनिड। 1. हैली धूमकेतु  2. स्विफ्ट-टटल धूमकेतु  3. क्षुद्रग्रह 3200 फेथॉन  4. टेम्पल-टटल धूमकेतु","optionsHi":["A-2, B-4, C-1, D-3","A-4, B-2, C-3, D-1","A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1"],"explanationHi":"अगस्त की पर्सिड स्विफ्ट-टटल धूमकेतु से, नवंबर की लियोनिड टेम्पल-टटल से, दिसंबर की जेमिनिड क्षुद्रग्रह 3200 फेथॉन से और अक्टूबर की ओरायनिड हैली धूमकेतु से आती हैं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-191","question":"The Tunguska event of 30 June 1908 in Siberia, which flattened about 2,000 square km of forest, is thought to have been:","options":["A crater-forming impact of a large iron meteorite on the Siberian plateau, leaving a deep bowl-shaped crater lake","A giant explosion of methane gas suddenly released from the frozen ground of the Siberian permafrost region","The fall of a fragment of Halley's Comet, which left a large crater lake behind in the taiga forest","An airburst of a small stony asteroid or comet fragment, high above the ground, with no large crater"],"answer":3,"explanation":"Trees were flattened radially over about 2,000 sq km, but no major crater was found, which points to an explosion some 5-10 km up from a stony body about 50-60 m across. The Chelyabinsk meteor of 2013 was a smaller, similar airburst.","difficulty":"hard","questionHi":"साइबेरिया में 30 जून 1908 की तुंगुस्का घटना, जिसने लगभग 2,000 वर्ग km वन को समतल कर दिया, माना जाता है कि थी:","optionsHi":["साइबेरियाई पठार पर बड़े लौह उल्कापिंड की गड्ढा बनाने वाली टक्कर","जमी भूमि से निकली मीथेन का विशाल विस्फोट","हैली धूमकेतु के एक खंड का गिरना, जिसने गड्ढे वाली झील छोड़ी","किसी छोटे पथरीले क्षुद्रग्रह या धूमकेतु खंड का भूमि से ऊँचाई पर वायु-विस्फोट, जिसने कोई बड़ा गड्ढा नहीं छोड़ा"],"explanationHi":"लगभग 2,000 वर्ग km में पेड़ त्रिज्यीय रूप से गिरे, पर कोई बड़ा गड्ढा नहीं मिला, जो लगभग 50-60 m चौड़े पथरीले पिंड के भूमि से लगभग 5-10 km ऊपर विस्फोट की ओर संकेत करता है। 2013 का चेल्याबिंस्क उल्कापिंड छोटा, समान वायु-विस्फोट था।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-solar-system-192","question":"Halley's Comet was last at perihelion in February 1986. Its next perihelion is predicted for:","options":["2061","2063","2056","2062"],"answer":0,"explanation":"Halley's period varies between about 74 and 79 years because of the planets' pull, and it averages 76 years. The next return is predicted for 28 July 2061, a little before 1986 plus 76.","difficulty":"hard","questionHi":"हैली धूमकेतु फरवरी 1986 में अंतिम बार उपसौर पर था। उसका अगला उपसौर किस वर्ष होने का पूर्वानुमान है?","optionsHi":["2061","2063","2056","2062"],"explanationHi":"ग्रहों के खिंचाव के कारण हैली की अवधि लगभग 74 से 79 वर्ष के बीच बदलती है और औसतन 76 वर्ष है। अगली वापसी 28 जुलाई 2061 के लिए पूर्वानुमानित है, जो 1986 में 76 जोड़ने से थोड़ा पहले है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-193","question":"A comet's tail always points:","options":["Towards whichever planet it happens to be nearest to at that moment of its orbit","Away from the Sun, so on the outward leg of its orbit the tail leads the head","Along the comet's path of motion, always trailing behind the head like a vapour trail","Towards the Sun, because the Sun's gravity pulls the light gas and dust of the tail forward"],"answer":1,"explanation":"The tail is blown outward by the solar wind and the pressure of sunlight, so it points away from the Sun whatever the comet's direction of travel. When the comet is moving away from the Sun, the tail runs ahead of it.","difficulty":"hard","questionHi":"धूमकेतु की पूँछ सदा किस ओर होती है?","optionsHi":["जिस ग्रह के सबसे निकट हो उसकी ओर","सूर्य से दूर, इसलिए कक्षा के बाहर जाने वाले चरण में पूँछ सिर के आगे रहती है","धूमकेतु के पथ के अनुदिश, सदा सिर के पीछे घिसटती हुई","सूर्य की ओर, सूर्य के गुरुत्व से खिंची हुई"],"explanationHi":"पूँछ सौर पवन और सूर्य के प्रकाश के दाब से बाहर की ओर उड़ाई जाती है, इसलिए धूमकेतु की गति की दिशा चाहे जो हो वह सूर्य से दूर रहती है। जब धूमकेतु सूर्य से दूर जा रहा होता है, तो पूँछ उसके आगे चलती है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-194","question":"Which type of asteroid is by far the most common, making up roughly three-quarters of all known asteroids?","options":["S-type, stony and rich in silicates","V-type, basaltic like Vesta","C-type, dark and rich in carbon","M-type, metallic and rich in iron and nickel"],"answer":2,"explanation":"C-type (carbonaceous) asteroids are dark and primitive, and dominate the outer part of the main belt. S-types are next in number, and M-types are scarce.","difficulty":"hard","questionHi":"किस प्रकार के क्षुद्रग्रह सबसे अधिक संख्या में हैं, जो ज्ञात क्षुद्रग्रहों का लगभग तीन-चौथाई हैं?","optionsHi":["S-प्रकार, पथरीले और सिलिकेट-समृद्ध","V-प्रकार, वेस्टा जैसे बेसाल्टी","C-प्रकार, गहरे और कार्बन-समृद्ध","M-प्रकार, धात्विक और लोहा-निकल-समृद्ध"],"explanationHi":"C-प्रकार (कार्बनमय) क्षुद्रग्रह गहरे और आदिम होते हैं और मुख्य पट्टी के बाहरी भाग में प्रमुख हैं। संख्या में S-प्रकार अगले हैं और M-प्रकार दुर्लभ हैं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-195","question":"The Trojan asteroids of Jupiter are found at:","options":["The gap between the orbits of Mars and Jupiter, in the main asteroid belt where Ceres also lies","The L3 point, on the far side of the Sun from Jupiter, opposite the planet's position in its orbit","The L1 and L2 points, on the line joining Jupiter and the Sun, on either side of the planet","The L4 and L5 Lagrange points, 60 degrees ahead of and behind the planet in its orbit"],"answer":3,"explanation":"Jupiter's Trojans gather around the stable L4 and L5 points of the Sun-Jupiter system, each forming a triangle with the Sun and the planet. The main belt lies between Mars and Jupiter.","difficulty":"hard","questionHi":"बृहस्पति के ट्रोजन क्षुद्रग्रह कहाँ पाए जाते हैं?","optionsHi":["मंगल और बृहस्पति की कक्षाओं के बीच के अंतराल में","L3 बिंदु पर, बृहस्पति से सूर्य के दूसरी ओर","L1 और L2 बिंदुओं पर, बृहस्पति और सूर्य को जोड़ने वाली रेखा पर","L4 और L5 लैग्रांज बिंदुओं पर, ग्रह से उसकी कक्षा में 60 अंश आगे और पीछे"],"explanationHi":"बृहस्पति के ट्रोजन सूर्य–बृहस्पति तंत्र के स्थिर L4 और L5 बिंदुओं के आसपास एकत्र हैं, जिनमें प्रत्येक सूर्य और ग्रह के साथ त्रिभुज बनाता है। मुख्य पट्टी मंगल और बृहस्पति के बीच है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-196","question":"Which planet has the coldest recorded atmospheric temperature, about 49 K (-224 °C), although it is nearer the Sun than Neptune?","options":["Uranus","Saturn","Neptune","Jupiter"],"answer":0,"explanation":"Uranus's atmosphere has been measured as cold as about 49 K, colder than Neptune's, because Uranus gives out almost no internal heat while Neptune radiates well over twice the heat it receives from the Sun.","difficulty":"very-hard","questionHi":"किस ग्रह के वायुमंडल का दर्ज किया गया सबसे कम तापमान लगभग 49 K (-224 °C) है, यद्यपि वह नेपच्यून से सूर्य के अधिक निकट है?","optionsHi":["यूरेनस","शनि","नेपच्यून","बृहस्पति"],"explanationHi":"यूरेनस के वायुमंडल का तापमान लगभग 49 K तक ठंडा मापा गया है, जो नेपच्यून से अधिक ठंडा है, क्योंकि यूरेनस लगभग कोई आंतरिक ऊष्मा नहीं छोड़ता जबकि नेपच्यून सूर्य से मिलने वाली ऊष्मा से दोगुने से भी अधिक विकिरित करता है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-197","question":"Which planet is the most flattened at its poles, with a polar diameter about 10% less than its equatorial diameter?","options":["Jupiter","Saturn","Earth","Mars"],"answer":1,"explanation":"Saturn is the most oblate planet, its low density and rapid rotation (about 10.7 hours) bulging it at the equator. Jupiter is next at about 6%, while Earth is only 0.3% flattened.","difficulty":"hard","questionHi":"कौन-सा ग्रह अपने ध्रुवों पर सबसे अधिक चपटा है, जिसका ध्रुवीय व्यास उसके विषुवतीय व्यास से लगभग 10% कम है?","optionsHi":["बृहस्पति","शनि","पृथ्वी","मंगल"],"explanationHi":"शनि सबसे अधिक चपटा ग्रह है, जिसका कम घनत्व और तेज़ घूर्णन (लगभग 10.7 घंटे) उसे विषुवत रेखा पर उभार देते हैं। बृहस्पति लगभग 6% पर अगला है, जबकि पृथ्वी केवल 0.3% चपटी है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-198","question":"Proxima Centauri, the nearest star to the Sun, is 4.24 light-years away. Taking one light-year as 9.46 x 10^12 km, its distance is about:","options":["4.0 x 10^14 km","9.5 x 10^12 km","4.0 x 10^13 km","4.0 x 10^12 km"],"answer":2,"explanation":"Distance = 4.24 x 9.46 x 10^12 = about 4.0 x 10^13 km. The 9.5 x 10^12 km figure is one light-year alone.","difficulty":"moderate","questionHi":"सूर्य का निकटतम तारा प्रॉक्सिमा सेंटॉरी 4.24 प्रकाश-वर्ष दूर है। एक प्रकाश-वर्ष को 9.46 x 10^12 km मानने पर उसकी दूरी लगभग है:","optionsHi":["4.0 x 10^14 km","9.5 x 10^12 km","4.0 x 10^13 km","4.0 x 10^12 km"],"explanationHi":"दूरी = 4.24 x 9.46 x 10^12 = लगभग 4.0 x 10^13 km। 9.5 x 10^12 km केवल एक प्रकाश-वर्ष है।","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-solar-system-199","question":"The Sun takes about how long to complete one revolution around the centre of the Milky Way, a period called a galactic or cosmic year?","options":["About 2.3 million years","About 23 million years","About 2.3 billion years","About 230 million years"],"answer":3,"explanation":"At roughly 230 km/s and about 26,000 light-years from the centre, the Sun circles the galaxy in about 225-250 million years. It has made some 20 circuits in its lifetime.","difficulty":"hard","questionHi":"सूर्य को आकाशगंगा के केंद्र की एक परिक्रमा पूरी करने में, जिस अवधि को गांगेय या ब्रह्मांडीय वर्ष कहते हैं, लगभग कितना समय लगता है?","optionsHi":["लगभग 23 लाख वर्ष","लगभग 2.3 करोड़ वर्ष","लगभग 2.3 अरब वर्ष","लगभग 23 करोड़ वर्ष"],"explanationHi":"लगभग 230 km/s की चाल से और केंद्र से लगभग 26,000 प्रकाश-वर्ष की दूरी पर, सूर्य लगभग 22.5-25 करोड़ वर्ष में आकाशगंगा का एक चक्कर पूरा करता है। अपने जीवनकाल में उसने लगभग 20 चक्कर लगाए हैं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-200","question":"At Kanyakumari, at about 8° N, the Pole Star (Polaris) appears above the northern horizon at an altitude of about:","options":["8°","82°","90°","23.5°"],"answer":0,"explanation":"The altitude of the Pole Star equals the observer's latitude, so it is about 8° at Kanyakumari. The 82° figure is the colatitude, and 90° applies only at the North Pole.","difficulty":"moderate","questionHi":"लगभग 8° उत्तर पर स्थित कन्याकुमारी में ध्रुव तारा (पोलारिस) उत्तरी क्षितिज के ऊपर लगभग किस ऊँचाई पर दिखता है?","optionsHi":["8°","82°","90°","23.5°"],"explanationHi":"ध्रुव तारे की ऊँचाई प्रेक्षक के अक्षांश के बराबर होती है, इसलिए कन्याकुमारी में वह लगभग 8° है। 82° का आँकड़ा सहअक्षांश है और 90° केवल उत्तरी ध्रुव पर होता है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-201","question":"At a place at 28° N, which of these stars never sets, that is, is circumpolar?","options":["A star of declination -70°","A star of declination +70°","A star of declination +40°","A star of declination +50°"],"answer":1,"explanation":"A star is circumpolar if its declination exceeds 90° minus the latitude, here 90 - 28 = 62°. Only the +70° star qualifies, whereas the -70° star never even rises at 28° N.","difficulty":"hard","questionHi":"28° उत्तर के स्थान पर इनमें से कौन-सा तारा कभी अस्त नहीं होता, यानी ध्रुव-परिक्रमी है?","optionsHi":["-70° दिक्पात वाला तारा","+70° दिक्पात वाला तारा","+40° दिक्पात वाला तारा","+50° दिक्पात वाला तारा"],"explanationHi":"कोई तारा ध्रुव-परिक्रमी तब होता है जब उसका दिक्पात 90° में से अक्षांश घटाने पर आई सीमा, यहाँ 90 - 28 = 62°, से अधिक हो। केवल +70° वाला तारा योग्य है, जबकि -70° वाला तारा 28° उत्तर पर उगता भी नहीं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-202","question":"Which star is the second-brightest in the night sky, after Sirius, and is known in Indian tradition as Agastya?","options":["Alpha Centauri","Arcturus","Canopus","Vega"],"answer":2,"explanation":"Canopus, in the constellation Carina, is the second-brightest star as seen from the Earth after Sirius, and is named Agastya in Indian tradition. Alpha Centauri and Arcturus follow, and Vega is the fifth.","difficulty":"hard","questionHi":"कौन-सा तारा सिरियस के बाद रात्रि आकाश का दूसरा सबसे चमकीला तारा है और भारतीय परंपरा में अगस्त्य के नाम से जाना जाता है?","optionsHi":["अल्फा सेंटॉरी","आर्कटुरस","कैनोपस","वेगा"],"explanationHi":"कैरिना तारामंडल का कैनोपस पृथ्वी से सिरियस के बाद दूसरा सबसे चमकीला तारा है और भारतीय परंपरा में अगस्त्य कहलाता है। अल्फा सेंटॉरी और आर्कटुरस उसके बाद हैं, और वेगा पाँचवाँ है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-solar-system-203","question":"Star A has an apparent magnitude of 1 and star B an apparent magnitude of 6. Given that five magnitudes correspond to a factor of 100 in brightness, star A appears:","options":["5 times brighter than B","25 times brighter than B","100 times fainter than B","100 times brighter than B"],"answer":3,"explanation":"The scale is inverted and logarithmic: a lower magnitude means a brighter star, and a difference of 5 magnitudes means 100 times in brightness. A, with the smaller number, is therefore 100 times brighter.","difficulty":"hard","questionHi":"तारा A का आभासी परिमाण 1 और तारा B का आभासी परिमाण 6 है। यह देखते हुए कि पाँच परिमाण चमक में 100 गुना के संगत हैं, तारा A दिखता है:","optionsHi":["B से 5 गुना अधिक चमकीला","B से 25 गुना अधिक चमकीला","B से 100 गुना अधिक धुंधला","B से 100 गुना अधिक चमकीला"],"explanationHi":"यह पैमाना उलटा और लघुगणकीय है: कम परिमाण का अर्थ अधिक चमकीला तारा है, और 5 परिमाण का अंतर चमक में 100 गुना होता है। इसलिए छोटी संख्या वाला A, 100 गुना अधिक चमकीला है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-204","question":"The month of Chaitra in the Hindu lunar calendar is so named because the full moon of the month falls near the nakshatra:","options":["Chitra","Rohini","Magha","Ashwini"],"answer":0,"explanation":"The lunar months are named after the nakshatra in which the full moon falls, so Chaitra comes from Chitra (the star Spica). Ashwini gives the month Ashvin and Magha the month Magha, while no month is named after Rohini.","difficulty":"hard","questionHi":"हिंदू चांद्र पंचांग के चैत्र मास का यह नाम इसलिए है क्योंकि इस मास की पूर्णिमा किस नक्षत्र के निकट पड़ती है?","optionsHi":["चित्रा","रोहिणी","मघा","अश्विनी"],"explanationHi":"चांद्र मासों के नाम उस नक्षत्र पर हैं जिसमें पूर्णिमा पड़ती है, इसलिए चैत्र चित्रा (तारा स्पाइका) से बना है। अश्विनी से आश्विन मास और मघा से माघ मास बने हैं, जबकि किसी मास का नाम रोहिणी पर नहीं है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-solar-system-205","question":"Makar Sankranti falls on about 14-15 January, although the winter solstice is on 21-22 December. This gap exists mainly because of:","options":["The elliptical shape of the Earth's orbit, which stretches the winter season","The precession of the equinoxes, which has shifted the sidereal zodiac against the seasons","The Earth's axis tilt, which changes the date of the solstice by about a day or two every year","The Moon's orbit, which steadily moves the lunar months against the position of the Sun year after year"],"answer":1,"explanation":"Makar Sankranti marks the Sun's entry into sidereal Capricorn, measured against the stars. Precession slides the equinoxes and solstices west by about one degree every 72 years, so the solstice, which coincided with Makara about 1,500 years ago, now comes about three weeks earlier.","difficulty":"very-hard","questionHi":"मकर संक्रांति लगभग 14-15 जनवरी को पड़ती है, यद्यपि शीत अयनांत 21-22 दिसंबर को होता है। यह अंतर मुख्यतः किस कारण है?","optionsHi":["पृथ्वी की कक्षा का दीर्घवृत्ताकार आकार, जो शीत ऋतु को लंबा करता है","विषुवों का पुरस्सरण, जिसने ऋतुओं के सापेक्ष निरयण राशिचक्र को खिसका दिया है","पृथ्वी की धुरी का झुकाव, जो प्रति वर्ष अयनांत की तिथि बदलता है","चंद्रमा की कक्षा, जो चांद्र मासों को सूर्य के सापेक्ष खिसकाती है"],"explanationHi":"मकर संक्रांति सूर्य के तारों के सापेक्ष मापे गए निरयण मकर में प्रवेश को दर्शाती है। पुरस्सरण विषुवों और अयनांतों को लगभग प्रत्येक 72 वर्ष में एक अंश पश्चिम खिसकाता है, इसलिए जो अयनांत लगभग 1,500 वर्ष पहले मकर से मेल खाता था वह अब लगभग तीन सप्ताह पहले आता है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-solar-system-206","question":"India's first satellite, Aryabhata, named after the fifth-century astronomer and launched in April 1975, was put into orbit:","options":["By India's own SLV-3 rocket from the Sriharikota launch range","By an American Delta rocket from the Cape Canaveral launch complex","By a Soviet launch vehicle from a Soviet launch site","By a European Ariane rocket from the Kourou range in French Guiana"],"answer":2,"explanation":"Aryabhata, built by ISRO, was launched on 19 April 1975 on a Soviet Kosmos-3M rocket from Kapustin Yar. India's own SLV-3 achieved its first successful orbital launch with Rohini in 1980.","difficulty":"hard","questionHi":"भारत का पहला उपग्रह आर्यभट, जिसका नाम पाँचवीं सदी के खगोलविद के नाम पर रखा गया और जो अप्रैल 1975 में प्रक्षेपित हुआ, कक्षा में कैसे स्थापित किया गया?","optionsHi":["श्रीहरिकोटा से SLV-3 रॉकेट द्वारा","केप कैनावेरल से अमेरिकी रॉकेट द्वारा","सोवियत प्रक्षेपण यान द्वारा सोवियत प्रक्षेपण स्थल से","फ्रेंच गुयाना से एरियन रॉकेट द्वारा"],"explanationHi":"ISRO द्वारा निर्मित आर्यभट 19 अप्रैल 1975 को कापुस्तिन यार से सोवियत कॉसमॉस-3M रॉकेट पर प्रक्षेपित हुआ। भारत के अपने SLV-3 ने 1980 में रोहिणी के साथ पहला सफल कक्षीय प्रक्षेपण किया।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-207","question":"Jezero crater, where NASA's Perseverance rover landed in February 2021 to search for signs of ancient life, is on:","options":["Venus","Titan","The Moon","Mars"],"answer":3,"explanation":"Jezero is a crater of about 45 km across on Mars, where orbital images show an ancient lake and river delta, a good place to look for preserved biosignatures. The rover collects rock cores for a planned return to Earth.","difficulty":"moderate","questionHi":"जेज़ेरो गड्ढा, जहाँ नासा का परसेवरेंस रोवर फरवरी 2021 में प्राचीन जीवन के चिह्न खोजने के लिए उतरा, कहाँ है?","optionsHi":["शुक्र","टाइटन","चंद्रमा","मंगल"],"explanationHi":"जेज़ेरो मंगल पर लगभग 45 km चौड़ा गड्ढा है, जहाँ कक्षीय चित्र प्राचीन झील और नदी डेल्टा दिखाते हैं, जो सुरक्षित जैव-चिह्न खोजने की अच्छी जगह है। रोवर चट्टानों के कोर एकत्र करता है जिन्हें पृथ्वी पर लौटाने की योजना है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-208","question":"How many humans have walked on the surface of the Moon, in the Apollo landings between 1969 and 1972?","options":["12","24","6","10"],"answer":0,"explanation":"Six Apollo missions landed (Apollo 11, 12, 14, 15, 16 and 17), each putting two astronauts on the surface, so twelve people in all. Apollo 13 did not land, and the last to walk was Apollo 17 in December 1972.","difficulty":"moderate","questionHi":"1969 से 1972 के बीच अपोलो अवतरणों में कितने मनुष्य चंद्रमा की सतह पर चल चुके हैं?","optionsHi":["12","24","6","10"],"explanationHi":"छह अपोलो अभियान (अपोलो 11, 12, 14, 15, 16 और 17) उतरे, प्रत्येक ने दो अंतरिक्ष यात्रियों को सतह पर उतारा, इसलिए कुल बारह लोग। अपोलो 13 नहीं उतरा, और सतह पर चलने वाला अंतिम अभियान दिसंबर 1972 का अपोलो 17 था।","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-solar-system-209","question":"The International Space Station orbits the Earth in about 93 minutes. The number of sunrises its crew sees in a day is about:","options":["24","16","8","1"],"answer":1,"explanation":"In 24 hours the station completes 1,440/93 = about 15.5 orbits, and each orbit brings a sunrise and a sunset, so the crew sees about 16 of each in a day.","difficulty":"moderate","questionHi":"अंतर्राष्ट्रीय अंतरिक्ष स्टेशन पृथ्वी की परिक्रमा लगभग 93 मिनट में करता है। एक दिन में उसके यात्री लगभग कितने सूर्योदय देखते हैं?","optionsHi":["24","16","8","1"],"explanationHi":"24 घंटे में स्टेशन 1,440/93 = लगभग 15.5 परिक्रमाएँ पूरी करता है, और प्रत्येक परिक्रमा में एक सूर्योदय और एक सूर्यास्त होता है, इसलिए यात्री एक दिन में लगभग 16-16 देखते हैं।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-solar-system-210","question":"At the height of about 400 km, where the International Space Station orbits, the Earth's gravitational pull is about what share of its value at the surface, taking the Earth's radius as 6,371 km?","options":["50%","11%","89%","0%"],"answer":2,"explanation":"Gravity falls as the inverse square of distance from the centre: (6,371/6,771)^2 = 0.885, about 89%. Astronauts float not because gravity is absent but because they are in continuous free fall around the Earth.","difficulty":"hard","questionHi":"लगभग 400 km की ऊँचाई पर, जहाँ अंतर्राष्ट्रीय अंतरिक्ष स्टेशन परिक्रमा करता है, पृथ्वी की त्रिज्या 6,371 km मानने पर, पृथ्वी का गुरुत्वाकर्षण सतह पर उसके मान का लगभग कितना भाग है?","optionsHi":["50%","11%","89%","0%"],"explanationHi":"गुरुत्व केंद्र से दूरी के वर्ग के व्युत्क्रम से घटता है: (6,371/6,771)^2 = 0.885, यानी लगभग 89%। अंतरिक्ष यात्री इसलिए नहीं तैरते कि गुरुत्व नहीं है, बल्कि इसलिए कि वे पृथ्वी के चारों ओर लगातार मुक्त पतन में हैं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-211","question":"The slow advance of Mercury's perihelion, about 43 arcseconds a century more than Newtonian gravity predicts, was finally explained in 1915 by:","options":["The tidal friction between Mercury and the Sun","The pull of an undiscovered inner planet called Vulcan","Newton's third law applied to the Sun and Mercury","Einstein's general theory of relativity"],"answer":3,"explanation":"Le Verrier had suggested an unseen planet, Vulcan, but none was found. Einstein's general relativity, in which space-time near the Sun is curved, gave exactly the extra 43 arcseconds a century, and was an early success of the theory.","difficulty":"very-hard","questionHi":"बुध के उपसौर की धीमी अग्रगति, जो न्यूटनी गुरुत्व की भविष्यवाणी से प्रति शताब्दी लगभग 43 चाप-सेकंड अधिक है, की व्याख्या अंततः 1915 में किसने की?","optionsHi":["बुध और सूर्य के बीच ज्वारीय घर्षण ने","वल्कन नामक अनदेखे आंतरिक ग्रह के खिंचाव ने","सूर्य और बुध पर लगाए गए न्यूटन के तीसरे नियम ने","आइंस्टीन के सामान्य सापेक्षता सिद्धांत ने"],"explanationHi":"ले वेरिये ने वल्कन नामक अनदेखे ग्रह का सुझाव दिया था, पर कोई नहीं मिला। आइंस्टीन के सामान्य सापेक्षता सिद्धांत, जिसमें सूर्य के पास दिक्-काल वक्र है, ने ठीक अतिरिक्त 43 चाप-सेकंड प्रति शताब्दी दिए, और यह सिद्धांत की आरंभिक सफलता थी।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-212","question":"Ceres was discovered in 1801 by Giuseppe Piazzi while astronomers were searching the gap between Mars and Jupiter indicated by which rule?","options":["The Titius-Bode law","Kepler's third law","The Roche limit","Hubble's law"],"answer":0,"explanation":"The Titius-Bode rule, an empirical sequence of planetary distances, suggested a missing planet at about 2.8 AU, and Ceres turned up near that distance. The rule fails for Neptune, and it is not a law of physics.","difficulty":"hard","questionHi":"सेरेस की खोज 1801 में ज्यूसेप पियाज़ी ने तब की जब खगोलविद मंगल और बृहस्पति के बीच के उस अंतराल को खोज रहे थे जो किस नियम द्वारा संकेतित था?","optionsHi":["टाइटियस–बोड नियम","केप्लर का तीसरा नियम","रोश सीमा","हबल का नियम"],"explanationHi":"टाइटियस–बोड नियम, ग्रहों की दूरियों का एक आनुभविक अनुक्रम, ने लगभग 2.8 AU पर एक लुप्त ग्रह का संकेत दिया, और सेरेस उसी दूरी के पास मिला। यह नियम नेपच्यून के लिए विफल रहता है और भौतिकी का नियम नहीं है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-213","question":"Among the eight planets, which has the most eccentric (least circular) orbit, with an eccentricity of about 0.21?","options":["Neptune","Mercury","Venus","Mars"],"answer":1,"explanation":"Mercury's orbit has an eccentricity of about 0.21, so its distance from the Sun varies from 0.31 to 0.47 AU. Mars is next at 0.09, while Venus (0.007) and Neptune (0.009) have nearly circular orbits.","difficulty":"hard","questionHi":"आठ ग्रहों में किसकी कक्षा सबसे अधिक उत्केंद्रीय (सबसे कम वृत्ताकार) है, जिसकी उत्केन्द्रता लगभग 0.21 है?","optionsHi":["नेपच्यून","बुध","शुक्र","मंगल"],"explanationHi":"बुध की कक्षा की उत्केन्द्रता लगभग 0.21 है, इसलिए सूर्य से उसकी दूरी 0.31 से 0.47 AU तक बदलती है। मंगल 0.09 पर अगला है, जबकि शुक्र (0.007) और नेपच्यून (0.009) की कक्षाएँ लगभग वृत्ताकार हैं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-solar-system-214","question":"A nearby star shows an annual parallax of 0.25 arcsecond. Its distance is:","options":["25 parsecs, about 82 light-years","0.25 parsec, about 0.8 light-year","4 parsecs, about 13 light-years","4 light-years, about 1.2 parsecs"],"answer":2,"explanation":"Distance in parsecs is 1/parallax in arcseconds = 1/0.25 = 4 pc, and 1 parsec is 3.26 light-years, so 4 pc is about 13 light-years. Taking the answer as 4 light-years confuses parsecs with light-years.","difficulty":"hard","questionHi":"किसी निकट तारे का वार्षिक लंबन 0.25 चाप-सेकंड है। उसकी दूरी है:","optionsHi":["25 पारसेक, लगभग 82 प्रकाश-वर्ष","0.25 पारसेक, लगभग 0.8 प्रकाश-वर्ष","4 पारसेक, लगभग 13 प्रकाश-वर्ष","4 प्रकाश-वर्ष, लगभग 1.2 पारसेक"],"explanationHi":"पारसेक में दूरी = 1/लंबन (चाप-सेकंड में) = 1/0.25 = 4 pc, और 1 पारसेक 3.26 प्रकाश-वर्ष है, इसलिए 4 pc लगभग 13 प्रकाश-वर्ष है। उत्तर को 4 प्रकाश-वर्ष मानना पारसेक और प्रकाश-वर्ष को भ्रमित करना है।","source":"UPSC Prelims · UGC NET style"},
];

